import create from 'zustand';
import { Template } from '../types/templates';

interface TemplatesStoreState {
  templates: Template[];

  setTemplates: (arr: Template[]) => void;
}

const useTemplateStore = create<TemplatesStoreState>((set) => ({
  templates: [],

  setTemplates(arr: Template[]) {
    set(() => ({ templates: arr }));
  },
}));

export default useTemplateStore;
