import { ButtonBase, Typography } from '@mui/material';
import React from 'react';
import { useTranslation } from 'react-i18next';
import { makeStyles } from 'tss-react/mui';
import { TooltipContentType } from '../../../enums/enums';
import { Colors } from '../../../theme/theme';
import { GrammarReplacement, ISuggestionItem, Paraphrase } from '../../../types/augmentedWriting';
import GrammarContent from './GrammarContent';
import ParaphraseContent from './ParaphraseContent';

interface Props {
  suggestion: ISuggestionItem;

  skipSuggestion(content: any): () => void;

  ignoreSuggestion(content: any, id: string): () => void;

  insertAtPosition: (word: string, highlightId: string, type: TooltipContentType) => void;
}

const SuggestionCard: React.FC<Props> = ({ suggestion, skipSuggestion, ignoreSuggestion, insertAtPosition }) => {
  const { classes } = useStyles();
  const { t } = useTranslation();

  return (
    <div className={classes.suggestionCard}>
      <Typography className={classes.title}>
        {suggestion.contentType === TooltipContentType.GRAMMAR_REPLACEMENT ? t('grammarOptimization') : t('paiMatchOptimization')}
      </Typography>
      <div className={classes.content}>
        {suggestion.contentType === TooltipContentType.GRAMMAR_REPLACEMENT ? (
          <GrammarContent grammarReplacement={suggestion.content as GrammarReplacement} insertAtPosition={insertAtPosition} />
        ) : (
          <ParaphraseContent paraphrase={suggestion.content as Paraphrase} insertAtPosition={insertAtPosition} />
        )}
      </div>
      <div className={classes.actions}>
        <ButtonBase onClick={skipSuggestion(suggestion.content)}>
          <Typography className={classes.actionText}>{t('ignoreOnce')}</Typography>
        </ButtonBase>
        <ButtonBase className={classes.hasLeft} onClick={ignoreSuggestion(suggestion.content, suggestion.highlightId)}>
          <Typography className={classes.actionText}>{t('alwaysIgnore')}</Typography>
        </ButtonBase>
      </div>
    </div>
  );
};

const useStyles = makeStyles()((theme) => ({
  suggestionCard: {
    width: '100%',
    background: '#FFF',
  },
  title: {
    fontSize: '13px',
    fontWeight: 'bold',
    textTransform: 'uppercase',
    textAlign: 'center',
    paddingTop: '8px',
  },
  actions: {
    display: 'flex',
    justifyContent: 'center',
    padding: '4px',
  },
  hasLeft: {
    marginLeft: '16px',
  },
  actionText: {
    fontSize: '11px',
    textDecoration: 'underline',
    color: Colors.GREY_SHADE_4,
    '&:hover': {
      color: theme.palette.primary.main,
      textDecoration: 'underline',
    },
  },
  content: {
    padding: '8px 16px',
    borderBottom: `1px solid ${Colors.GREY_SHADE_1}`,
  },
}));

export default SuggestionCard;
