import { Typography } from '@mui/material';
import _ from 'lodash';
import React from 'react';
import { useTranslation } from 'react-i18next';
import { makeStyles } from 'tss-react/mui';
import { Shadows } from '../../theme/theme';
import { getLogos } from '../../utils/imageUtils';
import {
  isLinkedInRecThreadsPage,
  isLinkedInRecUserPage,
  isLinkedInSalesNavThreadsPage,
  isLinkedInSalesNavUserPage,
  isLinkedInSalesNavSearchLeadsPage,
  isLinkedInThreadsPage,
  isLinkedInUserPage,
} from '../../utils/linkedinUtils';

interface Props {
  authenticated?: boolean;

  openPanel(): void;
}

const ExtensionButton: React.FC<Props> = ({ authenticated, openPanel }) => {
  const { t } = useTranslation();
  const { classes } = useStyles();
  const logo = getLogos()?.product_logo_white;

  const buttonTextGenerator = () => {
    if (!_.isNil(authenticated) && !authenticated) {
      return t('loginButton');
    } else if (isLinkedInThreadsPage() || isLinkedInSalesNavThreadsPage() || isLinkedInRecThreadsPage()) {
      return t('analyzeCommunication');
    } else if (isLinkedInUserPage() || isLinkedInSalesNavUserPage() || isLinkedInSalesNavSearchLeadsPage() || isLinkedInRecUserPage()) {
      return t('capturePersonality');
    }
    return t('capturePersonality');
  };

  return (
    <div className={classes.button} onClick={openPanel}>
      <img className={classes.buttonIcon} src={logo} alt="icon" />
      <Typography className={classes.text}>{buttonTextGenerator()}</Typography>
    </div>
  );
};

const useStyles = makeStyles()((theme) => ({
  button: {
    position: 'relative',
    width: '150px',
    height: '42px',
    padding: '8px 16px',
    borderRadius: 0,
    background: theme.palette.primary.main,
    boxShadow: Shadows.BLUE_SHADOW,
    cursor: 'pointer',
    display: 'flex',
    justifyContent: 'center',
    alignItems: 'center',
    '&:hover': {
      background: theme.palette.secondary.main,
      boxShadow: Shadows.ORANGE_SHADOW,
    },
  },
  buttonIcon: {
    height: '100%',
  },
  text: {
    fontSize: '9px',
    color: '#FFF',
    whiteSpace: 'pre-wrap',
    lineHeight: 1.2,
    marginLeft: '16px',
  },
}));

export default ExtensionButton;
