import { ButtonBase, Stack, Typography } from '@mui/material';
import _ from 'lodash';
import React from 'react';
import { useTranslation } from 'react-i18next';
import { makeStyles } from 'tss-react/mui';
import { AnalysisSelection } from '../../../enums/enums';
import { Colors } from '../../../theme/theme';

interface Props {
  selectedAnalysis: AnalysisSelection;

  handleSelectedAnalysisChange(newSelection: AnalysisSelection): () => void;
}

const AnalysisSelectionBar: React.FC<Props> = ({ selectedAnalysis, handleSelectedAnalysisChange }) => {
  const { classes, cx } = useStyles();
  const { t } = useTranslation();

  return (
    <div className={classes.selectionBar}>
      <Stack direction={'row'} flexWrap={'nowrap'} justifyContent={'center'} gap={3}>
        {_.map(AnalysisSelection, (selection) => (
          <ButtonBase
            key={selection}
            className={cx(classes.selectionItem, selectedAnalysis === selection ? 'active' : null)}
            disableRipple={true}
            onClick={handleSelectedAnalysisChange(selection)}
          >
            <Typography className={classes.selectionItemText}>{t(selection)}</Typography>
          </ButtonBase>
        ))}
      </Stack>
    </div>
  );
};

const useStyles = makeStyles()((theme) => ({
  selectionBar: {
    padding: '8px 0 12px 0',
    background: '#FFF',
    border: `1px solid ${theme.palette.primary.main}`,
  },
  selectionItem: {
    display: 'flex',
    justifyContent: 'center',
    alignItems: 'flex-end',
    padding: '4px 0',
    color: Colors.GREY_SHADE_5,
    borderBottom: `2px solid ${Colors.GREY_SHADE_5}`,
    '&.active': {
      color: theme.palette.primary.main,
      borderBottom: `2px solid ${theme.palette.primary.main}`,
    },
  },
  selectionItemText: {
    whiteSpace: 'pre-wrap',
    fontSize: '11px',
    fontWeight: 'bold',
  },
}));

export default AnalysisSelectionBar;
