import CloseIcon from '@mui/icons-material/Close';
import { ButtonBase, Typography, darken } from '@mui/material';
import Tooltip from '@mui/material/Tooltip';
import _ from 'lodash';
import React from 'react';
import { useTranslation } from 'react-i18next';
import { makeStyles } from 'tss-react/mui';
import shallow from 'zustand/shallow';
import { TooltipContentType, ZIndices } from '../../enums/enums';
import useContainerStore from '../../stores/containerStore';
import useInteractiveTooltipStore from '../../stores/interactiveTooltipStore';
import { Colors, Shadows } from '../../theme/theme';
import { GrammarReplacement, Paraphrase } from '../../types/augmentedWriting';
import GrammarContent from '../textOptimization/Suggestion/GrammarContent';
import ParaphraseContent from '../textOptimization/Suggestion/ParaphraseContent';

interface Props {
  insertAtPosition: (word: string, highlightId: string, type: TooltipContentType) => void;

  ignoreSuggestion(content: any, id: string): () => void;
}

const InteractiveTooltip: React.FC<Props> = ({ insertAtPosition, ignoreSuggestion }) => {
  const { classes } = useStyles();
  const { t } = useTranslation();

  const tooltipContainerElement = useContainerStore((state) => state.tooltipContainer);

  const { open, anchorElement, type, suggestion, handleClose } = useInteractiveTooltipStore(
    (state) => ({
      open: state.open,
      anchorElement: state.anchorElement,
      type: state.type,
      suggestion: state.suggestion,
      handleClose: state.handleClose,
    }),
    shallow
  );

  if (_.isNil(anchorElement)) {
    return null;
  }

  const highlightId = `${type}-${suggestion?.ranking_index}`;

  return (
    <Tooltip
      classes={{ tooltip: classes.tooltip, popper: classes.popper }}
      open={open}
      PopperProps={{
        anchorEl: anchorElement,
        container: tooltipContainerElement,
      }}
      title={
        <div className={classes.interactiveTooltip}>
          <ButtonBase
            className={classes.closeButton}
            onClick={(event) => {
              event.preventDefault();
              event.stopPropagation();
              handleClose();
            }}
          >
            <CloseIcon className={classes.closeIcon} />
          </ButtonBase>
          <Typography className={classes.title}>
            {type === TooltipContentType.GRAMMAR_REPLACEMENT ? t('grammarOptimization') : t('paiMatchOptimization')}
          </Typography>
          <div className={classes.content}>
            {type === TooltipContentType.GRAMMAR_REPLACEMENT ? (
              <GrammarContent grammarReplacement={suggestion as GrammarReplacement} insertAtPosition={insertAtPosition} />
            ) : (
              <ParaphraseContent paraphrase={suggestion as Paraphrase} insertAtPosition={insertAtPosition} />
            )}
          </div>
          <div className={classes.actions}>
            <div />
            <ButtonBase
              onClick={(event) => {
                event.preventDefault();
                event.stopPropagation();
                ignoreSuggestion(suggestion, highlightId)();
                handleClose();
              }}
            >
              <Typography className={classes.actionText}>{t('alwaysIgnore')}</Typography>
            </ButtonBase>
          </div>
        </div>
      }
    >
      <span />
    </Tooltip>
  );
};

const useStyles = makeStyles()((theme) => ({
  tooltip: {
    borderRadius: 0,
    color: 'black',
    background: 'white',
    boxShadow: Shadows.NORMAL_SHADOW,
    width: '275px',
    padding: 0,
  },
  popper: {
    zIndex: ZIndices.TOOLTIP,
  },
  interactiveTooltip: {
    width: '100%',
    background: '#FFF',
    position: 'relative',
  },
  closeButton: {
    position: 'absolute',
    right: '8px',
    top: '8px',
  },
  closeIcon: {
    fontSize: '16px',
    color: '#000',
  },
  title: {
    fontSize: '13px',
    fontWeight: 'bold',
    textTransform: 'uppercase',
    textAlign: 'center',
    paddingTop: '8px',
  },
  content: {
    padding: '8px 16px',
    borderBottom: `1px solid ${Colors.GREY_SHADE_1}`,
    maxHeight: '66dvh',
    overflow: 'auto',
    overflowX: 'hidden',
    '&::-webkit-scrollbar': {
      width: '6px',
    },
    '&::-webkit-scrollbar-track': {
      background: '#FFF',
    },
    '&::-webkit-scrollbar-thumb': {
      background: Colors.GREY_SHADE_1,
      '&:hover': {
        background: darken(Colors.GREY_SHADE_1, 0.25),
      },
    },
  },
  actions: {
    display: 'flex',
    justifyContent: 'center',
    padding: '4px',
  },
  actionText: {
    fontSize: '11px',
    textDecoration: 'underline',
    color: Colors.GREY_SHADE_4,
    '&:hover': {
      color: theme.palette.primary.main,
      textDecoration: 'underline',
    },
  },
}));

export default InteractiveTooltip;
