import { ButtonBase, Stack, Typography } from '@mui/material';
import _ from 'lodash';
import React, { useEffect, useState } from 'react';
import { useTranslation } from 'react-i18next';
import { makeStyles } from 'tss-react/mui';
import { ApiActions, textGenerationActions } from '../../enums/actions';
import { Genres } from '../../enums/enums';
import { Colors } from '../../theme/theme';
import { sendMessageToBackground } from '../../utils/helper';
import PaiButton from '../basic/PaiButton';
import PaiTextArea from '../basic/PaiTextArea';
import EnterProjectNameDialog from './EnterProjectNameDialog';
import SaveAsProjectDialog from './SaveAsProjectDialog';

interface Props {
  genre: Genres;
  loading: boolean;

  problems?: string;
  features?: string;
  benefits?: string;
  impact?: string;

  companyDescription?: string;
  tasks?: string;
  requirements?: string;
  whyYou?: string;

  handleProblemsChange?(event: React.ChangeEvent<HTMLInputElement>): void;

  handleFeaturesChange?(event: React.ChangeEvent<HTMLInputElement>): void;

  handleBenefitsChange?(event: React.ChangeEvent<HTMLInputElement>): void;

  handleImpactChange?(event: React.ChangeEvent<HTMLInputElement>): void;

  handleCompanyDescriptionChange?(event: React.ChangeEvent<HTMLInputElement>): void;

  handleTasksChange?(event: React.ChangeEvent<HTMLInputElement>): void;

  handleRequirementsChange?(event: React.ChangeEvent<HTMLInputElement>): void;

  handleWhyYouChange?(event: React.ChangeEvent<HTMLInputElement>): void;

  createTextVariantStream(): void;

  fetchProjects(searchParam?: string): void;

  handleBackClick(): void;
}

const FirstStepCreateNewProject: React.FC<Props> = ({
  genre,
  loading,
  problems,
  features,
  benefits,
  impact,
  companyDescription,
  tasks,
  requirements,
  whyYou,
  handleProblemsChange,
  handleFeaturesChange,
  handleBenefitsChange,
  handleImpactChange,
  handleCompanyDescriptionChange,
  handleTasksChange,
  handleRequirementsChange,
  handleWhyYouChange,
  createTextVariantStream,
  fetchProjects,
  handleBackClick,
}) => {
  const { classes } = useStyles();
  const { t } = useTranslation();

  const [saveAsProjectDialog, setSaveAsProjectDialog] = useState<{ open: boolean }>({ open: false });
  const [enterProjectNameDialog, setEnterProjectNameDialog] = useState<{ open: boolean; projectName: string; nameTakenError?: boolean }>({
    open: false,
    projectName: '',
  });
  const [createProjectLoading, setCreateProjectLoading] = useState(false);

  const rowCount = 5;

  useEffect(() => {
    const messageListener = (request, sender, callback) => {
      if (request.action === textGenerationActions.CREATE_BOOSTER_PROJECT_RESPONSE) {
        setCreateProjectLoading(false);
        fetchProjects(genre);
        createTextVariantStream();
        handleCloseProjectNameDialog();
      }

      if (request.action.includes(ApiActions.ERROR) && request.action.includes(textGenerationActions.CREATE_BOOSTER_PROJECT_RESPONSE)) {
        setCreateProjectLoading(false);

        if (request.body.message !== 'project exists') {
          setEnterProjectNameDialog({ ...enterProjectNameDialog, nameTakenError: true });
        }
      }
    };

    chrome?.runtime?.onMessage.addListener(messageListener);
    return () => {
      chrome?.runtime?.onMessage.removeListener(messageListener);
    };
  }, [enterProjectNameDialog, genre, companyDescription, tasks, requirements, whyYou, problems, features, benefits, impact]);

  const textGenerationPossible = () => {
    if (genre === Genres.CONNECTION_REQUEST || genre === Genres.SALES_EMAIL) {
      return problems?.trim() !== '' && features?.trim() !== '' && benefits?.trim() !== '' && impact?.trim() !== '';
    }

    if (genre === Genres.ACTIVE_SOURCING) {
      return companyDescription?.trim() !== '' && tasks?.trim() !== '' && requirements?.trim() !== '' && whyYou?.trim() !== '';
    }

    return false;
  };

  /**
   * Save as project dialog handlers
   */

  const handleOpenSaveAsProjectDialog = () => {
    setSaveAsProjectDialog({ open: true });
  };

  const handleCloseSaveAsProjectDialog = () => {
    setSaveAsProjectDialog({ open: false });
  };

  const handleCreateTextVariant = () => {
    createTextVariantStream();
    handleCloseSaveAsProjectDialog();
  };

  /**
   * Enter project name dialog handlers
   */

  const handleOpenProjectNameDialog = () => {
    handleCloseSaveAsProjectDialog();
    setEnterProjectNameDialog({ ...enterProjectNameDialog, open: true });
  };

  const handleCloseProjectNameDialog = () => {
    setEnterProjectNameDialog({ open: false, projectName: '', nameTakenError: undefined });
  };

  const handleProjectNameChange = (event: React.ChangeEvent<HTMLInputElement>) => {
    setEnterProjectNameDialog({ ...enterProjectNameDialog, projectName: event.target.value });
  };

  const createBoosterProject = () => {
    const offerPayloadLeadBooster = {
      problems,
      features,
      benefits,
      impact,
    };
    const offerPayloadHrBooster = {
      companyDescription,
      tasks,
      requirements,
      whyYou,
    };
    const offerPayload = genre === Genres.ACTIVE_SOURCING ? offerPayloadHrBooster : offerPayloadLeadBooster;

    const creationPayload = {
      projectName: enterProjectNameDialog.projectName,
      genre,
      offer: offerPayload,
      problems: genre === Genres.ACTIVE_SOURCING ? undefined : problems,
    };

    sendMessageToBackground({ action: textGenerationActions.CREATE_BOOSTER_PROJECT_REQUEST, body: creationPayload });
  };

  const handleAcceptProjectName = () => {
    setCreateProjectLoading(true);
    createBoosterProject();
  };

  return (
    <>
      <Stack spacing={1}>
        {genre === Genres.CONNECTION_REQUEST || genre === Genres.SALES_EMAIL ? (
          <>
            {!_.isNil(problems) && !_.isNil(handleProblemsChange) ? (
              <PaiTextArea
                instruction={t('leadBoosterProblemsInstruction')}
                placeholder={t('leadBoosterProblemsPlaceholder')}
                value={problems}
                disabled={loading}
                onChange={handleProblemsChange}
                rows={rowCount}
              />
            ) : null}

            {!_.isNil(features) && !_.isNil(handleFeaturesChange) ? (
              <PaiTextArea
                instruction={t('leadBoosterFeaturesInstruction')}
                placeholder={t('leadBoosterFeaturesPlaceholder')}
                value={features}
                disabled={loading}
                onChange={handleFeaturesChange}
                rows={rowCount}
              />
            ) : null}

            {!_.isNil(benefits) && !_.isNil(handleBenefitsChange) ? (
              <PaiTextArea
                instruction={t('leadBoosterBenefitsInstruction')}
                placeholder={t('leadBoosterBenefitsPlaceholder')}
                value={benefits}
                disabled={loading}
                onChange={handleBenefitsChange}
                rows={rowCount}
              />
            ) : null}

            {!_.isNil(impact) && !_.isNil(handleImpactChange) ? (
              <PaiTextArea
                instruction={t('leadBoosterImpactInstructions')}
                placeholder={t('leadBoosterImpactPlaceholder')}
                value={impact}
                disabled={loading}
                onChange={handleImpactChange}
                rows={rowCount}
              />
            ) : null}
          </>
        ) : null}

        {genre === Genres.ACTIVE_SOURCING ? (
          <>
            {!_.isNil(companyDescription) && !_.isNil(handleCompanyDescriptionChange) ? (
              <PaiTextArea
                instruction={t('jobOfferCompanyDescriptionInstruction')}
                placeholder={t('jobOfferCompanyDescriptionPlaceholder')}
                value={companyDescription}
                disabled={loading}
                onChange={handleCompanyDescriptionChange}
                rows={rowCount}
              />
            ) : null}

            {!_.isNil(tasks) && !_.isNil(handleTasksChange) ? (
              <PaiTextArea
                instruction={t('jobOfferResponsibilitiesInstruction')}
                placeholder={t('jobOfferResponsibilitiesPlaceholder')}
                value={tasks}
                disabled={loading}
                onChange={handleTasksChange}
                rows={rowCount}
              />
            ) : null}

            {!_.isNil(requirements) && !_.isNil(handleRequirementsChange) ? (
              <PaiTextArea
                instruction={t('jobOfferRequirementsInstruction')}
                placeholder={t('jobOfferRequirementsPlaceholder')}
                value={requirements}
                disabled={loading}
                onChange={handleRequirementsChange}
                rows={rowCount}
              />
            ) : null}

            {!_.isNil(whyYou) && !_.isNil(handleWhyYouChange) ? (
              <PaiTextArea
                instruction={t('jobOfferWhyYouInstruction')}
                placeholder={t('jobOfferWhyYouPlaceholder')}
                value={whyYou}
                disabled={loading}
                onChange={handleWhyYouChange}
                rows={rowCount}
              />
            ) : null}
          </>
        ) : null}
        <Stack direction={'row'} justifyContent={'flex-end'} alignItems={'center'} gap={2}>
          <ButtonBase onClick={handleBackClick} disabled={loading}>
            <Typography className={classes.actionText}>{t('back')}</Typography>
          </ButtonBase>
          <PaiButton text={t('generateTextVariants')} disabled={!textGenerationPossible()} action={handleOpenSaveAsProjectDialog} />
        </Stack>
      </Stack>
      <SaveAsProjectDialog
        open={saveAsProjectDialog.open}
        handleCreateTextVariant={handleCreateTextVariant}
        handleOpenProjectNameDialog={handleOpenProjectNameDialog}
        handleClose={handleCloseSaveAsProjectDialog}
      />
      <EnterProjectNameDialog
        open={enterProjectNameDialog.open}
        projectName={enterProjectNameDialog.projectName}
        nameTakenError={enterProjectNameDialog.nameTakenError}
        loading={createProjectLoading}
        handleProjectNameChange={handleProjectNameChange}
        handleClose={handleCloseProjectNameDialog}
        acceptProjectName={handleAcceptProjectName}
      />
    </>
  );
};

const useStyles = makeStyles()((theme) => ({
  buttonContainer: {
    display: 'flex',
    justifyContent: 'center',
    alignItems: 'center',
  },
  actionText: {
    fontSize: '12px',
    textDecoration: 'underline',
    color: Colors.GREY_SHADE_4,
    lineHeight: 1,
    '&:hover': {
      color: theme.palette.primary.main,
      textDecoration: 'underline',
    },
  },
}));

export default FirstStepCreateNewProject;
