import { Stack } from '@mui/material';
import _ from 'lodash';
import React, { useState } from 'react';
import { AnalysisSelection } from '../../../enums/enums';
import { RelationshipQuality } from '../../../types/analysis';
import { Assessment } from '../../../types/assessment';
import { ProfileValues } from '../../../types/contact';
import AnalysisSelectionBar from './AnalysisSelectionBar';
import AnalysisSelectionContent from './AnalysisSelectionContent';
import Persona from './Persona';

interface Props {
  contactAssessment: Assessment | undefined;
  contactProfile?: ProfileValues;
  userProfile?: ProfileValues;
  relationshipQuality?: RelationshipQuality;
}

const AnalysisResults: React.FC<Props> = ({ contactAssessment, contactProfile, userProfile, relationshipQuality }) => {
  const [selectedAnalysis, setSelectedAnalysis] = useState<AnalysisSelection>(AnalysisSelection.STYLE_MATCH);

  const handleSelectedAnalysisChange = (newSelection: AnalysisSelection) => {
    return () => {
      setSelectedAnalysis(newSelection);
    };
  };

  return (
    <Stack spacing={1}>
      {!_.isNil(contactAssessment) ? <Persona assessment={contactAssessment} /> : null}
      <AnalysisSelectionBar selectedAnalysis={selectedAnalysis} handleSelectedAnalysisChange={handleSelectedAnalysisChange} />
      <AnalysisSelectionContent
        selectedAnalysis={selectedAnalysis}
        contactAssessment={contactAssessment}
        contactProfile={contactProfile}
        userProfile={userProfile}
        relationshipQuality={relationshipQuality}
      />
    </Stack>
  );
};

export default AnalysisResults;
