import { Typography } from '@mui/material';
import _ from 'lodash';
import React from 'react';
import Confetti from 'react-confetti';
import { useTranslation } from 'react-i18next';
import { makeStyles } from 'tss-react/mui';
import { Assessment } from '../../types/assessment';
import { getIllustrationUrl } from '../../utils/imageUtils';

interface Props {
  userAssessment: Assessment | undefined;
  profileName: string | undefined;
}

const UserDone: React.FC<Props> = ({ userAssessment, profileName }) => {
  const { classes } = useStyles();
  const { t } = useTranslation();

  const motiveIllustrationGenerator = () => {
    const motive = userAssessment?.name || '';
    const lowerCase = _.lowerCase(motive);
    const noGap = _.replace(lowerCase, ' ', '');

    return getIllustrationUrl(noGap);
  };

  return (
    <div className={classes.userDone}>
      <Confetti className={classes.confetti} numberOfPieces={5000} tweenDuration={125000} friction={1} gravity={0.08} recycle={false} />
      <Typography className={classes.title} align={'center'}>
        {t('congratulations')}
      </Typography>
      <Typography className={classes.text} align={'center'}>
        {t('userDoneText', { profileName })}
      </Typography>
      <div className={classes.centered}>
        <img className={classes.illustration} src={motiveIllustrationGenerator()} alt="motive illustration" />
      </div>
    </div>
  );
};

const useStyles = makeStyles()((theme) => ({
  userDone: {
    width: '100%',
    background: '#FFF',
    padding: '8px',
    position: 'relative',
    overflow: 'hidden',
    display: 'flex',
    justifyContent: 'center',
    alignItems: 'center',
    flexDirection: 'column',
  },
  title: {
    fontSize: '13px',
    fontWeight: 'bold',
    textTransform: 'uppercase',
    marginBottom: '8px',
  },
  text: {
    fontSize: '11px',
    marginBottom: '8px',
  },
  confetti: {
    width: '100%',
    height: '100%',
  },
  centered: {
    width: '100%',
    display: 'flex',
    justifyContent: 'center',
  },
  illustration: {
    width: 'auto',
    maxHeight: '85px',
  },
}));

export default UserDone;
