import { Stack } from '@mui/material';
import _ from 'lodash';
import React, { useEffect, useState } from 'react';
import { makeStyles } from 'tss-react/mui';
import shallow from 'zustand/shallow';
import { ApiActions, AugmentedWritingActions, textGenerationActions } from '../../enums/actions';
import { AWTypes, Genres, MappedGenres } from '../../enums/enums';
import i18n from '../../i18n';
import useProfileStore from '../../stores/profileStore';
import useTextGenerationStore from '../../stores/textGenerationStore';
import { Assessment } from '../../types/assessment';
import { ProfileValues } from '../../types/contact';
import { sendMessageToBackground } from '../../utils/helper';
import Persona from '../analysis/AnalysisResults/Persona';
import PaiDotLoader from '../basic/PaiDotLoader';
import FirstStepCreateFromExisting from './FirstStepCreateFromExisting';
import FirstStepCreateNewProject from './FirstStepCreateNewProject';
import SecondStepGeneratedTexts from './SecondStepGeneratedTexts';

interface Props {
  contactAssessment: Assessment | undefined;
}

export interface Project {
  _id: string;
  createDate: string;
  occupation: string;
  projectName: string;
}

export interface BoosterProject {
  _id: string;
  projectName: string;
  occupation: string;
  profile: ProfileValues;
  genre: Genres;
  offer: string;
  persona: string;
  createDate: string;
  creator: string;
  score?: number;
  text?: string;
  problems: string;
}

const GenerateText: React.FC<Props> = ({ contactAssessment }) => {
  const { classes, cx } = useStyles();

  const {
    generatedText,
    setGeneratedText,
    textVariants,
    addTextVariant,
    resetTextVariants,
    genre,
    setGenre,
    selectedLanguage,
    setSelectedLanguage,
    isFormal,
    setIsFormal,
    includeEmoji,
    setIncludeEmoji,
    selectedProject,
    setSelectedProject,
    createNew,
    setCreateNew,
    companyDescription,
    setCompanyDescription,
    requirements,
    setRequirements,
    tasks,
    setTasks,
    whyYou,
    setWhyYou,
    problems,
    setProblems,
    features,
    setFeatures,
    benefits,
    setBenefits,
    impact,
    setImpact,
  } = useTextGenerationStore(
    (state) => ({
      // general text generation states
      generatedText: state.generatedText,
      setGeneratedText: state.setGeneratedText,
      textVariants: state.textVariants,
      addTextVariant: state.addTextVariant,
      resetTextVariants: state.resetTextVariants,
      // text generation selectable states
      genre: state.genre,
      setGenre: state.setGenre,
      selectedLanguage: state.selectedLanguage,
      setSelectedLanguage: state.setSelectedLanguage,
      isFormal: state.isFormal,
      setIsFormal: state.setIsFormal,
      includeEmoji: state.includeEmoji,
      setIncludeEmoji: state.setIncludeEmoji,
      selectedProject: state.selectedProject,
      setSelectedProject: state.setSelectedProject,
      // create new text project states
      createNew: state.createNew,
      setCreateNew: state.setCreateNew,
      companyDescription: state.companyDescription,
      setCompanyDescription: state.setCompanyDescription,
      requirements: state.requirements,
      setRequirements: state.setRequirements,
      tasks: state.tasks,
      setTasks: state.setTasks,
      whyYou: state.whyYou,
      setWhyYou: state.setWhyYou,
      problems: state.problems,
      setProblems: state.setProblems,
      features: state.features,
      setFeatures: state.setFeatures,
      benefits: state.benefits,
      setBenefits: state.setBenefits,
      impact: state.impact,
      setImpact: state.setImpact,
    }),
    shallow
  );

  const firstStepDone = generatedText !== '';

  const [projectsLoading, setProjectsLoading] = useState(false);
  const [textGenerationLoading, setTextGenerationLoading] = useState(false);
  const contact = useProfileStore((state) => state.contact);
  const [projects, setProjects] = useState<BoosterProject[]>([]);

  const [analysisLoading, setAnalysisLoading] = useState<boolean>(false);
  const [score, setScore] = useState<number | null>(null);
  const [formatTextLoading, setFormatTextLoading] = useState(false);
  const [showSuccess, setShowSuccess] = useState(false);

  const loading = textGenerationLoading || analysisLoading || formatTextLoading;

  const domain: AWTypes = MappedGenres[genre || 'default'];
  const language = i18n.languages[0];

  useEffect(() => {
    const messageListener = (request, sender, callback) => {
      if (request.action === textGenerationActions.GET_BOOSTER_PROJECTS_RESPONSE) {
        const tempBoosterProjects = request.body.response;
        const filteredBoosterProjects = _.filter(tempBoosterProjects, (tbp) => tbp.offer);

        if (!_.isNil(filteredBoosterProjects)) {
          setProjects(filteredBoosterProjects);

          if (!_.isEmpty(filteredBoosterProjects)) {
            if (!_.isNil(selectedProject) && filteredBoosterProjects.some((project) => project._id === selectedProject._id)) {
              setSelectedProject(selectedProject);
            } else {
              setSelectedProject(filteredBoosterProjects[0]);
            }
          } else {
            setSelectedProject(null);
          }
        } else {
          setProjects([]);
          setSelectedProject(null);
        }

        setProjectsLoading(false);
      }

      if (request.action === textGenerationActions.CREATE_TEXT_GENERATION_STREAM_ERROR) {
        console.error(request.body);
        setTextGenerationLoading(false);
      }

      if (request.action === textGenerationActions.CREATE_TEXT_GENERATION_STREAM_END) {
        setTextGenerationLoading(false);

        const text = request.body.text;

        if (text !== '') {
          addTextVariant(text);
          analyzeTextQuick(text);
        }
      }

      if (request.action === textGenerationActions.CREATE_TEXT_GENERATION_STREAM_RESPONSE) {
        const newGeneratedTextRes = request.body;
        setGeneratedText(newGeneratedTextRes.text);
      }

      if (request.action === AugmentedWritingActions.QUICK_OPTIMIZATION) {
        const { lang, profile, domain } = request.requestBody;
        const text = request.body.text;
        const score = request.body.match;
        let count = request.count + 1;

        setGeneratedText(text);

        if (score < 0.98 && count <= 10) {
          setScore(score);
          sendMessageToBackground({ action: AugmentedWritingActions.QUICK_OPTIMIZATION, body: { lang, profile, text, domain }, count });
        } else {
          setScore(1);
          setAnalysisLoading(false);

          setFormatTextLoading(true);
          sendMessageToBackground({ action: AugmentedWritingActions.FORMAT_TEXT, body: { text, includeEmoji: includeEmoji } });
        }
      }

      if (request.action === AugmentedWritingActions.FORMAT_TEXT) {
        setFormatTextLoading(false);
        setGeneratedText(request.body.text);
        setShowSuccess(true);
      }

      if (request.action.includes(ApiActions.ERROR)) {
        setProjectsLoading(false);
        setAnalysisLoading(false);
        setTextGenerationLoading(false);
        setFormatTextLoading(false);
      }
    };

    chrome?.runtime?.onMessage.addListener(messageListener);
    return () => {
      chrome?.runtime?.onMessage.removeListener(messageListener);
    };
  }, [selectedProject, includeEmoji]);

  const fetchProjects = async (searchParam?: string) => {
    setProjectsLoading(true);
    sendMessageToBackground({
      action: textGenerationActions.GET_BOOSTER_PROJECTS_REQUEST,
      body: { searchParam },
    });
  };

  useEffect(() => {
    fetchProjects(genre);
  }, [genre]);

  const selectedProjectChange = (event: React.ChangeEvent<HTMLInputElement>) => {
    const foundProject = _.find(projects, (p) => p._id === event.target.value);
    if (foundProject) {
      setSelectedProject(foundProject);
    }
  };

  const selectedGenreChange = (event: React.ChangeEvent<HTMLInputElement>) => {
    setGenre(event.target.value as Genres);
  };

  const selectedLanguageChange = (event: React.ChangeEvent<HTMLInputElement>) => {
    setSelectedLanguage(event.target.value);
  };

  const handleIsFormalChange = (event: React.ChangeEvent<HTMLInputElement>) => {
    setIsFormal(event.target.checked);
  };

  const handleIncludeEmojiChange = (event: React.ChangeEvent<HTMLInputElement>) => {
    setIncludeEmoji(event.target.checked);
  };

  const createTextVariantStream = async () => {
    setTextGenerationLoading(true);
    const offerPayloadLeadBooster = {
      problems,
      features,
      benefits,
      impact,
    };
    const offerPayloadHrBooster = {
      companyDescription,
      tasks,
      requirements,
      whyYou,
    };
    const offerPayload = createNew
      ? genre === Genres.ACTIVE_SOURCING
        ? offerPayloadHrBooster
        : offerPayloadLeadBooster
      : selectedProject?.offer
      ? JSON.parse(selectedProject?.offer)
      : undefined;
    sendMessageToBackground({
      action: textGenerationActions.CREATE_TEXT_GENERATION_STREAM_REQUEST,
      body: {
        profile: contact?.profile,
        offer: offerPayload,
        genre: genre,
        occupation: contact?.occupation,
        problems: createNew ? (problems !== '' ? problems : undefined) : selectedProject?.problems,
        textVariants,
        globalContact: contact?.globalContact,
        dataLang: selectedLanguage,
        includeEmoji,
        isFormal,
      },
    });
  };

  const copyGeneratedText = (text: string) => {
    return async () => {
      try {
        await navigator.clipboard.writeText(text);
      } catch (e) {
        console.log(e);
      }
    };
  };

  const resetTextGenCredentials = () => {
    setCompanyDescription('');
    setTasks('');
    setRequirements('');
    setWhyYou('');

    setProblems('');
    setFeatures('');
    setBenefits('');
    setImpact('');
  };

  const handleBackClick = () => {
    if (createNew) {
      if (firstStepDone) {
        setGeneratedText('');
        setScore(null);
        setShowSuccess(false);
        resetTextVariants();
      } else {
        setCreateNew(false);
        resetTextGenCredentials();
      }
    } else {
      setGeneratedText('');
      setScore(null);
      setShowSuccess(false);
      resetTextVariants();
    }
  };

  const handleCreateNewClick = () => {
    setCreateNew(true);
  };

  /**
   * Sales Email & Connection Request Text generation handlers
   */

  const handleProblemsChange = (event: React.ChangeEvent<HTMLInputElement>) => {
    setProblems(event.target.value);
  };

  const handleFeaturesChange = (event: React.ChangeEvent<HTMLInputElement>) => {
    setFeatures(event.target.value);
  };

  const handleBenefitsChange = (event: React.ChangeEvent<HTMLInputElement>) => {
    setBenefits(event.target.value);
  };

  const handleImpactChange = (event: React.ChangeEvent<HTMLInputElement>) => {
    setImpact(event.target.value);
  };

  /**
   * Active Sourcing Text generation handlers
   */

  const handleCompanyDescriptionChange = (event: React.ChangeEvent<HTMLInputElement>) => {
    setCompanyDescription(event.target.value);
  };

  const handleRequirementsChange = (event: React.ChangeEvent<HTMLInputElement>) => {
    setRequirements(event.target.value);
  };

  const handleTasksChange = (event: React.ChangeEvent<HTMLInputElement>) => {
    setTasks(event.target.value);
  };

  const handleWhyYouChange = (event: React.ChangeEvent<HTMLInputElement>) => {
    setWhyYou(event.target.value);
  };

  /**
   * Quick optimization
   */

  const analyzeTextQuick = (text: string) => {
    setAnalysisLoading(true);
    setShowSuccess(false);

    const profile = contact?.profile;

    if (!_.isNil(profile)) {
      let count = 1;

      sendMessageToBackground({ action: AugmentedWritingActions.QUICK_OPTIMIZATION, body: { lang: language, profile, text, domain }, count });
    }
  };

  return (
    <Stack gap={1}>
      <Persona assessment={contactAssessment} showSuccess={showSuccess} />
      <div className={cx(classes.card, loading ? 'dense' : null)}>
        {projectsLoading ? (
          <PaiDotLoader />
        ) : !firstStepDone ? (
          createNew ? (
            <FirstStepCreateNewProject
              genre={genre}
              loading={textGenerationLoading || projectsLoading}
              problems={problems}
              features={features}
              benefits={benefits}
              impact={impact}
              companyDescription={companyDescription}
              tasks={tasks}
              requirements={requirements}
              whyYou={whyYou}
              handleProblemsChange={handleProblemsChange}
              handleFeaturesChange={handleFeaturesChange}
              handleBenefitsChange={handleBenefitsChange}
              handleImpactChange={handleImpactChange}
              handleCompanyDescriptionChange={handleCompanyDescriptionChange}
              handleRequirementsChange={handleRequirementsChange}
              handleTasksChange={handleTasksChange}
              handleWhyYouChange={handleWhyYouChange}
              createTextVariantStream={createTextVariantStream}
              fetchProjects={fetchProjects}
              handleBackClick={handleBackClick}
            />
          ) : (
            <FirstStepCreateFromExisting
              projects={projects}
              selectedGenreChange={selectedGenreChange}
              createTextVariantStream={createTextVariantStream}
              genre={genre}
              selectedLanguage={selectedLanguage}
              isFormal={isFormal}
              includeEmoji={includeEmoji}
              selectedProject={selectedProject}
              handleCreateNewClick={handleCreateNewClick}
              selectedProjectChange={selectedProjectChange}
              selectedLanguageChange={selectedLanguageChange}
              handleIsFormalChange={handleIsFormalChange}
              handleIncludeEmojiChange={handleIncludeEmojiChange}
            />
          )
        ) : (
          <SecondStepGeneratedTexts
            generatedText={generatedText}
            score={score}
            textGenerationLoading={textGenerationLoading}
            analysisLoading={analysisLoading}
            formatTextLoading={formatTextLoading}
            textVariants={textVariants}
            copyGeneratedText={copyGeneratedText}
            handleBackClick={handleBackClick}
            createTextVariantStream={createTextVariantStream}
          />
        )}
      </div>
    </Stack>
  );
};

const useStyles = makeStyles()((_theme) => ({
  card: {
    width: '100%',
    background: '#FFF',
    padding: '16px 8px 8px',
    '&.dense': {
      padding: '8px',
    },
  },
}));

export default GenerateText;
