import _ from 'lodash';
import create from 'zustand';
import { Modes } from '../enums/enums';

interface PanelStoreState {
  open: boolean;
  collapsed: boolean;
  attached: boolean;
  clickTrigger: boolean;
  mode: Modes;

  togglePanel: (open: boolean) => void;

  collapsePanel: () => void;

  setClickTrigger: (trigger: boolean) => void;

  setMode: (mode: Modes) => void;

  setAttachment: (attached: boolean) => void;
}

const localStorageKey = 'pai-attached';
const storedBool = localStorage.getItem(localStorageKey);
const attachedBool = !_.isNil(storedBool) ? JSON.parse(storedBool) : true;

const usePanelStore = create<PanelStoreState>((set, get) => ({
  open: false,
  collapsed: false,
  attached: attachedBool,
  clickTrigger: false,
  mode: Modes.CONTACT_ANALYSIS,

  togglePanel(open: boolean) {
    set(() => ({ open }));
  },

  collapsePanel() {
    const state = get();
    set(() => ({ collapsed: !state.collapsed }));
  },

  setClickTrigger(trigger: boolean) {
    set(() => ({ clickTrigger: trigger }));
  },

  setMode(mode) {
    set(() => ({ mode }));
  },

  setAttachment(attached: boolean) {
    set(() => ({ attached }));
    localStorage.setItem(localStorageKey, JSON.stringify(attached));
  },
}));

export default usePanelStore;
