import create from 'zustand';

export enum UserLanguages {
  DE = 'de',
  EN = 'en',
}

interface LanguageStoreState {
  userLanguage: UserLanguages | null;

  setUserLanguage: (newLang: UserLanguages) => void;
}

const useLanguageStore = create<LanguageStoreState>((set) => ({
  userLanguage: null,

  setUserLanguage(newLang: UserLanguages) {
    set(() => ({ userLanguage: newLang }));
  },
}));

export default useLanguageStore;
