import ScopedCssBaseline from '@mui/material/ScopedCssBaseline';
import { ThemeProvider } from '@mui/material/styles';
import useResizeObserver from '@react-hook/resize-observer';
import $ from 'jquery';
import _ from 'lodash';
import React, { useEffect, useRef, useState } from 'react';
import shallow from 'zustand/shallow';
import HighlightRenderer from '../components/highlighter/HighlightRenderer';
import WrappedJssComponent from '../components/ui/WrappedJssComponent';
import { ApiActions, AugmentedWritingActions, GeneralActions } from '../enums/actions';
import { AWTriggers, AWTypes, Ids, Modes, Sources, TooltipContentType } from '../enums/enums';
import i18n from '../i18n';
import useAugmentedWritingStore from '../stores/augmentedWritingStore';
import useElementStore from '../stores/elementStore';
import useInteractiveTooltipStore from '../stores/interactiveTooltipStore';
import useLanguageStore from '../stores/languageStore';
import usePanelStore from '../stores/panelStore';
import useProfileStore from '../stores/profileStore';
import theme from '../theme/theme';
import {
  Deletion,
  DiagnosticMode,
  GrammarReplacement,
  HighlightTexts,
  HighlightType,
  ISuggestionItem,
  Insertion,
  Paraphrase,
  Suggestion,
} from '../types/augmentedWriting';
import { getMostInnerTextNode, getTextFromActiveElement, sendMessageToBackground } from '../utils/helper';

const Highlighter: React.FC = () => {
  const userLanguage = useLanguageStore((state) => state.userLanguage);
  const lang = !_.isNil(userLanguage) ? userLanguage : i18n.languages[0];
  const { contact } = useProfileStore((state) => ({ contact: state.contact }), shallow);
  const { analysisLoading, setAnalysisLoading, fingerprints } = useAugmentedWritingStore(
    (state) => ({ analysisLoading: state.analysisLoading, setAnalysisLoading: state.setAnalysisLoading, fingerprints: state.fingerprints }),
    shallow
  );
  const setMode = usePanelStore((state) => state.setMode);
  const contactAssessment = contact?.assessment;
  const activeElement = useElementStore((state) => state.activeElement);
  const handleClose = useInteractiveTooltipStore((state) => state.handleClose);

  const [windowScrollY, setWindowScrollY] = useState(0);
  const [resizeWindow, setResizeWindow] = useState<{ height: number; width: number }>({ height: 0, width: 0 });
  const [resizeElement, setResizeElement] = useState<{ height: number; width: number }>({ height: 0, width: 0 });

  const [highlights, setHighlights] = useState<HighlightType[]>([]);
  const [grammarReplacements, setGrammarReplacements] = useState<GrammarReplacement[]>([]);
  const [paraphrases, setParaphrases] = useState<Paraphrase[]>([]);

  const [tempHighlights, setTempHighlights] = useState<HighlightType[]>([]);
  const [tempGrammarReplacements, setTempGrammarReplacements] = useState<GrammarReplacement[]>([]);
  const [tempParaphrases, setTempParaphrases] = useState<Paraphrase[]>([]);

  const [highlightTexts, setHighlightTexts] = useState<HighlightTexts>();
  const [modifiedHighlightTexts, setModifiedHighlightTexts] = useState<HighlightTexts>();

  const [diagnosticMode, setDiagnosticMode] = useState<DiagnosticMode>({
    active: false,
    category: '',
    composedCategory: [],
    locked: false,
    source: Sources.NONE,
  });

  const [firstSuggestion, setFirstSuggestion] = useState<ISuggestionItem>();

  const [typingTimer, setTypingTimer] = useState<ReturnType<typeof setTimeout> | null>(null);
  const textRef = useRef<string>('');

  const myObserver = useResizeObserver(activeElement, (entry) => {
    const rect = entry.contentRect;
    setResizeElement({ height: rect.height, width: rect.width });
  });

  useEffect(() => {
    if (!_.isNil(activeElement)) {
      myObserver.observe(activeElement);
    }

    return () => {
      myObserver?.disconnect();
    };
  }, [activeElement]);

  const selectionStartsInHighlight = (
    start: number,
    highlight: HighlightType | Deletion | Suggestion | Insertion | GrammarReplacement | Paraphrase
  ) => {
    return start > highlight.highlightPosition[0] && start < highlight.highlightPosition[1];
  };

  const selectionEndsInHighlight = (end: number, highlight: HighlightType | Deletion | Suggestion | Insertion | GrammarReplacement | Paraphrase) => {
    return end > highlight.highlightPosition[0] && end < highlight.highlightPosition[1];
  };

  const selectionsWrapsHighlight = (
    start: number,
    end: number,
    highlight: HighlightType | Deletion | Suggestion | Insertion | GrammarReplacement | Paraphrase
  ) => {
    return start <= highlight.highlightPosition[0] && end >= highlight.highlightPosition[1];
  };

  const highlightAfterSelectionStart = (
    start: number,
    end: number,
    highlight: HighlightType | Deletion | Suggestion | Insertion | GrammarReplacement | Paraphrase
  ) => {
    return highlight.highlightPosition[0] >= start;
  };

  const setTemporaryHighlights = (
    updateHighlights: HighlightType[],
    updateGrammarReplacements: GrammarReplacement[],
    updateParaphrases: Paraphrase[]
  ) => {
    setTempHighlights(updateHighlights.filter((highlight) => highlight.highlightPosition[0] !== 0 && highlight.highlightPosition[1] !== 0));
    setTempGrammarReplacements(
      updateGrammarReplacements.filter((highlight) => highlight.highlightPosition[0] !== 0 && highlight.highlightPosition[1] !== 0)
    );
    setTempParaphrases(updateParaphrases.filter((highlight) => highlight.highlightPosition[0] !== 0 && highlight.highlightPosition[1] !== 0));
  };

  const textAreaKeyPressEventListener = (event: any) => {
    let selectionStart = (activeElement as HTMLTextAreaElement).selectionStart;
    let selectionEnd = (activeElement as HTMLTextAreaElement).selectionEnd;

    const updateHighlights = _.cloneDeep(tempHighlights);
    const updateGrammarReplacements = _.cloneDeep(tempGrammarReplacements);
    const updateParaphrases = _.cloneDeep(tempParaphrases);

    _.forEach(highlights, (highlight, index) => {
      if (highlightAfterSelectionStart(selectionStart, selectionEnd, highlight)) {
        updateHighlights[index].highlightPosition[0] += selectionStart - selectionEnd + 1;
        updateHighlights[index].highlightPosition[1] += selectionStart - selectionEnd + 1;
      }
      if (
        selectionStartsInHighlight(selectionStart, highlight) ||
        selectionEndsInHighlight(selectionEnd, highlight) ||
        selectionsWrapsHighlight(selectionStart, selectionEnd, highlight)
      ) {
        updateHighlights[index].highlightPosition[0] = 0;
        updateHighlights[index].highlightPosition[1] = 0;
      }
    });

    _.forEach(grammarReplacements, (grammarReplacement, index) => {
      if (highlightAfterSelectionStart(selectionStart, selectionEnd, grammarReplacement)) {
        updateGrammarReplacements[index].highlightPosition[0] += selectionStart - selectionEnd + 1;
        updateGrammarReplacements[index].highlightPosition[1] += selectionStart - selectionEnd + 1;
      }
      if (
        selectionStartsInHighlight(selectionStart, grammarReplacement) ||
        selectionEndsInHighlight(selectionEnd, grammarReplacement) ||
        selectionsWrapsHighlight(selectionStart, selectionEnd, grammarReplacement)
      ) {
        updateGrammarReplacements[index].highlightPosition[0] = 0;
        updateGrammarReplacements[index].highlightPosition[1] = 0;
      }
    });

    _.forEach(paraphrases, (paraphrase, index) => {
      if (highlightAfterSelectionStart(selectionStart, selectionEnd, paraphrase)) {
        updateParaphrases[index].highlightPosition[0] += selectionStart - selectionEnd + 1;
        updateParaphrases[index].highlightPosition[1] += selectionStart - selectionEnd + 1;
      }
      if (
        selectionStartsInHighlight(selectionStart, paraphrase) ||
        selectionEndsInHighlight(selectionEnd, paraphrase) ||
        selectionsWrapsHighlight(selectionStart, selectionEnd, paraphrase)
      ) {
        updateParaphrases[index].highlightPosition[0] = 0;
        updateParaphrases[index].highlightPosition[1] = 0;
      }
    });
    setTemporaryHighlights(updateHighlights, updateGrammarReplacements, updateParaphrases);
  };

  const keyPressEventListener = (event: any) => {
    let selectionStart = 0;
    let selectionEnd = 0;

    const selection = document.getSelection();
    const range = selection?.getRangeAt(0);

    let prevLength = 0;
    let paragraphCount = 0;
    let currentNode = selection?.anchorNode?.parentElement as Element | null;
    while (currentNode?.previousElementSibling) {
      prevLength += currentNode?.previousElementSibling?.textContent?.length || 0;
      currentNode = currentNode.previousElementSibling;
      paragraphCount++;
    }
    selectionStart = (range?.startOffset || 0) + prevLength + paragraphCount;
    selectionEnd = (range?.endOffset || 0) + prevLength + paragraphCount;

    const updateHighlights = _.cloneDeep(tempHighlights);
    const updateGrammarReplacements = _.cloneDeep(tempGrammarReplacements);
    const updateParaphrases = _.cloneDeep(tempParaphrases);

    _.forEach(highlights, (highlight, index) => {
      if (highlightAfterSelectionStart(selectionStart, selectionEnd, highlight)) {
        updateHighlights[index].highlightPosition[0] += selectionStart - selectionEnd + 1;
        updateHighlights[index].highlightPosition[1] += selectionStart - selectionEnd + 1;
      }
      if (
        selectionStartsInHighlight(selectionStart, highlight) ||
        selectionEndsInHighlight(selectionEnd, highlight) ||
        selectionsWrapsHighlight(selectionStart, selectionEnd, highlight)
      ) {
        updateHighlights[index].highlightPosition[0] = 0;
        updateHighlights[index].highlightPosition[1] = 0;
      }
    });

    _.forEach(grammarReplacements, (grammarReplacement, index) => {
      if (highlightAfterSelectionStart(selectionStart, selectionEnd, grammarReplacement)) {
        updateGrammarReplacements[index].highlightPosition[0] += selectionStart - selectionEnd + 1;
        updateGrammarReplacements[index].highlightPosition[1] += selectionStart - selectionEnd + 1;
      }
      if (
        selectionStartsInHighlight(selectionStart, grammarReplacement) ||
        selectionEndsInHighlight(selectionEnd, grammarReplacement) ||
        selectionsWrapsHighlight(selectionStart, selectionEnd, grammarReplacement)
      ) {
        updateGrammarReplacements[index].highlightPosition[0] = 0;
        updateGrammarReplacements[index].highlightPosition[1] = 0;
      }
    });

    _.forEach(paraphrases, (paraphrase, index) => {
      if (highlightAfterSelectionStart(selectionStart, selectionEnd, paraphrase)) {
        updateParaphrases[index].highlightPosition[0] += selectionStart - selectionEnd + 1;
        updateParaphrases[index].highlightPosition[1] += selectionStart - selectionEnd + 1;
      }
      if (
        selectionStartsInHighlight(selectionStart, paraphrase) ||
        selectionEndsInHighlight(selectionEnd, paraphrase) ||
        selectionsWrapsHighlight(selectionStart, selectionEnd, paraphrase)
      ) {
        updateParaphrases[index].highlightPosition[0] = 0;
        updateParaphrases[index].highlightPosition[1] = 0;
      }
    });

    setTemporaryHighlights(updateHighlights, updateGrammarReplacements, updateParaphrases);
  };

  const onPasteEventListener = (event: any) => {
    if (analysisLoading) {
      resetHighlights();
      sendMessageToBackground({ action: ApiActions.ABORT_REQUEST });
      setAnalysisLoading(false);
    } else {
      resetHighlights();

      setTimeout(() => {
        const tempText = getTextFromActiveElement(activeElement);
        textRef.current = tempText;
        analyzeText(tempText);
      }, 1000);
    }
  };

  const onCutEventListener = (event: any) => {
    let selectionStart = 0;
    let selectionEnd = 0;
    let prevLength = 0;
    let paragraphCount = 0;
    if (activeElement?.tagName === 'DIV') {
      const selection = document.getSelection();
      const range = selection?.getRangeAt(0);

      let currentNode = selection?.anchorNode?.parentElement as Element | null;
      while (currentNode?.previousElementSibling) {
        prevLength += currentNode?.previousElementSibling?.textContent?.length || 0;
        currentNode = currentNode.previousElementSibling;
        paragraphCount++;
      }
      selectionStart = (range?.startOffset || 0) + prevLength + paragraphCount;
      selectionEnd = (range?.endOffset || 0) + prevLength + paragraphCount;
    } else {
      const selection = document.getSelection()?.toString();
      selectionStart = (activeElement as HTMLTextAreaElement).selectionStart - 1;
      selectionEnd = (activeElement as HTMLTextAreaElement).selectionStart + (selection?.length || 0);
    }

    const updateHighlights = _.cloneDeep(tempHighlights);
    const updateGrammarReplacements = _.cloneDeep(tempGrammarReplacements);
    const updateParaphrases = _.cloneDeep(tempParaphrases);

    _.forEach(highlights, (highlight, index) => {
      if (highlightAfterSelectionStart(selectionStart, selectionEnd, highlight)) {
        if (selectionEnd - selectionStart > 0) {
          updateHighlights[index].highlightPosition[0] -= selectionEnd - selectionStart;
          updateHighlights[index].highlightPosition[1] -= selectionEnd - selectionStart;
        } else {
          updateHighlights[index].highlightPosition[0] -= 1;
          updateHighlights[index].highlightPosition[1] -= 1;
        }
      }
      if (
        selectionStartsInHighlight(selectionStart, highlight) ||
        selectionEndsInHighlight(selectionEnd, highlight) ||
        selectionsWrapsHighlight(selectionStart, selectionEnd, highlight)
      ) {
        updateHighlights[index].highlightPosition[0] = 0;
        updateHighlights[index].highlightPosition[1] = 0;
      }
    });

    _.forEach(grammarReplacements, (grammarReplacement, index) => {
      if (highlightAfterSelectionStart(selectionStart, selectionEnd, grammarReplacement)) {
        if (selectionEnd - selectionStart > 0) {
          updateGrammarReplacements[index].highlightPosition[0] -= selectionEnd - selectionStart;
          updateGrammarReplacements[index].highlightPosition[1] -= selectionEnd - selectionStart;
        } else {
          updateGrammarReplacements[index].highlightPosition[0] -= 1;
          updateGrammarReplacements[index].highlightPosition[1] -= 1;
        }
      }
      if (
        selectionStartsInHighlight(selectionStart, grammarReplacement) ||
        selectionEndsInHighlight(selectionEnd, grammarReplacement) ||
        selectionsWrapsHighlight(selectionStart, selectionEnd, grammarReplacement)
      ) {
        updateGrammarReplacements[index].highlightPosition[0] = 0;
        updateGrammarReplacements[index].highlightPosition[1] = 0;
      }
    });

    _.forEach(paraphrases, (paraphrase, index) => {
      if (highlightAfterSelectionStart(selectionStart, selectionEnd, paraphrase)) {
        if (selectionEnd - selectionStart > 0) {
          updateParaphrases[index].highlightPosition[0] -= selectionEnd - selectionStart;
          updateParaphrases[index].highlightPosition[1] -= selectionEnd - selectionStart;
        } else {
          updateParaphrases[index].highlightPosition[0] -= 1;
          updateParaphrases[index].highlightPosition[1] -= 1;
        }
      }
      if (
        selectionStartsInHighlight(selectionStart, paraphrase) ||
        selectionEndsInHighlight(selectionEnd, paraphrase) ||
        selectionsWrapsHighlight(selectionStart, selectionEnd, paraphrase)
      ) {
        updateParaphrases[index].highlightPosition[0] = 0;
        updateParaphrases[index].highlightPosition[1] = 0;
      }
    });

    setTemporaryHighlights(updateHighlights, updateGrammarReplacements, updateParaphrases);
  };

  const analysisKeyUp = () => {
    if (!analysisLoading) {
      if (!_.isNil(typingTimer)) {
        clearTimeout(typingTimer);
      }

      setTypingTimer(
        setTimeout(() => {
          analyzeText(textRef.current);
        }, 2500)
      );
    }
  };

  const analysisKeyDown = () => {
    if (!_.isNil(typingTimer)) {
      clearTimeout(typingTimer);
      setTypingTimer(null);

      if (analysisLoading) {
        resetHighlights();
        sendMessageToBackground({ action: ApiActions.ABORT_REQUEST });
        setAnalysisLoading(false);
      }
    }
  };

  const changeEventListener = (event: any) => {
    if (event.inputType !== 'insertFromPaste') {
      const tempText = getTextFromActiveElement(activeElement);
      textRef.current = tempText;

      analysisKeyDown();

      if (tempText?.length === 0) {
        setTempHighlights([]);
        setTempGrammarReplacements([]);
        setTempParaphrases([]);

        setHighlights([]);
        setGrammarReplacements([]);
        setParaphrases([]);
      }
    }
  };

  const textAreaKeyDownEventListener = (event: any) => {
    let selectionStart = (activeElement as HTMLTextAreaElement).selectionStart;
    let selectionEnd = (activeElement as HTMLTextAreaElement).selectionEnd;

    const updateHighlights = _.cloneDeep(tempHighlights);
    const updateGrammarReplacements = _.cloneDeep(tempGrammarReplacements);
    const updateParaphrases = _.cloneDeep(tempParaphrases);

    if (event.key === 'Backspace' || event.key === 'Delete') {
      _.forEach(highlights, (highlight, index) => {
        if (highlightAfterSelectionStart(selectionStart, selectionEnd, highlight)) {
          if (selectionEnd - selectionStart > 0) {
            updateHighlights[index].highlightPosition[0] += selectionStart - selectionEnd;
            updateHighlights[index].highlightPosition[1] += selectionStart - selectionEnd;
          } else {
            updateHighlights[index].highlightPosition[0] -= 1;
            updateHighlights[index].highlightPosition[1] -= 1;
          }
        }
        if (
          selectionStartsInHighlight(selectionStart, highlight) ||
          selectionEndsInHighlight(selectionEnd, highlight) ||
          selectionsWrapsHighlight(selectionStart, selectionEnd, highlight)
        ) {
          updateHighlights[index].highlightPosition[0] = 0;
          updateHighlights[index].highlightPosition[1] = 0;
        }
      });

      _.forEach(grammarReplacements, (grammarReplacement, index) => {
        if (highlightAfterSelectionStart(selectionStart, selectionEnd, grammarReplacement)) {
          if (selectionEnd - selectionStart > 0) {
            updateGrammarReplacements[index].highlightPosition[0] += selectionStart - selectionEnd;
            updateGrammarReplacements[index].highlightPosition[1] += selectionStart - selectionEnd;
          } else {
            updateGrammarReplacements[index].highlightPosition[0] -= 1;
            updateGrammarReplacements[index].highlightPosition[1] -= 1;
          }
        }
        if (
          selectionStartsInHighlight(selectionStart, grammarReplacement) ||
          selectionEndsInHighlight(selectionEnd, grammarReplacement) ||
          selectionsWrapsHighlight(selectionStart, selectionEnd, grammarReplacement)
        ) {
          updateGrammarReplacements[index].highlightPosition[0] = 0;
          updateGrammarReplacements[index].highlightPosition[1] = 0;
        }
      });

      _.forEach(paraphrases, (paraphrase, index) => {
        if (highlightAfterSelectionStart(selectionStart, selectionEnd, paraphrase)) {
          if (selectionEnd - selectionStart > 0) {
            updateParaphrases[index].highlightPosition[0] += selectionStart - selectionEnd;
            updateParaphrases[index].highlightPosition[1] += selectionStart - selectionEnd;
          } else {
            updateParaphrases[index].highlightPosition[0] -= 1;
            updateParaphrases[index].highlightPosition[1] -= 1;
          }
        }
        if (
          selectionStartsInHighlight(selectionStart, paraphrase) ||
          selectionEndsInHighlight(selectionEnd, paraphrase) ||
          selectionsWrapsHighlight(selectionStart, selectionEnd, paraphrase)
        ) {
          updateParaphrases[index].highlightPosition[0] = 0;
          updateParaphrases[index].highlightPosition[1] = 0;
        }
      });

      setTemporaryHighlights(updateHighlights, updateGrammarReplacements, updateParaphrases);
    } else if (event.key === 'Enter') {
      _.forEach(highlights, (highlight, index) => {
        if (highlightAfterSelectionStart(selectionStart, selectionEnd, highlight)) {
          if (selectionEnd - selectionStart > 0) {
            updateHighlights[index].highlightPosition[0] += selectionStart - selectionEnd;
            updateHighlights[index].highlightPosition[1] += selectionStart - selectionEnd;
          } else {
            if (activeElement?.tagName === 'DIV') {
              if (selectionEnd - selectionStart === 0) {
                updateHighlights[index].highlightPosition[0] += 1;
                updateHighlights[index].highlightPosition[1] += 1;
              }
            } else {
              updateHighlights[index].highlightPosition[0] += 1;
              updateHighlights[index].highlightPosition[1] += 1;
            }
          }
        }
        if (
          selectionStartsInHighlight(selectionStart, highlight) ||
          selectionEndsInHighlight(selectionEnd, highlight) ||
          selectionsWrapsHighlight(selectionStart, selectionEnd, highlight)
        ) {
          updateHighlights[index].highlightPosition[0] = 0;
          updateHighlights[index].highlightPosition[1] = 0;
        }
      });

      _.forEach(grammarReplacements, (grammarReplacement, index) => {
        if (highlightAfterSelectionStart(selectionStart, selectionEnd, grammarReplacement)) {
          if (selectionEnd - selectionStart > 0) {
            updateGrammarReplacements[index].highlightPosition[0] += selectionStart - selectionEnd;
            updateGrammarReplacements[index].highlightPosition[1] += selectionStart - selectionEnd;
          } else {
            if (activeElement?.tagName === 'DIV') {
              if (selectionEnd - selectionStart === 0) {
                updateGrammarReplacements[index].highlightPosition[0] += 1;
                updateGrammarReplacements[index].highlightPosition[1] += 1;
              }
            } else {
              updateGrammarReplacements[index].highlightPosition[0] += 1;
              updateGrammarReplacements[index].highlightPosition[1] += 1;
            }
          }
        }
        if (
          selectionStartsInHighlight(selectionStart, grammarReplacement) ||
          selectionEndsInHighlight(selectionEnd, grammarReplacement) ||
          selectionsWrapsHighlight(selectionStart, selectionEnd, grammarReplacement)
        ) {
          updateGrammarReplacements[index].highlightPosition[0] = 0;
          updateGrammarReplacements[index].highlightPosition[1] = 0;
        }
      });

      _.forEach(paraphrases, (paraphrase, index) => {
        if (highlightAfterSelectionStart(selectionStart, selectionEnd, paraphrase)) {
          if (selectionEnd - selectionStart > 0) {
            updateParaphrases[index].highlightPosition[0] += selectionStart - selectionEnd;
            updateParaphrases[index].highlightPosition[1] += selectionStart - selectionEnd;
          } else {
            if (activeElement?.tagName === 'DIV') {
              if (selectionEnd - selectionStart === 0) {
                updateParaphrases[index].highlightPosition[0] += 1;
                updateParaphrases[index].highlightPosition[1] += 1;
              }
            } else {
              updateParaphrases[index].highlightPosition[0] += 1;
              updateParaphrases[index].highlightPosition[1] += 1;
            }
          }
        }
        if (
          selectionStartsInHighlight(selectionStart, paraphrase) ||
          selectionEndsInHighlight(selectionEnd, paraphrase) ||
          selectionsWrapsHighlight(selectionStart, selectionEnd, paraphrase)
        ) {
          updateParaphrases[index].highlightPosition[0] = 0;
          updateParaphrases[index].highlightPosition[1] = 0;
        }
      });

      setTemporaryHighlights(updateHighlights, updateGrammarReplacements, updateParaphrases);
    }
  };

  const keyDownEventListener = (event: any) => {
    let selectionStart = 0;
    let selectionEnd = 0;

    const selection = document.getSelection();
    const range = selection?.getRangeAt(0);

    let prevLength = 0;
    let paragraphCount = 0;
    let currentNode =
      range?.startContainer.nodeType === Node.TEXT_NODE || range?.startContainer.nodeName === 'BR'
        ? range?.startContainer?.parentElement
        : range?.startContainer;
    while (currentNode?.previousSibling) {
      prevLength += currentNode?.previousSibling?.textContent?.length || 0;
      currentNode = currentNode.previousSibling;
      paragraphCount++;
    }
    selectionStart = (range?.startOffset || 0) + prevLength + paragraphCount;
    selectionEnd = (range?.endOffset || 0) + prevLength + paragraphCount;

    const updateHighlights = _.cloneDeep(tempHighlights);
    const updateGrammarReplacements = _.cloneDeep(tempGrammarReplacements);
    const updateParaphrases = _.cloneDeep(tempParaphrases);

    if (event.key === 'Backspace' || event.key === 'Delete') {
      _.forEach(highlights, (highlight, index) => {
        if (highlightAfterSelectionStart(selectionStart, selectionEnd, highlight)) {
          if (selectionEnd - selectionStart > 0) {
            updateHighlights[index].highlightPosition[0] += selectionStart - selectionEnd;
            updateHighlights[index].highlightPosition[1] += selectionStart - selectionEnd;
          } else {
            updateHighlights[index].highlightPosition[0] -= 1;
            updateHighlights[index].highlightPosition[1] -= 1;
          }
        }
        if (
          selectionStartsInHighlight(selectionStart, highlight) ||
          selectionEndsInHighlight(selectionEnd, highlight) ||
          selectionsWrapsHighlight(selectionStart, selectionEnd, highlight)
        ) {
          updateHighlights[index].highlightPosition[0] = 0;
          updateHighlights[index].highlightPosition[1] = 0;
        }
      });

      _.forEach(grammarReplacements, (grammarReplacement, index) => {
        if (highlightAfterSelectionStart(selectionStart, selectionEnd, grammarReplacement)) {
          if (selectionEnd - selectionStart > 0) {
            updateGrammarReplacements[index].highlightPosition[0] += selectionStart - selectionEnd;
            updateGrammarReplacements[index].highlightPosition[1] += selectionStart - selectionEnd;
          } else {
            updateGrammarReplacements[index].highlightPosition[0] -= 1;
            updateGrammarReplacements[index].highlightPosition[1] -= 1;
          }
        }
        if (
          selectionStartsInHighlight(selectionStart, grammarReplacement) ||
          selectionEndsInHighlight(selectionEnd, grammarReplacement) ||
          selectionsWrapsHighlight(selectionStart, selectionEnd, grammarReplacement)
        ) {
          updateGrammarReplacements[index].highlightPosition[0] = 0;
          updateGrammarReplacements[index].highlightPosition[1] = 0;
        }
      });

      _.forEach(paraphrases, (paraphrase, index) => {
        if (highlightAfterSelectionStart(selectionStart, selectionEnd, paraphrase)) {
          if (selectionEnd - selectionStart > 0) {
            updateParaphrases[index].highlightPosition[0] += selectionStart - selectionEnd;
            updateParaphrases[index].highlightPosition[1] += selectionStart - selectionEnd;
          } else {
            updateParaphrases[index].highlightPosition[0] -= 1;
            updateParaphrases[index].highlightPosition[1] -= 1;
          }
        }
        if (
          selectionStartsInHighlight(selectionStart, paraphrase) ||
          selectionEndsInHighlight(selectionEnd, paraphrase) ||
          selectionsWrapsHighlight(selectionStart, selectionEnd, paraphrase)
        ) {
          updateParaphrases[index].highlightPosition[0] = 0;
          updateParaphrases[index].highlightPosition[1] = 0;
        }
      });

      setTemporaryHighlights(updateHighlights, updateGrammarReplacements, updateParaphrases);
    } else if (event.key === 'Enter') {
      _.forEach(highlights, (highlight, index) => {
        if (highlightAfterSelectionStart(selectionStart, selectionEnd, highlight)) {
          if (selectionEnd - selectionStart > 0) {
            updateHighlights[index].highlightPosition[0] += selectionStart - selectionEnd;
            updateHighlights[index].highlightPosition[1] += selectionStart - selectionEnd;
          } else {
            if (activeElement?.tagName === 'DIV') {
              if (selectionEnd - selectionStart === 0) {
                updateHighlights[index].highlightPosition[0] += 1;
                updateHighlights[index].highlightPosition[1] += 1;
              }
            } else {
              updateHighlights[index].highlightPosition[0] += 1;
              updateHighlights[index].highlightPosition[1] += 1;
            }
          }
        }
        if (
          selectionStartsInHighlight(selectionStart, highlight) ||
          selectionEndsInHighlight(selectionEnd, highlight) ||
          selectionsWrapsHighlight(selectionStart, selectionEnd, highlight)
        ) {
          updateHighlights[index].highlightPosition[0] = 0;
          updateHighlights[index].highlightPosition[1] = 0;
        }
      });

      _.forEach(grammarReplacements, (grammarReplacement, index) => {
        if (highlightAfterSelectionStart(selectionStart, selectionEnd, grammarReplacement)) {
          if (selectionEnd - selectionStart > 0) {
            updateGrammarReplacements[index].highlightPosition[0] += selectionStart - selectionEnd;
            updateGrammarReplacements[index].highlightPosition[1] += selectionStart - selectionEnd;
          } else {
            if (activeElement?.tagName === 'DIV') {
              if (selectionEnd - selectionStart === 0) {
                updateGrammarReplacements[index].highlightPosition[0] += 1;
                updateGrammarReplacements[index].highlightPosition[1] += 1;
              }
            } else {
              updateGrammarReplacements[index].highlightPosition[0] += 1;
              updateGrammarReplacements[index].highlightPosition[1] += 1;
            }
          }
        }
        if (
          selectionStartsInHighlight(selectionStart, grammarReplacement) ||
          selectionEndsInHighlight(selectionEnd, grammarReplacement) ||
          selectionsWrapsHighlight(selectionStart, selectionEnd, grammarReplacement)
        ) {
          updateGrammarReplacements[index].highlightPosition[0] = 0;
          updateGrammarReplacements[index].highlightPosition[1] = 0;
        }
      });

      _.forEach(paraphrases, (paraphrase, index) => {
        if (highlightAfterSelectionStart(selectionStart, selectionEnd, paraphrase)) {
          if (selectionEnd - selectionStart > 0) {
            updateParaphrases[index].highlightPosition[0] += selectionStart - selectionEnd;
            updateParaphrases[index].highlightPosition[1] += selectionStart - selectionEnd;
          } else {
            if (activeElement?.tagName === 'DIV') {
              if (selectionEnd - selectionStart === 0) {
                updateParaphrases[index].highlightPosition[0] += 1;
                updateParaphrases[index].highlightPosition[1] += 1;
              }
            } else {
              updateParaphrases[index].highlightPosition[0] += 1;
              updateParaphrases[index].highlightPosition[1] += 1;
            }
          }
        }
        if (
          selectionStartsInHighlight(selectionStart, paraphrase) ||
          selectionEndsInHighlight(selectionEnd, paraphrase) ||
          selectionsWrapsHighlight(selectionStart, selectionEnd, paraphrase)
        ) {
          updateParaphrases[index].highlightPosition[0] = 0;
          updateParaphrases[index].highlightPosition[1] = 0;
        }
      });

      setTemporaryHighlights(updateHighlights, updateGrammarReplacements, updateParaphrases);
    }
  };

  const keyUpEventListener = (event: any) => {
    if (event.key === 'z' && event.ctrlKey) {
      sendMessageToBackground({ action: AugmentedWritingActions.RESET_PANEL_HIGHLIGHTS });
    } else {
      if (
        !event.ctrlKey &&
        !event.altKey &&
        event.key !== 'Control' &&
        event.key !== 'Alt' &&
        event.key !== 'AltGraph' &&
        event.key !== 'Shift' &&
        event.key !== 'CapsLock' &&
        event.key !== 'Meta' &&
        event.key !== 'ArrowUp' &&
        event.key !== 'ArrowDown' &&
        event.key !== 'ArrowLeft' &&
        event.key !== 'ArrowRight' &&
        event.key !== 'Backquote' &&
        event.key !== 'F1' &&
        event.key !== 'F2' &&
        event.key !== 'F3' &&
        event.key !== 'F4' &&
        event.key !== 'F5' &&
        event.key !== 'F6' &&
        event.key !== 'F7' &&
        event.key !== 'F8' &&
        event.key !== 'F9' &&
        event.key !== 'F10' &&
        event.key !== 'F11' &&
        event.key !== 'F12' &&
        event.key !== 'Escape' &&
        event.key !== 'Insert' &&
        event.key !== 'Home' &&
        event.key !== 'End' &&
        event.key !== 'PageUp' &&
        event.key !== 'PageDown' &&
        event.key !== 'PrintScreen' &&
        event.key !== 'Tab' &&
        event.key !== 'NumLock' &&
        event.key !== 'ContextMenu'
      ) {
        analysisKeyUp();
      }

      setHighlights(tempHighlights);
      setGrammarReplacements(tempGrammarReplacements);
      setParaphrases(tempParaphrases);
    }
  };

  useEffect(() => {
    activeElement?.addEventListener('input', changeEventListener);
    activeElement?.addEventListener('keydown', activeElement.tagName === 'DIV' ? keyDownEventListener : textAreaKeyDownEventListener);
    activeElement?.addEventListener('keypress', activeElement.tagName === 'DIV' ? keyPressEventListener : textAreaKeyPressEventListener);
    activeElement?.addEventListener('keyup', keyUpEventListener);
    activeElement?.addEventListener('paste', onPasteEventListener);
    activeElement?.addEventListener('cut', onCutEventListener);
    return () => {
      activeElement?.removeEventListener('input', changeEventListener);
      activeElement?.removeEventListener('keydown', activeElement.tagName === 'DIV' ? keyDownEventListener : textAreaKeyDownEventListener);
      activeElement?.removeEventListener('keypress', activeElement.tagName === 'DIV' ? keyPressEventListener : textAreaKeyPressEventListener);
      activeElement?.removeEventListener('keyup', keyUpEventListener);
      activeElement?.removeEventListener('paste', onPasteEventListener);
      activeElement?.removeEventListener('cut', onCutEventListener);
    };
  }, [
    activeElement,
    highlights,
    grammarReplacements,
    paraphrases,
    tempHighlights,
    tempGrammarReplacements,
    tempParaphrases,
    contact,
    typingTimer,
    analysisLoading,
    fingerprints,
  ]);

  const modifyHighlightTexts = (text: string, removeCategories: string[]) => {
    const tempHighlightTexts = _.cloneDeep(highlightTexts);
    _.forEach(removeCategories, (category) => {
      if (tempHighlightTexts) {
        tempHighlightTexts[category] = text;
      }
    });
    return tempHighlightTexts;
  };

  useEffect(() => {
    const messageListener = (request, sender, callback) => {
      if (request.action === AugmentedWritingActions.POST_AUGMENTED_WRITING_SUGGESTIONS_RESPONSE) {
        if (request.body.scores !== undefined) {
          setHighlights(request.body.highlights);
          setTempHighlights(request.body.highlights);
          setHighlightTexts(request.body.highlightTexts);
        }

        if (request.body.suggestions !== undefined) {
          if (request.body.suggestions.grammarReplacement) {
            const unfilteredArr = request.body.suggestions.grammarReplacement;
            setGrammarReplacements(unfilteredArr);
            setTempGrammarReplacements(unfilteredArr);
          } else {
            setGrammarReplacements([]);
            setTempGrammarReplacements([]);
          }
          if (request.body.suggestions.paraphrases) {
            const unfilteredArr = request.body.suggestions.paraphrases;
            setParaphrases(unfilteredArr);
            setTempParaphrases(unfilteredArr);
          } else {
            setParaphrases([]);
            setTempParaphrases([]);
          }
        }
      }

      if (request.action === AugmentedWritingActions.CATEGORY_CLICK) {
        const category = request.body.category;
        const composedCategory = request.body.composedCategory?.composed ? request.body.composedCategory.composed : request.body.composedCategory;
        const source = request.body.source;
        const removeText = request.body.removeText;
        if (removeText) {
          setModifiedHighlightTexts(modifyHighlightTexts(removeText, composedCategory));
        }
        if (category) {
          if (composedCategory) {
            if (diagnosticMode.source === Sources.SIDEBAR_NOTES) {
              if (source === Sources.CHART) {
                // do nothing
              } else if (source === Sources.SIDEBAR_NOTES) {
                if (diagnosticMode.locked && category === diagnosticMode.category) {
                  setDiagnosticMode({ ...diagnosticMode, active: false, category: '', composedCategory: [], locked: false, source: Sources.NONE });
                  setModifiedHighlightTexts(undefined);
                } else {
                  setDiagnosticMode({
                    ...diagnosticMode,
                    active: true,
                    category,
                    composedCategory,
                    locked: true,
                    source,
                  });
                }
              } else {
                setDiagnosticMode({ ...diagnosticMode, active: false, category: '', composedCategory: [], locked: false, source: Sources.NONE });
                setModifiedHighlightTexts(undefined);
              }
            } else if (diagnosticMode.source === Sources.CHART) {
              if (source === Sources.CHART) {
                if (diagnosticMode.locked && category === diagnosticMode.category) {
                  setDiagnosticMode({ ...diagnosticMode, active: false, category: '', composedCategory: [], locked: false, source: Sources.NONE });
                  setModifiedHighlightTexts(undefined);
                } else {
                  setDiagnosticMode({
                    ...diagnosticMode,
                    active: true,
                    category,
                    composedCategory,
                    locked: true,
                    source,
                  });
                }
              } else if (source === Sources.SIDEBAR_NOTES) {
                setDiagnosticMode({
                  ...diagnosticMode,
                  active: true,
                  category,
                  composedCategory,
                  locked: true,
                  source,
                });
              } else {
                setDiagnosticMode({ ...diagnosticMode, active: false, category: '', composedCategory: [], locked: false, source: Sources.NONE });
                setModifiedHighlightTexts(undefined);
              }
            } else if (diagnosticMode.source === Sources.NONE) {
              if (source === Sources.NONE) {
                setDiagnosticMode({ ...diagnosticMode, active: false, category: '', composedCategory: [], locked: false, source: Sources.NONE });
                setModifiedHighlightTexts(undefined);
              } else {
                setDiagnosticMode({
                  ...diagnosticMode,
                  active: true,
                  category,
                  composedCategory,
                  locked: true,
                  source,
                });
              }
            }
          } else {
            setDiagnosticMode({ ...diagnosticMode, active: false, category: '', composedCategory: [], locked: false, source: Sources.NONE });
            setModifiedHighlightTexts(undefined);
          }
        } else {
          setDiagnosticMode({ ...diagnosticMode, active: false, category: '', composedCategory: [], locked: false, source: Sources.NONE });
          setModifiedHighlightTexts(undefined);
        }
      }

      if (request.action === AugmentedWritingActions.RESET_FIELD_HIGHLIGHTS) {
        resetHighlights();
      }

      if (request.action === GeneralActions.RESIZE_WINDOW) {
        setResizeWindow(request.body);
      }

      if (request.action === GeneralActions.SCROLL) {
        setWindowScrollY(request.body);
      }

      if (request.action === AugmentedWritingActions.INSERT_BY_CLICKABLE_MODE) {
        const shadow = document.getElementById(Ids.HIGHLIGHTER_SHADOW_ROOT)?.shadowRoot;
        const element = shadow?.getElementById(request.body.highlightId);
        if (element?.dataset.highlight) {
          const content = JSON.parse(element?.dataset.highlight);
          if (request.body.type === TooltipContentType.GRAMMAR_REPLACEMENT) {
            const grammarReplacement = content as GrammarReplacement;
            handleReplacementClick(grammarReplacement.highlightPosition, request.body.word)();
          }
          if (request.body.type === TooltipContentType.PARAPHRASE) {
            const paraphrase = content as Paraphrase;
            handleReplacementClick(paraphrase.highlightPosition, request.body.word)();
          }
        }
        handleClose();
      }

      if (request.action === AugmentedWritingActions.HIGHLIGHT_FIRST_SUGGESTION) {
        const suggestion = request.body.firstSuggestion as ISuggestionItem;
        const prevSuggestion = request.body.prevSuggestion as ISuggestionItem;
        setFirstSuggestion(suggestion);
        if (prevSuggestion) {
          if (prevSuggestion.contentType === TooltipContentType.GRAMMAR_REPLACEMENT) {
            const updateGrammarReplacements = _.cloneDeep(grammarReplacements);
            const filtered = updateGrammarReplacements.filter((grammarReplacement) => grammarReplacement.ranking_index !== prevSuggestion.index);
            setGrammarReplacements(filtered);
            setTempGrammarReplacements(filtered);
          }
          if (prevSuggestion.contentType === TooltipContentType.PARAPHRASE) {
            const updateParaphrases = _.cloneDeep(paraphrases);
            const filtered = updateParaphrases.filter((paraphrase) => paraphrase.ranking_index !== prevSuggestion.index);
            setParaphrases(filtered);
            setTempParaphrases(filtered);
          }
        }
      }
    };

    chrome?.runtime?.onMessage.addListener(messageListener);
    return () => {
      chrome?.runtime?.onMessage.removeListener(messageListener);
    };
  }, [activeElement, diagnosticMode, grammarReplacements, paraphrases]);

  const handleReplacementClick = (position: [number, number], suggestion: string) => {
    return () => {
      if (activeElement) {
        if (activeElement.tagName === 'DIV') {
          activeElement?.focus();
          const divElement = activeElement as HTMLDivElement;
          const range = document.createRange();
          range.selectNodeContents(divElement);
          const selection = window.getSelection();
          selection?.removeAllRanges();

          try {
            const jqueryContents: any[] = $(divElement).contents();
            let paragraphCount = 0;
            let prevLength = 0;
            _.forEach(jqueryContents, (node, index) => {
              const nodeList = getMostInnerTextNode(node);
              if (nodeList.length === 0 && node.nodeType === Node.TEXT_NODE) {
                nodeList.push(node);
              }
              _.forEach(nodeList, (textNode) => {
                if (position[0] < (textNode.textContent?.length || 0) + prevLength + paragraphCount && position[0] >= prevLength + paragraphCount) {
                  if (suggestion === '') {
                    range.setStart(textNode, position[0] - 1 - prevLength - paragraphCount);
                  } else {
                    range.setStart(textNode, position[0] - prevLength - paragraphCount);
                  }
                  range.setEnd(textNode, position[1] - prevLength - paragraphCount);
                }
                prevLength += textNode.textContent?.length || 0;
              });
              if (index !== jqueryContents.length - 1) {
                paragraphCount++;
              }
            });
            selection?.addRange(range);

            document.execCommand('insertText', false, suggestion);
            sendMessageToBackground({ action: AugmentedWritingActions.ANALYZE_TEXT });
          } catch (e) {
            console.error(e);
          }
        } else {
          activeElement?.focus();
          const divElement = activeElement as HTMLTextAreaElement;

          if (suggestion === '') {
            divElement.setSelectionRange(position[0] - 1, position[1]);
          } else {
            divElement.setSelectionRange(position[0], position[1]);
          }
          try {
            document.execCommand('insertText', false, suggestion);
            sendMessageToBackground({ action: AugmentedWritingActions.ANALYZE_TEXT });
          } catch (e) {
            console.error(e);
          }
        }
      }
    };
  };

  function resetHighlights() {
    setHighlights([]);
    setGrammarReplacements([]);
    setParaphrases([]);

    setTempHighlights([]);
    setTempGrammarReplacements([]);
    setTempParaphrases([]);

    setHighlightTexts(undefined);
    setModifiedHighlightTexts(undefined);
  }

  function analyzeText(text: string) {
    if (activeElement) {
      const profile = contact?.profile;
      const assessment = contactAssessment;
      const domain = AWTypes.LINKEDIN_MSG;

      if (profile && !_.isNil(assessment)) {
        if (text.length > 0) {
          sendMessageToBackground({
            action: AugmentedWritingActions.POST_AUGMENTED_WRITING_SUGGESTIONS_REQUEST,
            body: { text, awTrigger: AWTriggers.Manual, profile, domain, lang, ignoredFingerprints: fingerprints },
          });
          setAnalysisLoading(true);
        } else {
          resetHighlights();
          sendMessageToBackground({ action: AugmentedWritingActions.RESET_PANEL_HIGHLIGHTS });
        }
      }
      setMode(Modes.WRITER);
    }
  }

  return (
    <WrappedJssComponent rootId={Ids.HIGHLIGHTER_SHADOW_ROOT} containerId={Ids.HIGHLIGHTER_SHADOW_ROOT_CONTAINER}>
      <ThemeProvider theme={theme}>
        <ScopedCssBaseline>
          <HighlightRenderer
            highlights={_.filter(highlights, (highlight) =>
              highlight.categories.some((category) => (diagnosticMode.composedCategory as string[]).includes(category))
            )}
            grammarReplacements={grammarReplacements}
            paraphrases={paraphrases}
            highlightTexts={modifiedHighlightTexts ? modifiedHighlightTexts : highlightTexts}
            resizeElement={resizeElement}
            resizeWindow={resizeWindow}
            activeElement={activeElement}
            windowScrollY={windowScrollY}
            diagnosticMode={diagnosticMode}
            firstSuggestion={firstSuggestion}
          />
        </ScopedCssBaseline>
      </ThemeProvider>
    </WrappedJssComponent>
  );
};

export default Highlighter;
