import { Grid, Paper, Typography } from '@mui/material';
import React from 'react';
import { Trans, useTranslation } from 'react-i18next';
import { makeStyles } from 'tss-react/mui';
import useProfileStore from '../../stores/profileStore';
import { getCardImages } from '../../utils/imageUtils';

const NoAssessment: React.FC = () => {
  const { classes, cx } = useStyles();
  const { t } = useTranslation();
  const images = getCardImages();
  const contact = useProfileStore((state) => state.contact);

  return (
    <Paper className={classes.paper} elevation={0}>
      <Grid container={true} direction={'column'} alignItems={'center'}>
        <Grid className={classes.cardHeader} item={true}>
          <img className={classes.itemIcon} src={images?.info} alt="" />
        </Grid>
        <Grid className={classes.cardContent} item={true}>
          <Typography className={classes.title} align={'center'}>
            {t('noAssessmentTitle')}
          </Typography>
          <Typography className={classes.paragraph} align={'center'}>
            <Trans i18nKey={'noAssessment1'} values={{ firstName: contact?.firstName || '', lastName: contact?.lastName || '' }}>
              Das Profil von
              <strong>
                {contact?.firstName || ''} {contact?.lastName || ''}
              </strong>
              hat zu wenig Daten, um ein Ergebnis zu Erstellen.
            </Trans>
          </Typography>
          <Typography className={cx(classes.paragraph, 'no-margin')} align={'center'}>
            <Trans i18nKey={'noAssessment2'} values={{ contactOccupation: contact?.occupation || '' }}>
              Da unsere KI bisher zu wenige Kontakte mit dem Titel <strong>"{contact?.occupation || ''}"</strong> kennengelernt hat, können wir auch
              kein allgemeines Ergebnis anbieten.
            </Trans>
          </Typography>
        </Grid>
      </Grid>
    </Paper>
  );
};

const useStyles = makeStyles()((theme) => ({
  paper: {
    background: '#fff',
    borderRadius: 0,
  },
  cardHeader: {
    background: theme.palette.secondary.main,
    position: 'relative',
    height: '53.5px',
    width: '100%',
    display: 'flex',
    justifyContent: 'center',
    alignItems: 'center',
  },
  cardContent: {
    width: '100%',
    padding: '16px 8px',
    display: 'flex',
    flexDirection: 'column',
    alignItems: 'center',
  },
  title: {
    fontSize: '13px',
    color: theme.palette.secondary.main,
    fontWeight: 900,
    marginBottom: '8px',
    whiteSpace: 'pre-wrap',
    textTransform: 'uppercase',
  },
  paragraph: {
    fontSize: '12px',
    marginBottom: '8px',
    whiteSpace: 'pre-wrap',
    '&.no-margin': {
      marginBottom: 0,
    },
  },
  itemIcon: {
    verticalAlign: 'middle',
    height: '36px',
    width: '36px',
  },
}));

export default NoAssessment;
