import { Stack, Typography, alpha } from '@mui/material';
import _ from 'lodash';
import React, { useEffect, useState } from 'react';
import { useTranslation } from 'react-i18next';
import { makeStyles } from 'tss-react/mui';
import PaiButton from '../basic/PaiButton';
import PaiCircularProgress from '../basic/PaiCircularProgress';
import PaiDotLoader from '../basic/PaiDotLoader';

interface Props {
  text: string;
  score: number | null;

  textGenerationLoading: boolean;
  analysisLoading: boolean;
  formatTextLoading: boolean;

  copyGeneratedText(text: string): () => void;
}

const GeneratedTextItem: React.FC<Props> = ({ text, score, textGenerationLoading, analysisLoading, formatTextLoading, copyGeneratedText }) => {
  const { classes, cx } = useStyles();
  const { t } = useTranslation();
  const [savedSuccessful, setSavedSuccessful] = useState<boolean | null>(null);
  const [showScore, setShowScore] = useState(false);

  const loading = textGenerationLoading || analysisLoading || formatTextLoading;

  useEffect(() => {
    if (!_.isNil(score)) {
      setShowScore(true);
    }

    const myTimeout = setTimeout(() => {
      setShowScore(false);
    }, 3000);

    return () => {
      clearTimeout(myTimeout);
    };
  }, [score]);

  return (
    <Stack gap={1}>
      <div className={cx(classes.generatedText, loading ? 'optimizing' : null)}>
        {analysisLoading || formatTextLoading ? <div className={classes.loadingBlur} /> : null}
        {analysisLoading ? (
          <Stack className={classes.optimizationContainer} alignItems={'center'} gap={2}>
            <Typography className={classes.optimizationTitle}>{t('paiMatchOptimization')}</Typography>
            {!_.isNil(score) && showScore ? <PaiCircularProgress value={score * 100} /> : <PaiDotLoader />}
          </Stack>
        ) : null}
        {formatTextLoading ? (
          <Stack className={classes.optimizationContainer} alignItems={'center'} gap={2}>
            <Typography className={classes.optimizationTitle}>{t('textAutoFormat')}</Typography>
            <PaiDotLoader />
          </Stack>
        ) : null}
        <Typography className={classes.text}>{text}</Typography>
      </div>
      <PaiButton
        text={t('copy')}
        action={() => {
          copyGeneratedText(text)();
          setSavedSuccessful(true);
          setTimeout(() => {
            setSavedSuccessful(null);
          }, 1500);
        }}
        fullWidth={true}
        disabled={loading}
        success={savedSuccessful}
      />
    </Stack>
  );
};

const useStyles = makeStyles()((theme) => ({
  generatedText: {
    border: `2px solid ${theme.palette.tertiary.main}`,
    padding: '16px',
    position: 'relative',
    '&.optimizing': {
      minHeight: '164px',
    },
  },
  loadingBlur: {
    position: 'absolute',
    top: 0,
    left: 0,
    height: '100%',
    width: '100%',
    pointerEvents: 'none',
    background: alpha('#FFF', 0.8),
  },
  optimizationContainer: {
    position: 'absolute',
    top: 0,
    left: 0,
    width: '100%',
    height: '100%',
    padding: '24px 16px',
  },
  optimizationTitle: {
    fontSize: '13px',
    fontWeight: 900,
    textTransform: 'uppercase',
  },
  text: {
    fontSize: '14px',
    whiteSpace: 'pre-wrap',
  },
  button: {
    position: 'absolute',
    top: '-8px',
    right: '16px',
    display: 'flex',
    alignItems: 'center',
    padding: '0 8px',
    background: '#FFF',
    '&:hover': {
      '& .action-text': {
        color: theme.palette.primary.main,
      },
    },
  },
  actionText: {
    fontSize: '14px',
    fontWeight: 'bold',
    lineHeight: 1,
  },
}));

export default GeneratedTextItem;
