import create from 'zustand';

interface ElementStoreState {
  activeElement: HTMLDivElement | HTMLTextAreaElement | null;

  setActiveElement: (newElement: HTMLDivElement | HTMLTextAreaElement | null) => void;
}

const useElementStore = create<ElementStoreState>((set) => ({
  activeElement: null,

  setActiveElement(newElement) {
    set(() => ({ activeElement: newElement }));
  },
}));

export default useElementStore;
