import { useTheme } from '@mui/material';
import _ from 'lodash';
import React from 'react';
import { ThreeDots } from 'react-loader-spinner';
import { makeStyles } from 'tss-react/mui';

interface Props {
  size?: 'small' | 'normal' | 'large';
}

const PaiDotLoader: React.FC<Props> = ({ size }) => {
  const { classes } = useStyles();
  const theme = useTheme();

  const smallHeight = 20;
  const normalHeight = 40;
  const largeHeight = 100;

  const smallRadius = 3;
  const normalRadius = 5;
  const largeRadius = 10;

  const height = _.isNil(size)
    ? normalHeight
    : size === 'small'
    ? smallHeight
    : size === 'normal'
    ? normalHeight
    : size === 'large'
    ? largeHeight
    : normalHeight;

  const radius = _.isNil(size)
    ? normalRadius
    : size === 'small'
    ? smallRadius
    : size === 'normal'
    ? normalRadius
    : size === 'large'
    ? largeRadius
    : normalRadius;

  return (
    <div className={classes.loader}>
      <ThreeDots color={theme.palette.primary.main} height={height} width={height} radius={radius} />
    </div>
  );
};

const useStyles = makeStyles()((_theme) => ({
  loader: {
    width: '100%',
    display: 'flex',
    justifyContent: 'center',
  },
}));

export default PaiDotLoader;
