import ArrowForwardIcon from '@mui/icons-material/ArrowForward';
import { ListItem, ListItemButton, ListItemIcon, Typography, useTheme } from '@mui/material';
import _ from 'lodash';
import React from 'react';
import { makeStyles } from 'tss-react/mui';
import { TooltipContentType } from '../../../enums/enums';
import { AWSuggestionContent } from '../../../types/augmentedWriting';

interface Props {
  suggestion: AWSuggestionContent;
  contentType: TooltipContentType;
  ranking_index: number;

  insertAtPosition: (word: string, highlightId: string, type: TooltipContentType) => void;
}

const Optimization: React.FC<Props> = ({ suggestion, contentType, ranking_index, insertAtPosition }) => {
  const { classes } = useStyles();
  const theme = useTheme();

  const highlightTextSpan = (text: string, highlights?: number[][]) => {
    const splitArray: any[] = [];
    highlights?.forEach((highlight, index) => {
      if (index !== 0) {
        const textBetweenHighlights = text.substring(highlights[index - 1][1], highlights[index][0]);
        splitArray.push({ text: textBetweenHighlights, highlight: false });
      } else {
        const textBetweenHighlights = text.substring(0, highlight[0]);
        splitArray.push({ text: textBetweenHighlights, highlight: false });
      }

      const currHighlight = text.substring(highlight[0], highlight[1]);
      splitArray.push({ text: currHighlight, highlight: true });

      if (index === highlights.length - 1) {
        const rest = text.substring(highlight[1], text.length);
        splitArray.push({ text: rest, highlight: false });
      }
    });

    return splitArray.length === 0
      ? text
      : splitArray.map((split, index) => (
          <span key={index} style={{ color: split.highlight ? theme.palette.primary.main : undefined }}>
            {split.text}
          </span>
        ));
  };

  return (
    <ListItem className={classes.listItem}>
      <ListItemButton className={classes.listItemButton} onClick={() => insertAtPosition(suggestion.content, `${contentType}-${ranking_index}`, contentType)}>
        <ListItemIcon className={classes.listItemIcon}>
          <ArrowForwardIcon />
        </ListItemIcon>
        <Typography className={classes.listItemText}>
          {_.isNil(suggestion.tooltipHighlights) ? suggestion.content : highlightTextSpan(suggestion.content, suggestion.tooltipHighlights)}
          {!_.isNil(suggestion.score_improvement) ? <span className={classes.score}>+{suggestion.score_improvement} Match</span> : null}
        </Typography>
      </ListItemButton>
    </ListItem>
  );
};

const useStyles = makeStyles()((theme) => ({
  listItem: {
    padding: 0,
    position: 'relative',
  },
  listItemButton: {
    padding: '4px 0',
  },
  listItemIcon: {
    minWidth: 0,
    paddingRight: '4px',
    marginBottom: 'auto',
    '& svg': {
      fontSize: '16px',
      color: theme.palette.primary.main,
    },
  },
  listItemText: {
    fontSize: '11px',
    fontWeight: 'bold',
  },
  score: {
    color: theme.palette.secondary.main,
    fontSize: '11px',
    fontWeight: 'bold',
    marginLeft: '4px',
    whiteSpace: 'nowrap',
  },
}));

export default Optimization;
