import React from 'react';
import { AnalysisSelection } from '../../../enums/enums';
import { RelationshipQuality } from '../../../types/analysis';
import { Assessment } from '../../../types/assessment';
import { ProfileValues } from '../../../types/contact';
import BoosterWords from '../BoosterWords';
import DoComponent from '../DoComponent';
import StyleMatch from './StyleMatch';

interface Props {
  selectedAnalysis: AnalysisSelection;

  contactAssessment: Assessment | undefined;
  contactProfile: ProfileValues | undefined;
  userProfile: ProfileValues | undefined;
  relationshipQuality: RelationshipQuality | undefined;
}

const AnalysisSelectionContent: React.FC<Props> = ({ selectedAnalysis, contactAssessment, contactProfile, userProfile, relationshipQuality }) => {
  return selectedAnalysis === AnalysisSelection.STYLE_MATCH ? (
    <StyleMatch
      contactAssessment={contactAssessment}
      contactProfile={contactProfile}
      userProfile={userProfile}
      relationshipQuality={relationshipQuality}
    />
  ) : selectedAnalysis === AnalysisSelection.DOS ? (
    <DoComponent assessment={contactAssessment} isDo={true} />
  ) : selectedAnalysis === AnalysisSelection.DONTS ? (
    <DoComponent assessment={contactAssessment} isDo={false} />
  ) : selectedAnalysis === AnalysisSelection.BOOSTER_WORDS ? (
    <BoosterWords assessment={contactAssessment} />
  ) : null;
};

export default AnalysisSelectionContent;
