import CheckIcon from '@mui/icons-material/Check';
import { LoadingButton } from '@mui/lab';
import _ from 'lodash';
import React from 'react';
import { keyframes } from 'tss-react';
import { makeStyles } from 'tss-react/mui';
import { Colors } from '../../theme/theme';

interface Props {
  text: string | JSX.Element;
  fullWidth?: boolean;
  loading?: boolean;
  disabled?: boolean;
  size?: 'small' | 'normal' | 'large';
  style?: React.CSSProperties;
  success?: boolean | null;
  highlight?: boolean;

  action(): void;
}

const PaiButton: React.FC<Props> = ({ text, fullWidth, loading, disabled, size, style, success, highlight, action }) => {
  const { classes, cx } = useStyles({ size, success });
  return (
    <LoadingButton
      className={cx(classes.button, highlight ? 'highlight' : null)}
      onClick={action}
      variant={'contained'}
      fullWidth={fullWidth}
      loading={loading}
      disabled={disabled || !_.isNil(success)}
      disableElevation={true}
      style={style}
    >
      <span className={'btn-text'}>{text}</span>
      {!_.isNil(success) ? <CheckIcon className={classes.successIcon} /> : null}
    </LoadingButton>
  );
};

const useStyles = makeStyles<{ size?: 'small' | 'normal' | 'large'; success?: boolean | null }>()((theme, { size, success }) => ({
  button: {
    position: 'relative',
    borderRadius: 0,
    background: theme.palette.primary.main,
    fontSize: '16px',
    textTransform: 'none',
    textDecoration: 'underline',
    color: '#FFF',
    lineHeight: 1,
    padding: size === 'small' ? '4px' : size === 'normal' ? '8px' : size === 'large' ? '14.5px 16px' : '8px',
    '& .btn-text': {
      visibility: !_.isNil(success) ? 'hidden' : 'visible',
    },
    '&.highlight': {
      animation: `${keyframes`
      0%, 50% {
        background: ${theme.palette.primary.main};
      }
      25%, 75% {
        background: ${theme.palette.secondary.main};
      }
      `} 5s infinite`,
    },
    '&:hover': {
      background: theme.palette.secondary.main,
      textDecoration: 'underline',
    },
  },
  successIcon: {
    position: 'absolute',
    fontSize: '24px',
    color: Colors.SUCCESS_GREEN,
  },
}));

export default PaiButton;
