import DragIndicatorIcon from '@mui/icons-material/DragIndicator';
import { Alert, Paper, Snackbar } from '@mui/material';
import _ from 'lodash';
import React, { useEffect, useState } from 'react';
import Draggable from 'react-draggable';
import { Navigate, Route, Routes } from 'react-router-dom';
import { makeStyles } from 'tss-react/mui';
import shallow from 'zustand/shallow';
import ExtensionButton from '../components/sidePanel/ExtensionButton';
import ExtHeader from '../components/sidePanel/Header';
import { AugmentedWritingActions } from '../enums/actions';
import { Routes as RoutesEnum, SessionStatus, Sources, TooltipContentType, ZIndices } from '../enums/enums';
import Linkedin from '../pages/Linkedin';
import Login from '../pages/Login';
import usePanelStore from '../stores/panelStore';
import useSnackbarStore from '../stores/snackbarStore';
import useTextGenerationStore from '../stores/textGenerationStore';
import { Shadows } from '../theme/theme';
import { ISuggestionItem, Scores, SidebarNote } from '../types/augmentedWriting';
import { getHostDomain, sendMessageToBackground } from '../utils/helper';
import {
  isLinkedInRecComposePage,
  isLinkedInRecThreadsPage,
  isLinkedInRecUserPage,
  isLinkedInSalesNavSearchLeadsPage,
  isLinkedInSalesNavThreadsPage,
  isLinkedInSalesNavUserPage,
  isLinkedInThreadsPage,
  isLinkedInUserPage,
  isNormalLinkedin,
  isSalesNav,
} from '../utils/linkedinUtils';

interface Props {
  authenticated?: boolean;

  scores: Scores;
  sidebarNotes: SidebarNote[];
  allSuggestions: ISuggestionItem[];
  currentSession?: number;

  onCategoryClick: (category: string | undefined, composedCategory: any, source: Sources, removeText?: string) => void;

  insertAtPosition: (word: string, highlightId: string, type: TooltipContentType) => void;

  skipSuggestion(content: any): () => void;

  ignoreSuggestion(content: any, id: string): () => void;
}

const SidePanel: React.FC<Props> = ({
  authenticated,
  scores,
  allSuggestions,
  sidebarNotes,
  currentSession,
  onCategoryClick,
  insertAtPosition,
  skipSuggestion,
  ignoreSuggestion,
}) => {
  const { open, togglePanel, attached, setClickTrigger, collapsed } = usePanelStore(
    (state) => ({
      open: state.open,
      togglePanel: state.togglePanel,
      attached: state.attached,
      setClickTrigger: state.setClickTrigger,
      collapsed: state.collapsed,
    }),
    shallow
  );
  const { snackbar, closeSnackbar } = useSnackbarStore((state) => ({ snackbar: state.snackbar, closeSnackbar: state.closeSnackbar }), shallow);

  const { classes, cx } = useStyles({ attached, collapsed });

  const panelLocalStorageKey = 'pai-drag-delta';
  const storedPanelDelta = localStorage.getItem(panelLocalStorageKey);
  const panelDelta = !_.isNil(storedPanelDelta) ? JSON.parse(storedPanelDelta) : undefined;

  const [panelDeltaPosition, setPanelDeltaPosition] = useState({
    x: panelDelta?.x || 0,
    y: panelDelta?.y || 0,
  });

  const buttonLocalStorageKey = 'pai-button-drag-delta';
  const storedButtonDelta = localStorage.getItem(buttonLocalStorageKey);
  const buttonDelta = !_.isNil(storedButtonDelta) ? JSON.parse(storedButtonDelta) : undefined;

  const [buttonDeltaPosition, setButtonDeltaPosition] = useState({
    x: buttonDelta?.x || 0,
    y: buttonDelta?.y || 0,
  });

  const [size, setSize] = useState({ width: window.innerWidth, height: window.innerHeight });

  const resetAllTextGeneration = useTextGenerationStore((state) => state.resetAllTextGeneration);

  useEffect(() => {
    const resizeEvent = (event: any) => {
      const width = event.currentTarget.innerWidth;
      const height = event.currentTarget.innerHeight;

      setSize({ width, height });
    };
    window.addEventListener('resize', resizeEvent);

    return () => {
      window.removeEventListener('resize', resizeEvent);
    };
  }, []);

  const openDashboard = async () => {
    const hostDomain = await getHostDomain();
    const dashboardURL = `${hostDomain}/dashboard/landing/signin`;

    window.open(dashboardURL, '_blank');
  };

  const openPanel = () => {
    togglePanel(true);

    if (authenticated) {
      setClickTrigger(true);
    } else {
      openDashboard();
    }
  };

  const closePanel = (event: React.MouseEvent) => {
    event.stopPropagation();
    togglePanel(false);
    resetAllTextGeneration();
    chrome?.storage.local.set({ disableSidebarAutoOpen: 'true' });
    if (currentSession && scores.overall) {
      sendMessageToBackground({
        action: AugmentedWritingActions.CREATE_USER_BEHAVIOR,
        body: { scores, sessionStatus: SessionStatus.END, session: currentSession },
      });
    }
  };

  const isUserPage = () => {
    return isLinkedInUserPage() || isLinkedInSalesNavUserPage() || isLinkedInSalesNavSearchLeadsPage() || isLinkedInRecUserPage();
  };

  const isThreadPage = () => {
    return isLinkedInThreadsPage() || isLinkedInSalesNavThreadsPage() || isLinkedInRecThreadsPage();
  };

  const showExtension = () => {
    return isUserPage() || isThreadPage();
  };

  /**
   * Panel drag handlers
   */

  const handlePanelDragStop = (e, ui) => {
    const newDelta = {
      x: ui.x,
      y: ui.y,
    };

    setPanelDeltaPosition(newDelta);
    localStorage.setItem(panelLocalStorageKey, JSON.stringify(newDelta));
  };

  const calcPanelDeltaPosition = () => {
    const deltaX = panelDeltaPosition.x;
    const deltaY = panelDeltaPosition.y;

    const windowWidth = size.width;
    const windowHeight = size.height;

    let tempDelta = panelDeltaPosition;

    if (Math.abs(deltaX) > windowWidth - 336) {
      tempDelta.x = (windowWidth - 336) * -1;
    }

    const draggableHeight = windowHeight * 0.5;

    if (deltaY > windowHeight - draggableHeight) {
      tempDelta.y = windowHeight - draggableHeight;
    }

    if (deltaY < 0) {
      tempDelta.y = 0;
    }

    return tempDelta;
  };

  /**
   * Button drag handlers
   */

  const handleButtonDragStop = (e, ui) => {
    const newDelta = {
      x: ui.x,
      y: ui.y,
    };

    setButtonDeltaPosition(newDelta);
    localStorage.setItem(buttonLocalStorageKey, JSON.stringify(newDelta));
  };

  const calcButtonDeltaPosition = () => {
    const deltaX = buttonDeltaPosition.x;
    const deltaY = buttonDeltaPosition.y;

    const windowWidth = size.width;
    const windowHeight = size.height;

    let tempDelta = buttonDeltaPosition;

    if (Math.abs(deltaX) > windowWidth - 166) {
      tempDelta.x = (windowWidth - 166) * -1;
    }

    const draggableHeight = windowHeight * 0.5;

    if (deltaY > windowHeight - draggableHeight) {
      tempDelta.y = windowHeight - draggableHeight;
    }

    if (deltaY < 0) {
      tempDelta.y = 0;
    }

    return tempDelta;
  };

  return (
    <>
      {open ? (
        <Draggable
          onStop={handlePanelDragStop}
          position={attached ? { x: 0, y: 0 } : calcPanelDeltaPosition()}
          defaultPosition={attached ? undefined : calcPanelDeltaPosition()}
          handle={'.panel-handle'}
          bounds={'body'}
          disabled={attached}
        >
          <Paper className={cx(classes.paper, classes.panel, !attached && 'sidebar-detached')} square={true} elevation={0}>
            <ExtHeader authenticated={authenticated} closePanel={closePanel} />
            <div className={classes.content}>
              <Routes>
                <Route path="/" element={<Navigate to={{ pathname: RoutesEnum.LOGIN }} />} />
                <Route path={RoutesEnum.LOGIN} element={<Login />} />
                <Route
                  path={RoutesEnum.LINKEDIN}
                  element={
                    <Linkedin
                      scores={scores}
                      sidebarNotes={sidebarNotes}
                      onCategoryClick={onCategoryClick}
                      allSuggestions={allSuggestions}
                      insertAtPosition={insertAtPosition}
                      skipSuggestion={skipSuggestion}
                      ignoreSuggestion={ignoreSuggestion}
                    />
                  }
                />
              </Routes>
              <Snackbar className={classes.snackbar} open={snackbar.open} autoHideDuration={3000} onClose={closeSnackbar}>
                <Alert severity={snackbar.type} style={{ fontSize: '14px', fontWeight: 'bold' }}>
                  {snackbar.message}
                </Alert>
              </Snackbar>
            </div>
          </Paper>
        </Draggable>
      ) : showExtension() ? (
        <Draggable
          onStop={handleButtonDragStop}
          position={calcButtonDeltaPosition()}
          defaultPosition={calcButtonDeltaPosition()}
          handle={'.button-handle'}
          bounds={'body'}
        >
          <div className={classes.extensionButton}>
            <ExtensionButton authenticated={authenticated} openPanel={openPanel} />
            <DragIndicatorIcon className={cx(classes.dragIndicator, 'button-handle')} />
          </div>
        </Draggable>
      ) : null}
    </>
  );
};

const useStyles = makeStyles<{ attached: boolean; collapsed: boolean }>()((theme, { attached, collapsed }) => ({
  panel: {
    boxShadow: Shadows.NORMAL_SHADOW,
    position: 'fixed',
    transition: !attached ? undefined : '500ms',
    width: collapsed ? '80px' : '380px',
    height: isNormalLinkedin()
      ? 'calc(100vh - 53px)'
      : isSalesNav()
      ? 'calc(100vh - 142px)'
      : isLinkedInRecComposePage()
      ? 'calc(100vh - 48px)'
      : isLinkedInRecUserPage()
      ? 'calc(100vh - 129px)'
      : '100vh',
    maxWidth: '400px',
    right: 0,
    top: isNormalLinkedin() ? '53px' : isSalesNav() ? '142px' : isLinkedInRecComposePage() ? '48px' : isLinkedInRecUserPage() ? '129px' : '50px',
    zIndex: ZIndices.SIDE_PANEL,
    borderRadius: !attached ? '4px' : 0,
    '&.sidebar-detached': {
      height: isNormalLinkedin() ? '90vh' : '85vh',
    },
  },
  paper: {
    height: '100%',
    display: 'flex',
    flexDirection: 'column',
  },
  extensionButton: {
    position: 'fixed',
    right: '16px',
    top: isLinkedInRecComposePage() || isLinkedInRecUserPage() ? '60px' : '4px',
    zIndex: ZIndices.EXTENSION_BUTTON,
    display: 'flex',
    flexDirection: 'column',
    alignItems: 'center',
  },
  content: {
    overflowY: 'hidden',
    height: 'calc(100% - 32px)',
    overflowX: 'hidden',
    background: '#FFF',
  },
  snackbar: {
    position: 'absolute',
    pointerEvents: 'none',
  },
  dragIndicator: {
    fontSize: '30px',
    color: theme.palette.primary.main,
    transform: 'rotate(90deg)',
    cursor: 'grab',
  },
}));

export default SidePanel;
