import _ from 'lodash';
import create from 'zustand';
import { Assessment } from '../types/assessment';
import { ProfileValues } from '../types/contact';

interface Analysis {
  assessment?: Assessment;
  profile?: ProfileValues;
  percentiles?: ProfileValues;
}

export interface Contact extends Analysis {
  id: string;
  globalContact?: string;
  externalId?: string;
  firstName?: string;
  lastName?: string;
  occupation?: string;
  qualityFactor?: number | string;
  trend?: string;
  basis?: ProfileBases;
  matchedJobTitle?: string;
}

export enum ProfileBases {
  PERSON = 'person',
  EXACT = 'exactJobTitle',
  MATCHED = 'matchedJobTitle',
}

interface ProfileStore {
  userAnalysis?: Analysis;
  contact?: Contact;
  profileLoading: boolean;

  setUserAnalysis: (assessment?: Assessment, profile?: ProfileValues, percentiles?: ProfileValues) => void;
  setContactData: (
    id: string,
    globalContact?: string,
    externalId?: string,
    firstName?: string,
    lastName?: string,
    occupation?: string,
    qualityFactor?: number | string,
    trend?: string,
    basis?: ProfileBases,
    matchedJobTitle?: string
  ) => void;
  setContactAnalysis: (assessment?: Assessment, profile?: ProfileValues, percentiles?: ProfileValues) => void;

  resetUserAnalysis: () => void;
  resetContact: () => void;

  setProfileLoading: (loading: boolean) => void;
}

const useProfileStore = create<ProfileStore>((set, get) => ({
  userAnalysis: undefined,
  contact: undefined,
  profileLoading: false,

  setUserAnalysis(assessment?: Assessment, profile?: ProfileValues, percentiles?: ProfileValues) {
    const tempAnalysis: Analysis = {};
    const state = get();

    if (!_.isNil(assessment)) {
      tempAnalysis.assessment = assessment;
    } else {
      tempAnalysis.assessment = state.userAnalysis?.assessment;
    }

    if (!_.isNil(profile)) {
      tempAnalysis.profile = profile;
    } else {
      tempAnalysis.profile = state.userAnalysis?.profile;
    }

    if (!_.isNil(percentiles)) {
      tempAnalysis.percentiles = percentiles;
    } else {
      tempAnalysis.percentiles = state.userAnalysis?.percentiles;
    }

    set(() => ({ userAnalysis: tempAnalysis }));
  },

  setContactData(
    id: string,
    globalContact?: string,
    externalId?: string,
    firstName?: string,
    lastName?: string,
    occupation?: string,
    qualityFactor?: number | string,
    trend?: string,
    basis?: ProfileBases,
    matchedJobTitle?: string
  ) {
    const tempContact: Contact = { id: '' };

    if (!_.isNil(id)) {
      tempContact.id = id;
    }

    if (!_.isNil(globalContact)) {
      tempContact.globalContact = globalContact;
    }

    if (!_.isNil(externalId)) {
      tempContact.externalId = externalId;
    }

    if (!_.isNil(firstName)) {
      tempContact.firstName = firstName;
    }

    if (!_.isNil(lastName)) {
      tempContact.lastName = lastName;
    }

    if (!_.isNil(occupation)) {
      tempContact.occupation = occupation;
    }

    if (!_.isNil(qualityFactor)) {
      tempContact.qualityFactor = qualityFactor;
    }

    if (!_.isNil(trend)) {
      tempContact.trend = trend;
    }

    if (!_.isNil(basis)) {
      tempContact.basis = basis;
    }

    if (!_.isNil(matchedJobTitle)) {
      tempContact.matchedJobTitle = matchedJobTitle;
    }

    const state = get();
    const tempAnalysis = {
      assessment: state.contact?.assessment,
      profile: state.contact?.profile,
      percentiles: state.contact?.percentiles,
    };

    set(() => ({ contact: { ...tempAnalysis, ...tempContact } }));
  },

  setContactAnalysis(assessment?: Assessment, profile?: ProfileValues, percentiles?: ProfileValues) {
    const tempAnalysis: Contact = { id: '' };
    const state = get();

    if (!_.isNil(assessment)) {
      tempAnalysis.assessment = assessment;
    } else {
      tempAnalysis.assessment = state.contact?.assessment;
    }

    if (!_.isNil(profile)) {
      tempAnalysis.profile = profile;
    } else {
      tempAnalysis.profile = state.contact?.profile;
    }

    if (!_.isNil(percentiles)) {
      tempAnalysis.percentiles = percentiles;
    } else {
      tempAnalysis.percentiles = state.contact?.percentiles;
    }

    const tempContact = {
      id: state.contact?.id || '',
      firstName: state.contact?.firstName,
      lastName: state.contact?.lastName,
      occupation: state.contact?.occupation,
      qualityFactor: state.contact?.qualityFactor,
      trend: state.contact?.trend,
      basis: state.contact?.basis,
      matchedJobTitle: state.contact?.matchedJobTitle,
    };

    set(() => ({ contact: { ...tempAnalysis, ...tempContact } }));
  },

  resetUserAnalysis() {
    set(() => ({ userAnalysis: undefined }));
  },

  resetContact() {
    set(() => ({ contact: undefined }));
  },

  setProfileLoading(loading: boolean) {
    set(() => ({ profileLoading: loading }));
  },

}));

export default useProfileStore;
