import _ from 'lodash';
import { useEffect, useState } from 'react';
import shallow from 'zustand/shallow';
import { AugmentedWritingActions } from '../enums/actions';
import { SessionStatus, Sources, TooltipContentType } from '../enums/enums';
import useAugmentedWritingStore from '../stores/augmentedWritingStore';
import useProfileStore, { Contact } from '../stores/profileStore';
import { AWSuggestionContent, GrammarReplacement, ISuggestionItem, Paraphrase } from '../types/augmentedWriting';
import { sendMessageToBackground } from '../utils/helper';

const defaultScores = {
  diversity: -0.1,
  overall: 0,
  percentiles: {
    profile: {
      diversity: -0.1,
      jointPosAchieve: 0,
      jointPosPower: 0,
      jointPosAffil: 0,
      authenticity: 0,
      regFocus: 0,
      gender: 0,
    },
    text: {
      diversity: -0.1,
      jointPosAchieve: 0,
      jointPosPower: 0,
      jointPosAffil: 0,
      authenticity: 0,
      regFocus: 0,
      gender: 0,
    },
  },
};

export const useAugmentedWriting = (element: HTMLDivElement | HTMLTextAreaElement | null, contact?: Contact) => {
  const { setUserAnalysis, resetUserAnalysis } = useProfileStore(
    (state) => ({ setUserAnalysis: state.setUserAnalysis, resetUserAnalysis: state.resetUserAnalysis }),
    shallow
  );
  const {
    setAnalysisLoading,
    setIsAnalyzed,
    setUserDone,
    fingerprints,
    setFingerprints,
    allSuggestions,
    setAllSuggestions,
    scores,
    setScores,
    sidebarNotes,
    setSidebarNotes,
  } = useAugmentedWritingStore(
    (state) => ({
      setAnalysisLoading: state.setAnalysisLoading,
      setIsAnalyzed: state.setIsAnalyzed,
      setUserDone: state.setUserDone,
      fingerprints: state.fingerprints,
      setFingerprints: state.setFingerprints,
      allSuggestions: state.allSuggestions,
      setAllSuggestions: state.setAllSuggestions,
      scores: state.scores,
      setScores: state.setScores,
      sidebarNotes: state.sidebarNotes,
      setSidebarNotes: state.setSidebarNotes,
    }),
    shallow
  );

  const [coreCommit, setCoreCommit] = useState<string | undefined>();
  const [currentSession, setCurrentSession] = useState<number | undefined>();

  const [grammarReplacements, setGrammarReplacements] = useState<GrammarReplacement[]>([]);
  const [paraphrases, setParaphrases] = useState<Paraphrase[]>();

  useEffect(() => {
    const messageListener = (request, sender, callback) => {
      if (request.action === AugmentedWritingActions.SET_CORE_COMMIT) {
        setCoreCommit(request.body.coreCommit);
      }

      if (request.action === AugmentedWritingActions.GET_BEHAVIOR_LAST_SESSION_RESPONSE) {
        setCurrentSession(request.body.session);
        sendMessageToBackground({
          action: AugmentedWritingActions.CREATE_USER_BEHAVIOR,
          body: { scores, sessionStatus: SessionStatus.START, session: request.body.session, from: '261 app' },
        });
      }
    };

    chrome?.runtime?.onMessage.addListener(messageListener);
    return () => {
      chrome?.runtime?.onMessage.removeListener(messageListener);
    };
  }, []);

  useEffect(() => {
    const messageListener = (request, sender, callback) => {
      if (request.action === AugmentedWritingActions.POST_AUGMENTED_WRITING_SUGGESTIONS_RESPONSE) {
        setAnalysisLoading(false);
        setIsAnalyzed(true);

        if (!_.isNil(request.body.user_done)) {
          setUserDone(request.body.user_done);
        }

        if (request.body.scores !== undefined) {
          setScores(request.body.scores);
          setUserAnalysis(undefined, undefined, request.body.scores.percentiles.text);
          if (!currentSession) {
            sendMessageToBackground({ action: AugmentedWritingActions.GET_BEHAVIOR_LAST_SESSION });
          } else {
            sendMessageToBackground({
              action: AugmentedWritingActions.CREATE_USER_BEHAVIOR,
              body: { scores: request.body.scores, sessionStatus: SessionStatus.MIDDLE, session: currentSession, wordCount: request.body.wordCount },
            });
          }
        }
        if (request.body.sidebarNotes !== undefined) {
          setSidebarNotes(request.body.sidebarNotes);
        }

        if (request.body.suggestions !== undefined) {
          if (request.body.suggestions.grammarReplacement) {
            const unfilteredArr = request.body.suggestions.grammarReplacement;
            setGrammarReplacements(unfilteredArr);
          } else {
            setGrammarReplacements([]);
          }
          if (request.body.suggestions.paraphrases) {
            const unfilteredArr = request.body.suggestions.paraphrases;
            setParaphrases(unfilteredArr);
          } else {
            setParaphrases([]);
          }
        }
      }

      if (request.action === AugmentedWritingActions.REMOVE_HIGHLIGHT_FROM_CLICKABLE_MODE) {
        const updateAllSuggestions = _.cloneDeep(allSuggestions);
        const prevSuggestion = updateAllSuggestions.find((item) => item.index === request.body.prevSuggestion.ranking_index);
        if (prevSuggestion) {
          const index = updateAllSuggestions.findIndex((item) => item.index === prevSuggestion.index);
          if (index >= 0) {
            updateAllSuggestions.splice(index, 1);
            const firstSuggestion = _.head(updateAllSuggestions);
            sendMessageToBackground({ action: AugmentedWritingActions.HIGHLIGHT_FIRST_SUGGESTION, body: { firstSuggestion, prevSuggestion } });
            setAllSuggestions(updateAllSuggestions);
          }
        }
      }

      if (request.action === AugmentedWritingActions.RESET_PANEL_HIGHLIGHTS) {
        resetSuggestions();
        resetAnalysisResults();
      }
    };

    chrome?.runtime?.onMessage.addListener(messageListener);
    return () => {
      chrome?.runtime?.onMessage.removeListener(messageListener);
    };
  }, [allSuggestions]);

  useEffect(() => {
    const mappedGrammarReplacements: ISuggestionItem[] =
      grammarReplacements?.map((item) => ({
        contentType: TooltipContentType.GRAMMAR_REPLACEMENT,
        content: item,
        index: item.ranking_index,
        highlightId: `${TooltipContentType.GRAMMAR_REPLACEMENT}-${item.ranking_index}`,
      })) || [];
    const mappedParaphrases: ISuggestionItem[] =
      paraphrases?.map((item) => ({
        contentType: TooltipContentType.PARAPHRASE,
        content: item,
        index: item.ranking_index,
        highlightId: `${TooltipContentType.PARAPHRASE}-${item.ranking_index}`,
      })) || [];

    const concatArray: ISuggestionItem[] = _.concat(mappedGrammarReplacements, mappedParaphrases);

    const sortedArray = _.sortBy(concatArray, (suggestion) => suggestion.index);
    const firstSuggestion = _.head(sortedArray);

    if (firstSuggestion) {
      sendMessageToBackground({ action: AugmentedWritingActions.HIGHLIGHT_FIRST_SUGGESTION, body: { firstSuggestion } });
    }

    setAllSuggestions(sortedArray);
  }, [grammarReplacements, paraphrases]);

  const skipSuggestion = (content: any) => {
    return () => {
      const suggestions: AWSuggestionContent[] = content.suggestions;
      const newFingerprints: string[] = [];

      suggestions.forEach((suggestion) => {
        if (!_.isNil(suggestion.fingerprint)) {
          newFingerprints.push(suggestion.fingerprint);
        }
      });

      const currentFingerprints = [...fingerprints];
      const newIgnored = [...currentFingerprints, ...newFingerprints];

      setFingerprints(newIgnored);

      const updateAllSuggestions = _.cloneDeep(allSuggestions);
      const prevSuggestion = updateAllSuggestions.shift();
      const firstSuggestion = _.head(updateAllSuggestions);
      sendMessageToBackground({ action: AugmentedWritingActions.HIGHLIGHT_FIRST_SUGGESTION, body: { firstSuggestion, prevSuggestion } });
      setAllSuggestions(updateAllSuggestions);
    };
  };

  const ignoreSuggestion = (content: any, id: string) => {
    return async () => {
      const suggestions: AWSuggestionContent[] = content.suggestions;
      const newFingerprints: string[] = [];

      suggestions.forEach((suggestion) => {
        if (!_.isNil(suggestion.fingerprint)) {
          newFingerprints.push(suggestion.fingerprint);
        }
      });

      sendMessageToBackground({ action: AugmentedWritingActions.SAVE_IGNORED_SUGGESTIONS, body: { fingerprints: newFingerprints } });

      const updateAllSuggestions = _.cloneDeep(allSuggestions);
      const currentActiveSuggestion = updateAllSuggestions.find((suggestion) => suggestion.highlightId === id);
      _.pull(updateAllSuggestions, currentActiveSuggestion);
      const firstSuggestion = _.head(updateAllSuggestions);
      sendMessageToBackground({
        action: AugmentedWritingActions.HIGHLIGHT_FIRST_SUGGESTION,
        body: { firstSuggestion, prevSuggestion: currentActiveSuggestion },
      });

      setAllSuggestions(updateAllSuggestions);
    };
  };

  const insertAtPosition = (word: string, highlightId: string, type: TooltipContentType) => {
    sendMessageToBackground({ action: AugmentedWritingActions.INSERT_BY_CLICKABLE_MODE, body: { word, highlightId, type } });
  };

  const onCategoryClick = (category: string | undefined, composedCategory: any, source: Sources, removeText?: string) => {
    sendMessageToBackground({ action: AugmentedWritingActions.CATEGORY_CLICK, body: { category, composedCategory, source, removeText } });
  };

  const resetSuggestions = () => {
    setGrammarReplacements([]);
    setParaphrases([]);
    setFingerprints([]);
  };

  const resetAnalysisResults = (keepScore?: boolean) => {
    if (!keepScore) {
      if (currentSession && scores.overall) {
        sendMessageToBackground({
          action: AugmentedWritingActions.CREATE_USER_BEHAVIOR,
          body: { scores, sessionStatus: SessionStatus.END, session: currentSession },
        });
      }
      setScores(defaultScores);
    }
    resetUserAnalysis();
    setSidebarNotes([]);
    setAnalysisLoading(false);
    setIsAnalyzed(false);
    setCoreCommit(undefined);
    setUserDone(false);

    sendMessageToBackground({
      action: AugmentedWritingActions.CATEGORY_CLICK,
      body: { category: undefined, composedCategory: undefined, source: Sources.NONE },
    });
    sendMessageToBackground({ action: AugmentedWritingActions.RESET_FIELD_HIGHLIGHTS });
  };

  return {
    allSuggestions,
    scores,
    sidebarNotes,
    coreCommit,
    currentSession,
    resetAnalysisResults,
    resetSuggestions,
    skipSuggestion,
    ignoreSuggestion,
    insertAtPosition,
    onCategoryClick,
  };
};
