import { ButtonBase, Stack, alpha } from '@mui/material';
import React from 'react';
import { makeStyles } from 'tss-react/mui';
import { ProductGroups } from '../../../enums/enums';
import { Colors, Shadows } from '../../../theme/theme';

interface Props {
  product: ProductGroups;
  activePricing: ProductGroups;

  setActive(newActive: ProductGroups): () => void;
}

const PricingSidebarItem: React.FC<Props> = ({ product, activePricing, setActive }) => {
  const { classes, cx } = useStyles({ product });

  const active = activePricing === product;

  return (
    <Stack gap={2} alignItems={'center'} flexWrap={'nowrap'} direction={'row'}>
      <ButtonBase className={cx(classes.select, active ? 'active' : null)} onClick={setActive(product)} />
      <ButtonBase className={cx(classes.button, active ? 'active' : null)} onClick={setActive(product)}>
        {active ? <div className={classes.arrow} /> : null}
        {product}
      </ButtonBase>
    </Stack>
  );
};

const useStyles = makeStyles<{ product: ProductGroups }>()((theme, { product }) => ({
  select: {
    width: '16px',
    height: '16px',
    border: `1px solid ${Colors.GREY_SHADE_5}`,
    background: '#FFF',
    '&.active': {
      border: `1px solid ${theme.palette.primary.main}`,
      background: theme.palette.primary.main,
    },
  },
  button: {
    width: 'calc(100% - 24px - 16px)',
    padding: '16px',
    display: 'flex',
    alignItems: 'center',
    border: `1px solid ${Colors.GREY_SHADE_5}`,
    color: Colors.GREY_SHADE_5,
    fontSize: '14px',
    fontWeight: 'bold',
    '&:hover': {
      background: theme.palette.action.hover,
    },
    '&.active': {
      color: '#FFF',
      border: `2px solid ${
        product === ProductGroups.LEAD_BOOSTER
          ? Colors.MAGENTA
          : product === ProductGroups.HR_BOOSTER
          ? Colors.ORANGE
          : product === ProductGroups.SALES_BOOSTER
          ? Colors.PURPLE
          : Colors.BLUE
      }`,
      background:
        product === ProductGroups.LEAD_BOOSTER
          ? Colors.MAGENTA
          : product === ProductGroups.HR_BOOSTER
          ? Colors.ORANGE
          : product === ProductGroups.SALES_BOOSTER
          ? Colors.PURPLE
          : Colors.BLUE,
      boxShadow: Shadows.GREY_SHADOW,
    },
  },
  arrow: {
    position: 'absolute',
    left: -2,
    width: 0,
    height: 0,
    borderTop: '16px solid transparent',
    borderBottom: '16px solid transparent',
    borderLeft: `16px solid ${alpha('#FFF', 0.8)}`,
  },
}));

export default PricingSidebarItem;
