import create from 'zustand';
import { TooltipContentType } from '../enums/enums';
import { GrammarReplacement, Paraphrase } from '../types/augmentedWriting';

interface InteractiveTooltipStoreState {
  open: boolean;
  anchorElement: HTMLElement | null;

  type?: TooltipContentType;
  suggestion?: GrammarReplacement | Paraphrase;

  handleOpen: (anchorElement: HTMLElement | null, type?: TooltipContentType, suggestion?: GrammarReplacement | Paraphrase) => void;

  handleClose: () => void;
}

const useInteractiveTooltipStore = create<InteractiveTooltipStoreState>((set) => ({
  open: false,
  anchorElement: null,
  type: undefined,
  suggestion: undefined,

  handleOpen(anchorElement: HTMLElement | null, type?: TooltipContentType, suggestion?: GrammarReplacement | Paraphrase) {
    set(() => ({ open: true, anchorElement, type, suggestion }));
  },

  handleClose() {
    set(() => ({ open: false, anchorElement: null, type: undefined, suggestion: undefined }));
  },
}));

export default useInteractiveTooltipStore;
