import { ButtonBase, Dialog, DialogActions, DialogContent, DialogTitle, Typography } from '@mui/material';
import React from 'react';
import { useTranslation } from 'react-i18next';
import { makeStyles } from 'tss-react/mui';
import useContainerStore from '../../stores/containerStore';
import { Colors } from '../../theme/theme';
import PaiButton from '../basic/PaiButton';

interface Props {
  open: boolean;

  handleCreateTextVariant(): void;

  handleOpenProjectNameDialog(): void;

  handleClose(): void;
}

const SaveAsProjectDialog: React.FC<Props> = ({ open, handleCreateTextVariant, handleOpenProjectNameDialog, handleClose }) => {
  const { classes } = useStyles();
  const { t } = useTranslation();

  const container = useContainerStore((state) => state.panelContainer);

  return (
    <Dialog open={open} onClose={handleClose} classes={{ paper: classes.paper }} fullWidth={true} maxWidth={'xs'} container={container}>
      <DialogTitle className={classes.title}>
        <Typography className={classes.titleText}>{t('saveContentTitle')}</Typography>
      </DialogTitle>
      <DialogContent className={classes.content}>
        <Typography className={classes.text}>{t('saveContent')}</Typography>
      </DialogContent>
      <DialogActions className={classes.actions}>
        <ButtonBase className={classes.actionTextButton} onClick={handleCreateTextVariant}>
          <Typography className={classes.actionText}>{t('no')}</Typography>
        </ButtonBase>
        <PaiButton text={t('yes')} action={handleOpenProjectNameDialog} />
      </DialogActions>
    </Dialog>
  );
};

const useStyles = makeStyles()((theme) => ({
  paper: {
    borderRadius: 0,
  },
  title: {
    background: theme.palette.primary.main,
  },
  titleText: {
    fontSize: '15px',
    fontWeight: 'bold',
    textTransform: 'uppercase',
    color: '#FFF',
    textAlign: 'center',
  },
  content: {
    padding: '20px 24px !important',
  },
  text: {
    fontSize: '13px',
  },
  actions: {
    display: 'flex',
    alignItems: 'center',
    justifyContent: 'flex-end',
    gap: '32px',
    padding: '0 24px 20px 24px',
  },
  actionTextButton: {
    display: 'flex',
    justifyContent: 'center',
    alignItems: 'center',
  },
  actionText: {
    color: Colors.GREY_SHADE_4,
    fontSize: '12px',
    textDecoration: 'underline',
    '&:hover': {
      textDecoration: 'underline',
      color: theme.palette.secondary.main,
    },
  },
}));

export default SaveAsProjectDialog;
