import { Grid } from '@mui/material';
import React from 'react';
import { SideBarSelection, Sources, TooltipContentType } from '../../enums/enums';
import { RelationshipQuality } from '../../types/analysis';
import { Assessment } from '../../types/assessment';
import { ISuggestionItem, Scores, SidebarNote } from '../../types/augmentedWriting';
import { ProfileValues } from '../../types/contact';
import AnalysisResults from '../analysis/AnalysisResults/AnalysisResults';
import NoAssessment from '../analysis/NoAssessment';
import Templates from '../analysis/Templates/Templates';
import Options from '../options/Options';
import GenerateText from '../textGeneration/GenerateText';
import TextOptimization from '../textOptimization/TextOptimization';

interface Props {
  activeSelection?: SideBarSelection;

  contactAssessment?: Assessment;
  contactProfile?: ProfileValues;
  userProfile?: ProfileValues;

  scores: Scores;
  sidebarNotes: SidebarNote[];
  allSuggestions: ISuggestionItem[];

  relationshipQuality?: RelationshipQuality;

  onCategoryClick?(category: string | undefined, composedCategory: any, source: Sources, removeText?: string): void;

  insertAtPosition: (word: string, highlightId: string, type: TooltipContentType) => void;

  skipSuggestion(content: any): () => void;

  ignoreSuggestion(content: any, id: string): () => void;
}

const SelectionContent: React.FC<Props> = ({
  scores,
  sidebarNotes,
  allSuggestions,
  contactAssessment,
  contactProfile,
  userProfile,
  relationshipQuality,
  activeSelection,
  onCategoryClick,
  insertAtPosition,
  skipSuggestion,
  ignoreSuggestion,
}) => {
  const renderSelectedContent = () => {
    switch (activeSelection) {
      case SideBarSelection.ANALYSIS:
        return (
          <AnalysisResults
            contactAssessment={contactAssessment}
            contactProfile={contactProfile}
            userProfile={userProfile}
            relationshipQuality={relationshipQuality}
          />
        );
      case SideBarSelection.TEXT_GENERATION:
        return <GenerateText contactAssessment={contactAssessment}  />;
      case SideBarSelection.TEXT_OPTIMIZATION:
        return (
          <TextOptimization
            contactAssessment={contactAssessment}
            contactProfile={contactProfile}
            userProfile={userProfile}
            scores={scores}
            sidebarNotes={sidebarNotes}
            allSuggestions={allSuggestions}
            onCategoryClick={onCategoryClick}
            insertAtPosition={insertAtPosition}
            skipSuggestion={skipSuggestion}
            ignoreSuggestion={ignoreSuggestion}
          />
        );
      case SideBarSelection.TEMPLATES:
        return <Templates />;

      case SideBarSelection.OPTIONS:
        return <Options />;
      default:
        return <></>;
    }
  };
  return (
    <Grid container={true}>
      {!contactAssessment && activeSelection !== SideBarSelection.OPTIONS ? (
        <Grid item={true} xs={12}>
          <NoAssessment />
        </Grid>
      ) : (
        <>
          <Grid item={true} xs={12}>
            {renderSelectedContent()}
          </Grid>
        </>
      )}
    </Grid>
  );
};

export default SelectionContent;
