import { List, Typography } from '@mui/material';
import React from 'react';
import { makeStyles } from 'tss-react/mui';
import { TooltipContentType } from '../../../enums/enums';
import { GrammarReplacement } from '../../../types/augmentedWriting';
import Optimization from './Optimization';

interface Props {
  grammarReplacement: GrammarReplacement;

  insertAtPosition: (word: string, highlightId: string, type: TooltipContentType) => void;
}

const GrammarContent: React.FC<Props> = ({ grammarReplacement, insertAtPosition }) => {
  const { classes } = useStyles();

  return (
    <div>
      <Typography className={classes.explanation}>{grammarReplacement.text}</Typography>
      <List disablePadding={true}>
        {grammarReplacement.suggestions.map((suggestion, index) => (
          <Optimization key={index} suggestion={suggestion}
            contentType={TooltipContentType.GRAMMAR_REPLACEMENT} ranking_index={grammarReplacement.ranking_index}
            insertAtPosition={insertAtPosition} />
        ))}
      </List>
    </div>
  );
};

const useStyles = makeStyles()((_theme) => ({
  explanation: {
    fontSize: '11px',
    marginBottom: '8px',
  },
}));

export default GrammarContent;
