import create from 'zustand';

interface DiagnosticTooltipStoreState {
  open: boolean;
  anchorElement: HTMLElement | null;
  text: string;

  handleOpen: (anchorElement: HTMLElement | null, text: string) => void;

  handleClose: () => void;
}

const useDiagnosticTooltipStore = create<DiagnosticTooltipStoreState>((set) => ({
  open: false,
  anchorElement: null,
  text: '',

  handleOpen(anchorElement: HTMLElement | null, text: string) {
    set(() => ({ open: true, anchorElement, text }));
  },

  handleClose() {
    set(() => ({ open: false, anchorElement: null, text: '' }));
  },
}));

export default useDiagnosticTooltipStore;
