import { Stack, Typography } from '@mui/material';
import _ from 'lodash';
import React from 'react';
import { useTranslation } from 'react-i18next';
import { makeStyles } from 'tss-react/mui';
import { ProfileValues } from '../../../types/contact';
import Legend from './Legend';
import MatchCompareGraph from './MatchCompareGraph';
import MotiveChart from './MotiveChart';

interface Props {
  contactProfile?: ProfileValues;
  userProfile?: ProfileValues;
  clickedChartCategoryKey?: string;

  onChartCategoryClicked?(category: any): void;
}

const TextOptimizationResults: React.FC<Props> = ({ contactProfile, userProfile, clickedChartCategoryKey, onChartCategoryClicked }) => {
  const { classes } = useStyles();
  const { t } = useTranslation();

  return (
    <div>
      <Stack spacing={1}>
        {!_.isNil(contactProfile) ? <Legend hideOwn={_.isNil(userProfile)} /> : null}
        {!_.isNil(contactProfile) ? (
          <div className={classes.card}>
            <Typography className={classes.title}>{t('motiveMatch')}</Typography>
            <MotiveChart
              contactScores={contactProfile}
              userScores={userProfile}
              clickedChartCategoryKey={clickedChartCategoryKey}
              onChartCategoryClicked={onChartCategoryClicked}
            />
          </div>
        ) : null}
        {!_.isNil(contactProfile?.authenticity) ? (
          <MatchCompareGraph
            title={t('languageStyleMatch')}
            categoryKey={'authenticity'}
            leftText={t('formal')}
            rightText={t('informal')}
            contactScore={contactProfile?.authenticity}
            userScore={userProfile?.authenticity}
            clickedChartCategoryKey={clickedChartCategoryKey}
            onChartCategoryClicked={onChartCategoryClicked}
          />
        ) : null}
      </Stack>
    </div>
  );
};

const useStyles = makeStyles()((_theme) => ({
  title: {
    fontSize: '12px',
    fontWeight: 900,
    textTransform: 'uppercase',
    textAlign: 'center',
    whiteSpace: 'pre-wrap',
    marginBottom: '8px',
  },
  card: {
    width: '100%',
    background: '#FFF',
    padding: '8px',
  },
}));

export default TextOptimizationResults;
