import { ButtonBase, darken, Stack, Typography } from '@mui/material';
import _ from 'lodash';
import { useTranslation } from 'react-i18next';
import { makeStyles } from 'tss-react/mui';
import { Colors } from '../../theme/theme';
import GeneratedTextItem from './GeneratedTextItem';

interface Props {
  generatedText: string;
  score: number | null;

  textGenerationLoading: boolean;
  analysisLoading: boolean;
  formatTextLoading: boolean;

  textVariants: string[];

  copyGeneratedText(text: string): () => void;

  handleBackClick(): void;

  createTextVariantStream(): void;
}

const SecondStepGeneratedTexts: React.FC<Props> = ({
  generatedText,
  score,
  textGenerationLoading,
  analysisLoading,
  formatTextLoading,
  textVariants,
  copyGeneratedText,
  handleBackClick,
  createTextVariantStream,
}) => {
  const { t } = useTranslation();
  const { classes } = useStyles();

  const loading = textGenerationLoading || analysisLoading || formatTextLoading;

  const showTextGenButton = textVariants.length > 0 && textVariants.length < 3 && !_.isNil(createTextVariantStream);

  return (
    <Stack className={classes.container} spacing={2}>
      {!loading && !_.isNil(score) ? <Typography className={classes.instruction}>{t('textGenerationSuccessInstruction')}</Typography> : null}
      <GeneratedTextItem
        text={generatedText}
        score={score}
        copyGeneratedText={copyGeneratedText}
        textGenerationLoading={textGenerationLoading}
        analysisLoading={analysisLoading}
        formatTextLoading={formatTextLoading}
      />
      <Stack direction={'row'} justifyContent={'center'} alignItems={'center'} gap={2}>
        <ButtonBase onClick={handleBackClick} disabled={loading}>
          <Typography className={classes.actionText}>{t('back')}</Typography>
        </ButtonBase>
        {showTextGenButton ? (
          <ButtonBase onClick={createTextVariantStream} disabled={loading}>
            <Typography className={classes.actionText}>{t('generateAnotherText')}</Typography>
          </ButtonBase>
        ) : null}
      </Stack>
    </Stack>
  );
};

const useStyles = makeStyles()((theme) => ({
  container: {
    height: 'calc(100% - 39px - 16px - 20px)',
    overflow: 'auto',
    overflowX: 'hidden',
    '&::-webkit-scrollbar': {
      width: '6px',
    },
    '&::-webkit-scrollbar-track': {
      background: '#FFF',
      borderRadius: '100px',
    },
    '&::-webkit-scrollbar-thumb': {
      background: Colors.GREY_SHADE_1,
      borderRadius: '100px',
      '&:hover': {
        background: darken(Colors.GREY_SHADE_1, 0.25),
      },
    },
  },
  buttonContainer: {
    display: 'flex',
    justifyContent: 'center',
    marginBottom: '16px',
  },
  instruction: {
    fontSize: '12px',
    textAlign: 'center',
    color: Colors.GREY_SHADE_4,
  },
  actionText: {
    fontSize: '12px',
    color: Colors.GREY_SHADE_4,
    textDecoration: 'underline',
    '&:hover': {
      color: theme.palette.primary.main,
    },
  },
}));

export default SecondStepGeneratedTexts;
