import create from 'zustand';
import { ISuggestionItem, Scores, SidebarNote } from '../types/augmentedWriting';

const defaultScores = {
  diversity: -0.1,
  overall: 0,
  percentiles: {
    profile: {
      diversity: -0.1,
      jointPosAchieve: 0,
      jointPosPower: 0,
      jointPosAffil: 0,
      authenticity: 0,
      regFocus: 0,
      gender: 0,
    },
    text: {
      diversity: -0.1,
      jointPosAchieve: 0,
      jointPosPower: 0,
      jointPosAffil: 0,
      authenticity: 0,
      regFocus: 0,
      gender: 0,
    },
  },
};

interface AugmentedWritingStoreState {
  isAnalyzed: boolean;
  analysisLoading: boolean;
  userDone: boolean;
  fingerprints: string[];

  allSuggestions: ISuggestionItem[];
  scores: Scores;
  sidebarNotes: SidebarNote[];

  setIsAnalyzed: (analyzed: boolean) => void;

  setAnalysisLoading: (loading: boolean) => void;

  setUserDone: (done: boolean) => void;

  setFingerprints: (newFingerprints: string[]) => void;

  setAllSuggestions: (newSuggestions: ISuggestionItem[]) => void;

  setScores: (newScores: Scores) => void;

  setSidebarNotes: (newSidebarNotes: SidebarNote[]) => void;
}

const useAugmentedWritingStore = create<AugmentedWritingStoreState>((set) => ({
  isAnalyzed: false,
  analysisLoading: false,
  userDone: false,
  fingerprints: [],

  allSuggestions: [],
  scores: defaultScores,
  sidebarNotes: [],

  setIsAnalyzed(analyzed: boolean) {
    set(() => ({ isAnalyzed: analyzed }));
  },

  setAnalysisLoading(loading: boolean) {
    set(() => ({ analysisLoading: loading }));
  },

  setUserDone(done: boolean) {
    set(() => ({ userDone: done }));
  },

  setFingerprints(newFingerprints: string[]) {
    set(() => ({ fingerprints: newFingerprints }));
  },

  setAllSuggestions(newSuggestions) {
    set(() => ({ allSuggestions: newSuggestions }));
  },

  setScores(newScores) {
    set(() => ({ scores: newScores }));
  },

  setSidebarNotes(newSidebarNotes) {
    set(() => ({ sidebarNotes: newSidebarNotes }));
  },
}));

export default useAugmentedWritingStore;
