import create from 'zustand';
import { Products } from '../enums/enums';
import { User } from '../types/account';
import { LicenseInfo } from '../types/license';

interface UserStore {
  user?: User;
  license?: LicenseInfo;
  quotaLimitReached: boolean;

  setUser: (user: User) => void;

  setLicense: (license: LicenseInfo) => void;

  isFreemium: () => boolean;

  setQuotaLimitReached: (reached: boolean) => void;

  resetUser: () => void;
}

const useUserStore = create<UserStore>((set, get) => ({
  user: undefined,
  license: undefined,
  quotaLimitReached: false,

  setUser(user) {
    set(() => ({ user: user }));
  },

  setLicense(license) {
    set(() => ({ license: license }));
  },

  isFreemium() {
    const state = get();

    return state.license?.package === Products.FREMIUM;
  },

  setQuotaLimitReached(reached) {
    set(() => ({ quotaLimitReached: reached }));
  },

  resetUser() {
    set(() => ({ user: undefined, license: undefined, quotaLimitReached: false }));
  },
}));

export default useUserStore;
