import { CircularProgress, TextField } from '@mui/material';
import React from 'react';
import { makeStyles } from 'tss-react/mui';

interface Props {
  value: string;
  placeholder?: string;
  loading?: boolean;

  onChange(event: React.ChangeEvent<HTMLInputElement>): void;

  onKeyUp?(): void;

  onKeyDown?(): void;
}

const PaiTextField: React.FC<Props> = ({ value, placeholder, loading, onChange, onKeyUp, onKeyDown }) => {
  const { classes } = useStyles();

  return (
    <TextField
      className={classes.textfield}
      InputProps={{
        disableUnderline: true,
        classes: { input: classes.fieldInput },
        endAdornment: loading ? <CircularProgress className={classes.spinner} /> : null,
      }}
      variant={'standard'}
      fullWidth={true}
      placeholder={placeholder}
      value={value}
      onChange={onChange}
      onKeyUp={onKeyUp}
      onKeyDown={onKeyDown}
    />
  );
};

const useStyles = makeStyles()((theme) => ({
  textfield: {
    border: `1px solid ${theme.palette.primary.main}`,
    padding: '2px',
    background: '#FFF',
    '& .MuiSvgIcon-root': {
      color: theme.palette.primary.main,
      height: '100%',
      top: 0,
      background: '#FFF',
    },
  },
  fieldInput: {
    background: theme.palette.tertiary.main,
    fontSize: '13px',
    padding: '8px 12px',
    minHeight: 'calc(39px - 8px - 8px)',
    '&::placeholder': {
      opacity: 0.67,
      fontSize: '13px',
    },
    '&:focus': {
      '&::placeholder': {
        opacity: 0,
      },
    },
  },
  spinner: {
    color: theme.palette.primary.main,
    width: '32px !important',
    height: 'auto !important',
    margin: '0 2px',
  },
}));

export default PaiTextField;
