import _ from 'lodash';
import React, { useCallback, useState } from 'react';
import { makeStyles } from 'tss-react/mui';
import shallow from 'zustand/shallow';
import { PlaceholderTokens } from '../../../enums/enums';
import useContainerStore from '../../../stores/containerStore';
import useProfileStore from '../../../stores/profileStore';
import useTemplateStore from '../../../stores/templatesStore';
import useUserStore from '../../../stores/userStore';
import { Template } from '../../../types/templates';
import { getHostDomain } from '../../../utils/helper';
import EmailTemplateListItem from './TemplateListItem';

const Templates: React.FC = () => {
  const [copied, setCopied] = useState<string | undefined>();
  const tooltipContainerElement = useContainerStore((state) => state.tooltipContainer);

  const { classes } = useStyles();

  const templates = useTemplateStore((state) => state.templates);
  const user = useUserStore((state) => state.user);
  const { contact } = useProfileStore((state) => ({ contact: state.contact }), shallow);

  const replacePlaceholders = useCallback(
    (text: string) => {
      let tempText = text;

      const ownForeNameRe = new RegExp(PlaceholderTokens.OWN_FORENAME, 'g');
      const ownSurNameRe = new RegExp(PlaceholderTokens.OWN_SURNAME, 'g');
      const ownEmailRe = new RegExp(PlaceholderTokens.OWN_EMAIL, 'g');
      const linkedinForeNameRe = new RegExp(PlaceholderTokens.LINKEDIN_FORENAME, 'g');
      const linkedinSurNameRe = new RegExp(PlaceholderTokens.LINKEDIN_SURNAME, 'g');

      if (!_.isNil(user) && !_.isNil(user.firstName)) {
        tempText = tempText.replace(ownForeNameRe, user.firstName);
      }

      if (!_.isNil(user) && !_.isNil(user.lastName)) {
        tempText = tempText.replace(ownSurNameRe, user.lastName);
      }

      if (!_.isNil(user) && !_.isNil(user.email)) {
        tempText = tempText.replace(ownEmailRe, user.email);
      }

      if (!_.isNil(contact) && !_.isNil(contact.firstName)) {
        tempText = tempText.replace(linkedinForeNameRe, contact.firstName);
      }

      if (!_.isNil(contact) && !_.isNil(contact.lastName)) {
        tempText = tempText.replace(linkedinSurNameRe, contact.lastName);
      }

      return tempText;
    },
    [user, contact]
  );

  const copyTextToClipboard = (template: Template) => {
    return async () => {
      try {
        const replacedText = !_.isNil(template.body) ? replacePlaceholders(template.body) : '';
        await navigator.clipboard.writeText(replacedText);
        setCopied(template.key);
      } catch (e) {
        console.log(e);
      }
    };
  };

  const handleOpenEditTemplates = (template: Template) => {
    return async (event: React.MouseEvent) => {
      event.stopPropagation();
      event.preventDefault();

      const hostDomain = await getHostDomain();
      window.open(`${hostDomain}/dashboard/templates/text-optimization?template=${template.key}`);
    };
  };

  return (
    <div className={classes.card}>
      {templates.map((template, index) => (
        <EmailTemplateListItem
          key={index}
          tooltipContainerElement={tooltipContainerElement}
          template={template}
          copied={copied}
          replacePlaceholders={replacePlaceholders}
          copyTextToClipboard={copyTextToClipboard}
          handleOpenEditTemplates={handleOpenEditTemplates}
        />
      ))}
    </div>
  );
};

const useStyles = makeStyles()((_theme) => ({
  card: {
    width: '100%',
    background: '#FFF',
    padding: '8px 16px',
  },
}));

export default Templates;
