import { Stack, Typography } from '@mui/material';
import _ from 'lodash';
import React, { useState } from 'react';
import { Trans, useTranslation } from 'react-i18next';
import { makeStyles } from 'tss-react/mui';
import { ProductGroups } from '../../enums/enums';
import { Colors } from '../../theme/theme';
import { getHostDomain } from '../../utils/helper';
import { getLogos } from '../../utils/imageUtils';
import PaiButton from '../basic/PaiButton';
import PricingSidebarItem from './QuotaLimitReached/PricingSidebarItem';

const QuotaLimitReached: React.FC = () => {
  const { classes, cx } = useStyles();
  const { t } = useTranslation();

  const [activePricing, setActivePricing] = useState<ProductGroups>(ProductGroups.LEAD_BOOSTER);

  const logo = getLogos().product_logo_white;

  const openLicenseOverview = async () => {
    const hostDomain = await getHostDomain();

    const product =
      activePricing === ProductGroups.LEAD_BOOSTER ? 'lead-booster' : activePricing === ProductGroups.HR_BOOSTER ? 'hr-booster' : 'lead-booster';

    window.open(`${hostDomain}/dashboard/upgrade?product=${product}`, '_blank');
  };

  const openEmail = () => {
    window.open('mailto:simon.tschuertz@100worte.de', '_blank');
  };

  const handleActivePricingChange = (newActive: ProductGroups) => {
    return () => {
      setActivePricing(newActive);
    };
  };

  return (
    <div className={classes.card}>
      <div className={classes.header}>
        <img className={classes.logo} src={logo} alt={'pai-logo'} />
      </div>
      <Stack className={classes.content} gap={2}>
        <div>
          <Typography className={classes.subTitle}>{t('limitReachedText1')}</Typography>
          <Typography className={classes.text}>{t('limitReachedText2')}</Typography>
        </div>
        <Stack className={classes.selectionContainer} gap={1}>
          <PricingSidebarItem product={ProductGroups.LEAD_BOOSTER} activePricing={activePricing} setActive={handleActivePricingChange} />
          <PricingSidebarItem product={ProductGroups.HR_BOOSTER} activePricing={activePricing} setActive={handleActivePricingChange} />
        </Stack>
        <PaiButton text={t('licenseOverview')} action={openLicenseOverview} disabled={_.isNil(activePricing)} />
        <Typography className={cx(classes.text, 'grey')}>
          <Trans i18nKey={'limitReachedSpecialPlan'}>
            Solltest Du einen speziellen Plan für dich oder dein Unternehmen benötigen, melde dich bitte direkt bei
            <span className={classes.link} onClick={openEmail}>
              simon.tschuertz@100worte.de
            </span>
            und wir finden zusammen eine passende Lösung.
          </Trans>
        </Typography>
      </Stack>
    </div>
  );
};

const useStyles = makeStyles()((theme) => ({
  card: {
    background: '#FFF',
  },
  header: {
    height: '100px',
    width: '100%',
    background: Colors.BLUE,
    display: 'flex',
    justifyContent: 'center',
    alignItems: 'center',
  },
  logo: {
    height: '70px',
    width: 'auto',
  },
  content: {
    padding: '24px 16px',
  },
  subTitle: {
    fontSize: '13px',
    fontWeight: 900,
    marginBottom: '8px',
  },
  selectionContainer: {
    padding: '8px',
    background: theme.palette.tertiary.main,
  },
  text: {
    fontSize: '12px',
    '&.grey': {
      marginTop: '8px',
      color: Colors.GREY_SHADE_4,
    },
  },
  link: {
    cursor: 'pointer',
    color: theme.palette.primary.main,
    textDecorationLine: 'underline',
    textDecorationColor: theme.palette.primary.main,
    '&:hover': {
      color: theme.palette.secondary.main,
      textDecorationColor: theme.palette.secondary.main,
    },
  },
}));

export default QuotaLimitReached;
