import { alpha, useTheme } from '@mui/material';
import $ from 'jquery';
import _ from 'lodash';
import React, { useCallback, useEffect, useState } from 'react';
import { AugmentedWritingActions } from '../../enums/actions';
import { Ids, TooltipContentType, ZIndices } from '../../enums/enums';
import useDiagnosticTooltipStore from '../../stores/diagnosticTooltipStore';
import useInteractiveTooltipStore from '../../stores/interactiveTooltipStore';
import {
  Deletion,
  DiagnosticMode,
  GrammarReplacement,
  HighlightTexts,
  HighlightType,
  ISuggestionItem,
  Insertion,
  Paraphrase,
  Suggestion,
} from '../../types/augmentedWriting';
import { getMostInnerTextNode, sendMessageToBackground } from '../../utils/helper';

interface Props {
  activeElement: HTMLDivElement | HTMLTextAreaElement | null;
  highlight?: HighlightType | Suggestion | Insertion | Deletion | GrammarReplacement | Paraphrase;
  highlightTexts?: HighlightTexts;
  diagnosticHighlights?: HighlightType[];
  firstSuggestion?: ISuggestionItem;

  diagnosticMode: DiagnosticMode;

  grammar?: boolean;
  paraphrase?: boolean;

  windowScrollY: number;
  elementScrollY: number;
  parentElementScrollTop: number | undefined;
  resizeElement: { height: number; width: number };
  resizeWindow: { height: number; width: number };
}

const Highlight: React.FC<Props> = ({
  activeElement,
  highlight,
  highlightTexts,
  diagnosticHighlights,
  firstSuggestion,
  diagnosticMode,
  grammar,
  paraphrase,
  windowScrollY,
  elementScrollY,
  parentElementScrollTop,
  resizeWindow,
  resizeElement,
}) => {
  const theme = useTheme();

  const [rects, setRects] = useState<DOMRect[]>();
  const [activeElementRects, setActiveElementRects] = useState<DOMRect>();

  const interactiveTooltipOpen = useInteractiveTooltipStore((state) => state.open);
  const handleOpenInteractiveTooltip = useInteractiveTooltipStore((state) => state.handleOpen);

  const diagnosticTooltipAnchorElement = useDiagnosticTooltipStore((state) => state.anchorElement);
  const handleOpenDiagnosticTooltip = useDiagnosticTooltipStore((state) => state.handleOpen);
  const handleCloseDiagnosticTooltip = useDiagnosticTooltipStore((state) => state.handleClose);

  useEffect(() => {
    setActiveElementRects(activeElement?.getBoundingClientRect());
  }, [activeElement, resizeElement, resizeWindow, windowScrollY, parentElementScrollTop, elementScrollY]);

  const getHighlightColor = (hl: HighlightType | Suggestion | Insertion | Deletion | GrammarReplacement | Paraphrase | undefined) => {
    if (paraphrase) {
      return theme.palette.primary.main;
    } else if (grammar) {
      return '#707070';
    } else {
      return theme.palette.primary.main;
    }
  };

  const getHighlightID = (index?: number) => {
    if (grammar) {
      return !_.isNil(index)
        ? `${TooltipContentType.GRAMMAR_REPLACEMENT}-${(highlight as GrammarReplacement).ranking_index}-${index}`
        : `${TooltipContentType.GRAMMAR_REPLACEMENT}-${(highlight as GrammarReplacement).ranking_index}`;
    } else if (paraphrase) {
      return !_.isNil(index)
        ? `${TooltipContentType.PARAPHRASE}-${(highlight as Paraphrase).ranking_index}-${index}`
        : `${TooltipContentType.PARAPHRASE}-${(highlight as Paraphrase).ranking_index}`;
    } else {
      return `diagnostic-${highlight?.highlightPosition[0]}-${highlight?.highlightPosition[1]}`;
    }
  };

  const atSamePosition = (hl: Suggestion | Insertion | Deletion | GrammarReplacement | Paraphrase) => {
    if (diagnosticHighlights && diagnosticHighlights.length > 0) {
      return diagnosticHighlights.some(
        (dHighlight) => dHighlight.highlightPosition[0] === hl.highlightPosition[0] && dHighlight.highlightPosition[1] === hl.highlightPosition[1]
      );
    }
    return false;
  };

  const cursorHoverListener = useCallback(
    ({ clientX: x, clientY: y }) => {
      if (rects && !grammar && !paraphrase) {
        rects.forEach((rect) => {
          const currRect: DOMRect = rect;
          const isInX = x >= currRect?.x && x <= currRect?.x + currRect?.width;
          const isInY = y >= currRect?.y && y <= currRect?.y + currRect?.height;
          if (isInX && isInY && !interactiveTooltipOpen) {
            const highlightId = getHighlightID();
            const shadow = document.getElementById(Ids.HIGHLIGHTER_SHADOW_ROOT)?.shadowRoot;
            const element = shadow?.getElementById(highlightId);

            if (!_.isNil(element)) {
              const shownCategory = (highlight as HighlightType)?.categories.find((category) =>
                (diagnosticMode.composedCategory as string[]).includes(category)
              );
              const text = shownCategory ? highlightTexts?.[shownCategory] : '';

              handleOpenDiagnosticTooltip(element, text);
            }
          } else {
            if (!_.isNil(diagnosticTooltipAnchorElement) && diagnosticTooltipAnchorElement.id === getHighlightID()) {
              handleCloseDiagnosticTooltip();
            }

          }
        });
      }
    },
    [rects, highlight, grammar, paraphrase, diagnosticTooltipAnchorElement, interactiveTooltipOpen]
  );

  const cursorClickListener = useCallback(
    ({ clientX: x, clientY: y }) => {
      if (rects && (grammar || paraphrase)) {
        rects.forEach((rect, index) => {
          const currRect: DOMRect = rect;
          const isInX = x >= currRect?.x && x <= currRect?.x + currRect?.width;
          const isInY = y >= currRect?.y && y <= currRect?.y + currRect?.height;
          if (isInX && isInY && !interactiveTooltipOpen) {
            const highlightId = getHighlightID();
            const shadow = document.getElementById(Ids.HIGHLIGHTER_SHADOW_ROOT)?.shadowRoot;
            const elements: NodeListOf<HTMLElement> | undefined = shadow?.querySelectorAll(`.${highlightId}`);

            if (!_.isNil(elements) && !_.isEmpty(elements)) {
              const anchorElement = _.find(elements, (element) => +element.dataset.index! === index);

              if (!_.isNil(anchorElement)) {
                handleOpenInteractiveTooltip(
                  anchorElement,
                  grammar ? TooltipContentType.GRAMMAR_REPLACEMENT : paraphrase ? TooltipContentType.PARAPHRASE : undefined,
                  highlight as Paraphrase | GrammarReplacement
                );
              }
            }
          }
        });
      }
    },
    [rects, grammar, paraphrase, interactiveTooltipOpen]
  );

  useEffect(() => {
    document.addEventListener('mousemove', cursorHoverListener);
    document.addEventListener('click', cursorClickListener);
    return () => {
      document.removeEventListener('mousemove', cursorHoverListener);
      document.removeEventListener('click', cursorClickListener);
    };
  }, [cursorClickListener, cursorHoverListener]);

  const calcLines = (node: any, height: number) => {
    let heightRange = document.createRange();
    heightRange.setStart(node, 0);
    heightRange.setEnd(node, 1);
    const lineHeight = heightRange.getBoundingClientRect().height;

    return height / lineHeight;
  };

  useEffect(() => {
    if (highlight && activeElement) {
      const divElement = activeElement as HTMLDivElement;
      if (divElement.hasChildNodes()) {
        let range = document.createRange();
        const jqueryContents: any[] = $(divElement).contents();
        try {
          let prevLength = 0;
          _.forEach(jqueryContents, (node, index) => {
            const nodeList = getMostInnerTextNode(node);
            if (nodeList.length === 0 && node.nodeType === Node.TEXT_NODE) {
              nodeList.push(node);
            }
            _.forEach(nodeList, (textNode) => {
              if (
                highlight.highlightPosition[0] < (textNode.textContent?.length || 0) + prevLength + index &&
                highlight.highlightPosition[0] >= prevLength + index
              ) {
                try {
                  const start = highlight.highlightPosition[0] - prevLength - index;
                  const end = highlight.highlightPosition[1] - prevLength - index;

                  range.setStart(textNode, start);
                  range.setEnd(textNode, end);

                  const lines = calcLines(textNode, range.getBoundingClientRect().height);

                  if (lines > 1) {
                    const splitRects: DOMRect[] = [];
                    let lineStart = start;
                    for (let i = start; i <= end; i++) {
                      let highlightRange = document.createRange();
                      highlightRange.setStart(textNode, lineStart);
                      highlightRange.setEnd(textNode, i);
                      const height = highlightRange.getBoundingClientRect().height;
                      const highlightLines = calcLines(textNode, height);

                      if (highlightLines > 1) {
                        highlightRange.setStart(textNode, lineStart);
                        highlightRange.setEnd(textNode, i - 1);
                        splitRects.push(highlightRange.getBoundingClientRect());
                        lineStart = i - 1;
                      }
                      if (i === end) {
                        highlightRange.setStart(textNode, lineStart);
                        highlightRange.setEnd(textNode, end);
                        splitRects.push(highlightRange.getBoundingClientRect());
                      }
                    }
                    setRects(splitRects);
                  } else {
                    setRects([range.getBoundingClientRect()]);
                  }
                } catch (error) {
                  sendMessageToBackground({
                    action: AugmentedWritingActions.REMOVE_HIGHLIGHT_FROM_CLICKABLE_MODE,
                    body: { prevSuggestion: highlight },
                  });
                }
              }
              prevLength += textNode.textContent?.length || 0;
            });
          });
        } catch (e) {
          console.error(e);
        }
      }
    }
  }, [activeElement, highlight, activeElementRects]);

  return (
    <>
      {rects?.map((rect, index) => (
        <div
          id={getHighlightID()}
          className={getHighlightID()}
          data-highlight={JSON.stringify(highlight)}
          data-index={JSON.stringify(index)}
          style={{
            position: 'absolute',
            display: 'flex',
            top: activeElementRects ? rect?.top + 1 - activeElementRects?.top : undefined,
            left: activeElementRects ? rect.left - activeElementRects.left : undefined,
            width: rect?.width,
            height: rect?.height,
          }}
        >
          {grammar || paraphrase ? (
            <div
              style={{
                background:
                  firstSuggestion?.highlightId === getHighlightID() ? `${alpha(getHighlightColor(highlight), 0.1)}` : getHighlightColor(highlight),
                height: firstSuggestion?.highlightId === getHighlightID() ? 'calc(100% - 2px)' : '2px',
                marginTop: 'auto',
                width: '100%',
                zIndex: ZIndices.ACTION_HIGHLIGHT,
                visibility: atSamePosition(highlight as Suggestion | Insertion | Deletion | GrammarReplacement | Paraphrase) ? 'hidden' : 'visible',
                borderBottom: firstSuggestion?.highlightId === getHighlightID() ? `2px solid ${getHighlightColor(highlight)}` : undefined,
                borderTopLeftRadius: '4px',
                borderTopRightRadius: '4px',
              }}
            />
          ) : (
            <div
              style={{
                position: 'absolute',
                top: '-3px',
                height: '100%',
                width: '100%',
                borderBottom: `2px solid ${getHighlightColor(highlight)}`,
                background: `${alpha(getHighlightColor(highlight), 0.1)}`,
                zIndex: ZIndices.DIAGNOSTIC_HIGHLIGHT,
                borderTopLeftRadius: '4px',
                borderTopRightRadius: '4px',
              }}
            />
          )}
        </div>
      ))}
    </>
  );
};

export default Highlight;
