import $ from 'jquery';
import _ from 'lodash';

export const sendMessageToBackground = (content: any) => {
  try {
    chrome?.runtime?.sendMessage(content);
  } catch (e) {
    console.log(e);
  }
};

export const getHostDomain = () => {
  return new Promise<string>((resolve, reject) => {
    chrome?.storage?.local?.get('hostDomain', async ({ hostDomain }) => {
      if (!_.isNil(hostDomain)) {
        resolve(hostDomain as string);
      } else {
        const placeholderDomain = 'https://app.psychological.ai';
        console.error('Could not fetch host domain from storage!');
        resolve(placeholderDomain);
      }
    });
  });
};

export const getMostInnerTextNode = (element: HTMLDivElement) => {
  const treeWalker = document.createTreeWalker(element, NodeFilter.SHOW_TEXT);
  const nodeList: Node[] = [];

  while (treeWalker.nextNode()) {
    nodeList.push(treeWalker.currentNode);
  }
  return nodeList;
};

export const getTextFromActiveElement = (element: HTMLDivElement | HTMLTextAreaElement | null) => {
  let text;
  const tagName = element?.tagName;
  switch (tagName) {
    case 'TEXTAREA':
      const textElement = element as HTMLTextAreaElement;
      text = textElement?.value;
      break;
    case 'DIV':
      const divElement = element as HTMLDivElement;
      const jqueryContents: any[] = $(divElement).contents();
      let mergedText = '';
      _.forEach(jqueryContents, (node, index) => {
        if (node.innerText.trim() !== '') {
          if (index !== jqueryContents.length - 1) {
            mergedText += node.innerText.trim() + '\n';
          } else {
            mergedText += node.innerText.trim();
          }
        } else if (node.innerText === '\n') {
          mergedText += '\n';
        }
      });
      text = mergedText;
      break;
    default:
      break;
  }
  return text?.trim();
};
