import { ButtonBase, Divider, Stack, Typography } from '@mui/material';
import _ from 'lodash';
import React, { useEffect } from 'react';
import { Trans, useTranslation } from 'react-i18next';
import { makeStyles } from 'tss-react/mui';
import { Modes, Products, SideBarSelection } from '../../enums/enums';
import useUserStore from '../../stores/userStore';
import { Colors } from '../../theme/theme';
import { getHostDomain } from '../../utils/helper';
import { getLogos } from '../../utils/imageUtils';
import SidebarItem from './SidebarItem';

interface Props {
  activeSelection: SideBarSelection | undefined;
  mode: Modes;

  handleSelectionChange(selection: SideBarSelection): void;
}

const Sidebar: React.FC<Props> = ({ activeSelection, mode, handleSelectionChange }) => {
  const { classes } = useStyles();
  const { t } = useTranslation();
  const license = useUserStore((state) => state.license);

  const logo = getLogos().short_logo;

  useEffect(() => {
    if (mode === Modes.WRITER) {
      handleSelectionChange(SideBarSelection.TEXT_OPTIMIZATION);
    } else {
      handleSelectionChange(SideBarSelection.ANALYSIS);
    }
  }, [mode]);

  const openFeatureOverview = async () => {
    const hostDomain = await getHostDomain();
    window.open(`${hostDomain}/dashboard/feature-overview`, '_blank');
  };

  const openUpgradePage = async () => {
    const hostDomain = await getHostDomain();
    window.open(`${hostDomain}/dashboard/upgrade?source=linkedin`, '_blank');
  };

  const openBonusPage = async () => {
    const hostDomain = await getHostDomain();
    window.open(`${hostDomain}/dashboard/bonus`, '_blank');
  };

  const openHelp = () => {
    window.open('mailto:info@100Worte.de', '_blank');
  };

  const openAccountPage = async () => {
    const hostDomain = await getHostDomain();
    window.open(`${hostDomain}/dashboard/account`, '_blank');
  };

  const mapProductName = (product?: string) => {
    switch (product) {
      case Products.STARTER:
        return 'Lead\nBooster';
      case Products.PROFESSIONAL:
        return 'Lead\nBooster';
      case Products.MASTER:
        return 'Lead\nBooster';
      case Products.FREMIUM:
        return 'Freemium';
      case Products.HR_LINKEDIN:
        return 'HR\nBooster';
      default:
        return 'Freemium';
    }
  };

  const mapProductColor = (product?: string) => {
    switch (product) {
      case Products.STARTER:
        return Colors.MAGENTA;
      case Products.PROFESSIONAL:
        return Colors.MAGENTA;
      case Products.MASTER:
        return Colors.MAGENTA;
      case Products.FREMIUM:
        return Colors.BLUE;
      case Products.HR_LINKEDIN:
        return Colors.ORANGE;
      default:
        return Colors.BLUE;
    }
  };

  return (
    <div className={classes.sidebar}>
      <div className={classes.sidebarItems}>
        <ButtonBase onClick={openFeatureOverview}>
          <img className={classes.logo} src={logo} alt={'logo'} />
        </ButtonBase>
        <Divider className={classes.divider} />
        <Stack gap={2.5} alignItems={'center'}>
          {_.map(
            _.filter(SideBarSelection, (item) => item !== SideBarSelection.OPTIONS),
            (selection, index) => {
              return (
                <SidebarItem
                  key={index}
                  text={t(`${selection}`)}
                  number={
                    selection === SideBarSelection.ANALYSIS
                      ? 1
                      : selection === SideBarSelection.TEXT_GENERATION
                      ? 2
                      : selection === SideBarSelection.TEXT_OPTIMIZATION
                      ? 3
                      : selection === SideBarSelection.TEMPLATES
                      ? 4
                      : undefined
                  }
                  action={() => handleSelectionChange(selection)}
                  active={selection === activeSelection}
                />
              );
            }
          )}
        </Stack>
        <Divider className={classes.divider} />
        <Stack spacing={1.5} alignItems={'center'}>
          <SidebarItem text={t('account')} underline={true} action={openAccountPage} />
          <Typography
            className={classes.contactsCountText}
            fontWeight={900}
            style={{ visibility: !_.isNil(license) ? 'visible' : 'hidden', color: mapProductColor(license?.package), marginTop: '14px' }}
          >
            {mapProductName(license?.package)}
          </Typography>
          <Typography className={classes.contactsCountText} style={{ visibility: !_.isNil(license) ? 'visible' : 'hidden' }}>
            <Trans i18nKey={'contactsCount'} values={{ used: license?.remaining, total: license?.total }}>
              0 <span className={classes.bold}>/0</span> contacts
            </Trans>
          </Typography>
        </Stack>
        <Divider className={classes.divider} />
        <Stack spacing={2} alignItems={'center'}>
          <SidebarItem
            text={t(`${SideBarSelection.OPTIONS}`)}
            active={SideBarSelection.OPTIONS === activeSelection}
            underline={true}
            action={() => handleSelectionChange(SideBarSelection.OPTIONS)}
          />
          <SidebarItem text={t('upgrade')} underline={true} action={openUpgradePage} />
          <SidebarItem text={t('bonus')} underline={true} action={openBonusPage} />
          <SidebarItem text={t('help')} underline={true} action={openHelp} />
        </Stack>
      </div>
    </div>
  );
};

const useStyles = makeStyles()((theme) => ({
  sidebar: {
    width: '100%',
    display: 'flex',
    flexDirection: 'column',
    alignItems: 'center',
    paddingBottom: '16px',
  },
  sidebarItems: {
    display: 'flex',
    justifyContent: 'center',
    alignItems: 'center',
    flexDirection: 'column',
  },
  logo: {
    width: '40px',
    height: '40px',
  },
  divider: {
    width: '40px',
    margin: '16px 0',
  },
  contactsCountText: {
    fontSize: '11px',
    lineHeight: 1.4,
    textAlign: 'center',
    color: Colors.GREY_SHADE_4,
    whiteSpace: 'pre-wrap',
  },
  bold: {
    fontWeight: 900,
  },
}));

export default Sidebar;
