import { ThemeProvider } from '@mui/material/styles';
import React from 'react';
import { MemoryRouter as Router } from 'react-router-dom';
import App from './App';
import WrappedJssComponent from './components/ui/WrappedJssComponent';
import { Ids } from './enums/enums';
import { setupProject } from './project-setup';
import theme from './theme/theme';

// Renders the web-app/extension content to DOM.
setupProject({
  rootElement: (
    <React.StrictMode>
      <WrappedJssComponent rootId={Ids.PANEL_SHADOW_ROOT} containerId={Ids.PANEL_SHADOW_ROOT_CONTAINER}>
        <Router>
          <ThemeProvider theme={theme}>
            <App />
          </ThemeProvider>
        </Router>
      </WrappedJssComponent>
    </React.StrictMode>
  ),
  injectExtensionTo: 'body',
  injectWebAppTo: '#root',
});