import { ButtonBase, Typography } from '@mui/material';
import _ from 'lodash';
import React from 'react';
import { makeStyles } from 'tss-react/mui';
import { Colors } from '../../../theme/theme';

interface Props {
  title: string;
  categoryKey: string;
  leftText: string;
  rightText: string;
  contactScore: number | undefined;
  userScore: number | undefined;

  clickedChartCategoryKey?: string;

  onChartCategoryClicked?(category: string | string[]): void;
}

const isAlmostEqual = (firstVal: number, secondVal: number) => {
  const difference = Math.abs(firstVal - secondVal);
  return difference > 1.25 ? false : true;
};

const MatchCompareGraph: React.FC<Props> = ({
  title,
  categoryKey,
  leftText,
  rightText,
  contactScore,
  userScore,
  clickedChartCategoryKey,
  onChartCategoryClicked,
}) => {
  const { classes, cx } = useStyles({
    contactScoreNorm: (contactScore ?? 0) * 100,
    userScoreNorm: (userScore ?? 0) * 100,
  });

  return (
    <div className={classes.languageMatch}>
      <ButtonBase
        onClick={() => (!_.isNil(onChartCategoryClicked) ? onChartCategoryClicked(categoryKey) : undefined)}
        style={{ width: '100%' }}
        disabled={_.isNil(onChartCategoryClicked) || _.isNil(userScore)}
      >
        <Typography
          className={cx(
            classes.title,
            _.isNil(onChartCategoryClicked) || _.isNil(userScore)
              ? null
              : clickedChartCategoryKey !== categoryKey
              ? classes.clickable
              : classes.clicked
          )}
        >
          {title}
        </Typography>
      </ButtonBase>
      <div className={classes.graph}>
        {!_.isNil(contactScore) ? <div className={classes.contactScore} /> : null}
        {!_.isNil(userScore) ? <div className={classes.userScore} /> : null}
        <div className={classes.leftText}>
          <Typography className={classes.graphText}>{leftText}</Typography>
        </div>
        <div className={classes.rightText}>
          <Typography className={classes.graphText}>{rightText}</Typography>
        </div>
      </div>
    </div>
  );
};

const useStyles = makeStyles<{ contactScoreNorm: number; userScoreNorm: number }>()((theme, { contactScoreNorm, userScoreNorm }) => ({
  languageMatch: {
    width: '100%',
    background: '#FFF',
    padding: '8px 16px',
  },
  title: {
    fontSize: '12px',
    fontWeight: 900,
    textTransform: 'uppercase',
    textAlign: 'center',
    whiteSpace: 'pre-wrap',
    marginBottom: '10px',
  },
  clickable: {
    textDecoration: 'underline',
    '&:hover': {
      color: theme.palette.primary.main,
      textDecoration: 'underline',
    },
  },
  clicked: {
    color: theme.palette.primary.main,
    textDecoration: 'underline',
  },
  graph: {
    position: 'relative',
    height: '4px',
    width: '100%',
    background: Colors.GREY_SHADE_1,
    display: 'flex',
    alignItems: 'center',
    margin: '5.5px 0 24px 0',
  },
  contactScore: {
    height: isAlmostEqual(contactScoreNorm, userScoreNorm) ? '10px' : '15px',
    width: isAlmostEqual(contactScoreNorm, userScoreNorm) ? '10px' : '15px',
    zIndex: isAlmostEqual(contactScoreNorm, userScoreNorm) ? 9999 : undefined,
    position: 'absolute',
    background: theme.palette.secondary.main,
    left: `calc(${contactScoreNorm}% - 7.5px)`,
    border: '1px solid #FFF',
  },
  userScore: {
    height: '15px',
    width: '15px',
    position: 'absolute',
    background: theme.palette.primary.main,
    left: `calc(${userScoreNorm}% - 7.5px)`,
    border: '1px solid #FFF',
  },
  graphText: {
    fontSize: '11px',
    textTransform: 'capitalize',
  },
  leftText: {
    position: 'absolute',
    textAlign: 'left',
    left: 0,
    top: '12px',
  },
  rightText: {
    position: 'absolute',
    textAlign: 'right',
    right: 0,
    top: '12px',
  },
  motiveItemText: {
    fontSize: '11px',
  },
}));

export default MatchCompareGraph;
