import CircleIcon from '@mui/icons-material/Circle';
import { ButtonBase, ListItemIcon, ListItemText, Stack, Tooltip, Typography } from '@mui/material';
import _ from 'lodash';
import React from 'react';
import { useTranslation } from 'react-i18next';
import { makeStyles } from 'tss-react/mui';
import { ZIndices } from '../../../enums/enums';
import { Colors } from '../../../theme/theme';
import { Template } from '../../../types/templates';

interface Props {
  tooltipContainerElement?: HTMLElement | null;

  template: Template;
  copied?: string;

  replacePlaceholders(text: string): string;

  copyTextToClipboard(template: Template): () => void;

  handleOpenEditTemplates(template: Template): (event: React.MouseEvent) => void;
}

const EmailTemplateListItem: React.FC<Props> = ({
  tooltipContainerElement,
  template,
  copied,
  replacePlaceholders,
  copyTextToClipboard,
  handleOpenEditTemplates,
}) => {
  const { classes, cx } = useStyles();
  const { t } = useTranslation();

  const text = !_.isNil(template.body) ? replacePlaceholders(template.body) : '';

  return (
    <Stack className={classes.listItem} spacing={0.5}>
      <Stack direction={'row'} alignItems={'center'}>
        <ListItemIcon className={classes.listItemIcon}>
          <CircleIcon className={classes.listItemIconDot} />
        </ListItemIcon>
        <ListItemText className={classes.listItemText} primary={_.truncate(template.name, { length: 40 })} />
      </Stack>
      <Stack className={classes.templateActions} spacing={1} direction={'row'} justifyContent={'space-between'}>
        <ButtonBase onClick={!_.isNil(template.body) ? copyTextToClipboard(template) : undefined}>
          <Typography className={cx(classes.actionText, copied === template.key ? 'copied' : null)}>{t('copy')}</Typography>
        </ButtonBase>
        {!_.isNil(template.body) && (
          <Tooltip
            title={text}
            classes={{ tooltip: classes.tooltip }}
            PopperProps={{
              className: classes.tooltip,
              container: tooltipContainerElement,
              style: { zIndex: ZIndices.TOOLTIP },
            }}
            placement={'top'}
            arrow={true}
          >
            <Typography className={classes.actionText}>{t('preview')}</Typography>
          </Tooltip>
        )}
        <ButtonBase onClick={handleOpenEditTemplates(template)}>
          <Typography className={classes.actionText}>{t('edit')}</Typography>
        </ButtonBase>
      </Stack>
    </Stack>
  );
};

const useStyles = makeStyles()((theme) => ({
  listItem: {
    position: 'relative',
    padding: '4px 0 8px',
    marginBottom: '6px',
    borderBottom: `1px solid ${Colors.GREY_SHADE_4}`,
  },
  listItemText: {
    margin: 0,
    '& .MuiListItemText-primary': {
      fontSize: '12px',
      textAlign: 'left',
    },
  },
  tooltip: {
    fontSize: '14px',
    lineHeight: 1.2,
    whiteSpace: 'pre-wrap',
  },
  listItemIcon: {
    color: theme.palette.primary.main,
    minWidth: 0,
    marginRight: '16px',
  },
  listItemIconDot: {
    width: '10px',
    height: '10px',
  },
  templateActions: {
    paddingLeft: '26px',
  },
  actionText: {
    fontSize: '11px',
    color: Colors.GREY_SHADE_4,
    '&:hover': {
      color: theme.palette.primary.main,
    },
    '&.copied': {
      color: theme.palette.primary.main,
    },
  },
}));

export default EmailTemplateListItem;
