import ExpandMoreIcon from '@mui/icons-material/ExpandMore';
import { TextField, Typography } from '@mui/material';
import _ from 'lodash';
import React, { PropsWithChildren } from 'react';
import { makeStyles } from 'tss-react/mui';
import { ZIndices } from '../../enums/enums';
import useContainerStore from '../../stores/containerStore';

interface Props {
  value: string | string[];
  label?: string;
  multiple?: boolean;

  onChange(event: React.ChangeEvent<HTMLInputElement>): void;
}

const PaiSelect: React.FC<PropsWithChildren<Props>> = ({ value, label, multiple, onChange, children }) => {
  const { classes } = useStyles();
  const tooltipContainer = useContainerStore((state) => state.tooltipContainer);

  return (
    <div>
      {!_.isNil(label) ? <Typography className={classes.label}>{label}</Typography> : null}
      <TextField
        className={classes.textfield}
        InputProps={{ disableUnderline: true, classes: { input: classes.fieldInput } }}
        SelectProps={{
          displayEmpty: true,
          IconComponent: ExpandMoreIcon,
          MenuProps: { classes: { list: classes.menuList, paper: classes.menuPaper, root: classes.menu }, container: tooltipContainer },
          multiple: multiple,
        }}
        select={true}
        variant={'standard'}
        fullWidth={true}
        value={value}
        onChange={onChange}
      >
        {children}
      </TextField>
    </div>
  );
};

const useStyles = makeStyles()((theme) => ({
  textfield: {
    border: `1px solid ${theme.palette.primary.main}`,
    padding: '2px',
    '& .MuiSvgIcon-root': {
      color: theme.palette.primary.main,
      height: '100%',
      top: 0,
      background: '#FFF',
    },
  },
  fieldInput: {
    background: theme.palette.tertiary.main,
    fontSize: '13px',
    padding: '8px 12px',
    display: 'flex',
    alignItems: 'center',
  },
  menu: {
    zIndex: ZIndices.TOOLTIP,
  },
  menuPaper: {
    borderRadius: 0,
    maxHeight: '33vh',
  },
  menuList: {
    padding: 0,
  },
  label: {
    marginBottom: '8px',
    marginLeft: '4px',
    fontSize: '11px',
  },
}));

export default PaiSelect;
