import SquareIcon from '@mui/icons-material/Square';
import { Grid, Typography, useTheme } from '@mui/material';
import _ from 'lodash';
import React from 'react';
import { useTranslation } from 'react-i18next';
import { makeStyles } from 'tss-react/mui';

const LegendItem: React.FC<{ text: string; color: string }> = ({ text, color }) => {
  const { classes } = useStyles();
  return (
    <div className={classes.legendItem}>
      <SquareIcon className={classes.legendIcon} style={{ color: color }} />
      <Typography className={classes.legendText}>{text}</Typography>
    </div>
  );
};

interface Props {
  hideOwn?: boolean;
}

const Legend: React.FC<Props> = ({ hideOwn }) => {
  const { classes } = useStyles();
  const { t } = useTranslation();
  const theme = useTheme();

  return (
    <div className={classes.legend}>
      <Typography className={classes.title}>{t('meanings')}</Typography>
      <Grid container={true} direction={'column'} spacing={1}>
        <Grid item={true}>
          <LegendItem text={t('targetValue')} color={theme.palette.secondary.main} />
        </Grid>
        {_.isNil(hideOwn) || !hideOwn ? (
          <Grid item={true}>
            <LegendItem text={t('currentValue')} color={theme.palette.primary.main} />
          </Grid>
        ) : null}
      </Grid>
    </div>
  );
};

const useStyles = makeStyles()((_theme) => ({
  legend: {
    width: '100%',
    background: '#FFF',
    padding: '8px 16px',
  },
  title: {
    fontSize: '12px',
    fontWeight: 900,
    textTransform: 'uppercase',
    textAlign: 'center',
    whiteSpace: 'pre-wrap',
    marginBottom: '8px',
  },
  legendItem: {
    display: 'flex',
    alignItems: 'center',
    justifyContent: 'flex-start',
    width: '100%',
  },
  legendIcon: {
    marginRight: '16px',
    fontSize: '20px',
  },
  legendText: {
    fontSize: '11px',
  },
}));

export default Legend;
