import { Paper, Stack, Typography } from '@mui/material';
import React, { useEffect } from 'react';
import { useTranslation } from 'react-i18next';
import { makeStyles } from 'tss-react/mui';
import shallow from 'zustand/shallow';
import PaiButton from '../components/basic/PaiButton';
import usePanelStore from '../stores/panelStore';
import { getHostDomain } from '../utils/helper';
import { getLogos } from '../utils/imageUtils';

const Login: React.FC = () => {
  const { classes } = useStyles();
  const { t } = useTranslation();
  const { collapsed, collapsePanel } = usePanelStore(
    (state) => ({
      collapsed: state.collapsed,
      collapsePanel: state.collapsePanel,
    }),
    shallow
  );

  const logo = getLogos().large_logo;

  const openDashboard = async () => {
    const hostDomain = await getHostDomain();
    const dashboardURL = `${hostDomain}/dashboard/landing/signin`;

    window.open(dashboardURL, '_blank');
  };

  useEffect(() => {
    if (collapsed) {
      collapsePanel();
    }
  }, [collapsed]);

  return (
    <div className={classes.login}>
      <Paper className={classes.card} elevation={0}>
        <Stack spacing={4} alignItems={'center'}>
          <img className={classes.logo} src={logo} alt="logo" />
          <Typography className={classes.paragraph} align={'center'}>
            {t('loginInfo')}
          </Typography>
          <div className={classes.buttonContainer}>
            <PaiButton text={t('loginLink')} size="large" action={openDashboard} />
          </div>
        </Stack>
      </Paper>
    </div>
  );
};

const useStyles = makeStyles()((theme) => ({
  login: {
    background: theme.palette.tertiary.main,
    height: '100%',
    padding: '8px',
  },
  card: {
    background: '#FFF',
    borderRadius: 0,
    width: '100%',
    height: '100%',
    padding: '16px',
  },
  paragraph: {
    fontSize: '20px',
    whiteSpace: 'pre-wrap',
    color: theme.palette.primary.main,
  },
  buttonContainer: {
    display: 'flex',
    justifyContent: 'center',
    alignItems: 'center',
  },
  logo: {
    height: '40px',
  },
}));

export default Login;
