import { Typography } from '@mui/material';
import Tooltip from '@mui/material/Tooltip';
import _ from 'lodash';
import React from 'react';
import { useTranslation } from 'react-i18next';
import { makeStyles } from 'tss-react/mui';
import shallow from 'zustand/shallow';
import { ZIndices } from '../../enums/enums';
import useContainerStore from '../../stores/containerStore';
import useDiagnosticTooltipStore from '../../stores/diagnosticTooltipStore';
import { Shadows } from '../../theme/theme';

const DiagnosticTooltip: React.FC = () => {
  const { classes } = useStyles();
  const { t } = useTranslation();

  const tooltipContainerElement = useContainerStore((state) => state.tooltipContainer);
  const { open, anchorElement, text } = useDiagnosticTooltipStore(
    (state) => ({
      open: state.open,
      anchorElement: state.anchorElement,
      text: state.text,
      handleClose: state.handleClose,
    }),
    shallow
  );

  if (_.isNil(anchorElement)) {
    return null;
  }

  return (
    <Tooltip
      classes={{ tooltip: classes.tooltip, popper: classes.popper }}
      open={open}
      PopperProps={{
        anchorEl: anchorElement,
        container: tooltipContainerElement,
      }}
      title={
        <div className={classes.diagnosticTooltip}>
          <Typography className={classes.title}>{t('diagnostic')}</Typography>
          <Typography className={classes.text}>{text}</Typography>
        </div>
      }
    >
      <span />
    </Tooltip>
  );
};

const useStyles = makeStyles()((_theme) => ({
  tooltip: {
    borderRadius: 0,
    color: 'black',
    background: 'white',
    boxShadow: Shadows.NORMAL_SHADOW,
    width: '200px',
    padding: 0,
  },
  popper: {
    zIndex: ZIndices.TOOLTIP,
  },
  diagnosticTooltip: {
    width: '100%',
    background: '#FFF',
    position: 'relative',
  },
  title: {
    fontSize: '11px',
    fontWeight: 'bold',
    textTransform: 'uppercase',
    textAlign: 'center',
    paddingTop: '8px',
  },
  text: {
    fontSize: '11px',
    padding: '2px 16px 8px 16px',
  },
}));

export default DiagnosticTooltip;
