import { TextField, Typography } from '@mui/material';
import _ from 'lodash';
import React from 'react';
import { makeStyles } from 'tss-react/mui';

interface Props {
  value: string;
  rows?: number;
  instruction?: string;
  placeholder?: string;
  disabled?: boolean;

  onChange(event: React.ChangeEvent<HTMLInputElement>): void;
}

const PaiTextArea: React.FC<Props> = ({ value, rows, instruction, placeholder, disabled, onChange }) => {
  const { classes, cx } = useStyles();

  return (
    <div className={classes.container}>
      {!_.isNil(instruction) ? <Typography className={classes.instruction}>{instruction}</Typography> : null}
      <TextField
        className={classes.textfield}
        InputProps={{ disableUnderline: true, classes: { input: cx(classes.fieldInput, !_.isNil(instruction) ? 'has-instruction' : null) } }}
        variant={'standard'}
        fullWidth={true}
        placeholder={placeholder}
        multiline={true}
        rows={_.isNil(rows) ? 7 : rows}
        disabled={disabled}
        value={value}
        onChange={onChange}
      />
    </div>
  );
};

const useStyles = makeStyles()((theme) => ({
  container: {
    background: theme.palette.tertiary.main,
    border: `1px solid ${theme.palette.primary.main}`,
    padding: '2px',
  },
  instruction: {
    zIndex: 1,
    fontSize: '11px',
    fontWeight: 'bold',
    padding: '8px 8px 0 8px',
    lineHeight: 1,
  },
  textfield: {
    '& .MuiInput-root': {
      padding: 0,
    },
    '& .MuiSvgIcon-root': {
      color: theme.palette.primary.main,
      height: '100%',
      top: 0,
      background: '#FFF',
    },
  },
  fieldInput: {
    fontSize: '13px',
    padding: '8px 12px',
    '&::placeholder': {
      opacity: 0.67,
      fontSize: '11px',
    },
    '&:focus': {
      '&::placeholder': {
        opacity: 0,
      },
    },
  },
}));

export default PaiTextArea;
