import { List, Stack, Typography } from '@mui/material';
import _ from 'lodash';
import React from 'react';
import { useTranslation } from 'react-i18next';
import { makeStyles } from 'tss-react/mui';
import useProfileStore from '../../../stores/profileStore';
import { Assessment } from '../../../types/assessment';
import PaiListItem from '../../basic/PaiListItem';

interface Props {
  assessment: Assessment | undefined;
}

const PersonalityType: React.FC<Props> = ({ assessment }) => {
  const { classes } = useStyles();
  const { t } = useTranslation();

  const contact = useProfileStore((state) => state.contact);

  return (
    <div className={classes.card}>
      <Typography className={classes.title}>{t('personalityType')}</Typography>
      {!_.isNil(assessment) ? (
        <Stack className={classes.assessment} gap={1}>
          <div>
            <Typography className={classes.subTitle}>
              {t('contactCharacteristics', { contactName: contact?.firstName || t('theContact') })}
            </Typography>
            <List disablePadding={true}>
              {assessment?.instructions.descriptions.shortdescription.split(',').map((item, index) => (
                <PaiListItem key={index} text={item} />
              ))}
            </List>
          </div>
          <div>
            <Typography className={classes.subTitle}>{t('definesContact', { contactName: contact?.firstName || t('theContact') })}</Typography>
            <List disablePadding={true}>
              {assessment?.instructions.descriptions.listdescription.map((item, index) => (
                <PaiListItem key={index} text={item} />
              ))}
            </List>
          </div>
          <div>
            <Typography className={classes.subTitle}>{t('importantToContact', { contactName: contact?.firstName || t('theContact') })}</Typography>
            <List disablePadding={true}>
              {assessment.instructions.descriptions.importantdescription.map((item, index) => (
                <PaiListItem key={index} text={item} />
              ))}
            </List>
          </div>
          <div>
            <Typography className={classes.subTitle}>
              {t('answerContactQuestions', { contactName: contact?.firstName || t('theContact') })}
            </Typography>
            <List disablePadding={true}>
              {assessment.instructions.descriptions.descriptionquestions.map((item, index) => (
                <PaiListItem key={index} text={item} />
              ))}
            </List>
          </div>
        </Stack>
      ) : null}
    </div>
  );
};

const useStyles = makeStyles()((theme) => ({
  card: {
    width: '100%',
    padding: '16px 8px 8px',
    height: 'calc(100% - 39px - 16px - 20px)',
    background: '#FFF',
  },
  assessment: {
    padding: '0 8px',
  },
  title: {
    fontSize: '12px',
    fontWeight: 900,
    textTransform: 'uppercase',
    textAlign: 'center',
    whiteSpace: 'pre-wrap',
    marginBottom: '12px',
  },
  subTitle: {
    width: '100%',
    fontSize: '12px',
    fontWeight: 900,
    color: theme.palette.primary.main,
    marginBottom: '8px',
  },
}));

export default PersonalityType;
