import {
  isLinkedInRecThreadsPage,
  isLinkedInRecUserPage,
  isLinkedInSalesNavThreadsPage,
  isLinkedInSalesNavUserPage,
  isLinkedInSalesNavSearchLeadsPage,
  isLinkedInThreadsPage,
  isLinkedInUserPage,
} from './linkedinUtils';

export const getAnalysisButton = (isAnalyzed: boolean) => {
  if (isLinkedInThreadsPage() || isLinkedInSalesNavThreadsPage() || isLinkedInRecThreadsPage()) {
    if (isAnalyzed) {
      return chrome?.runtime?.getURL('images/analysisBtn/com_analyzed.svg');
    } else {
      return chrome?.runtime?.getURL('images/analysisBtn/com_open.svg');
    }
  } else if (isLinkedInUserPage() || isLinkedInSalesNavUserPage() || isLinkedInSalesNavSearchLeadsPage() || isLinkedInRecUserPage()) {
    if (isAnalyzed) {
      return chrome?.runtime?.getURL('images/analysisBtn/contact_analyzed.svg');
    } else {
      return chrome?.runtime?.getURL('images/analysisBtn/contact_open.svg');
    }
  } else {
    if (isAnalyzed) {
      return chrome?.runtime?.getURL('images/analysisBtn/text_analyzed.svg');
    } else {
      return chrome?.runtime?.getURL('images/analysisBtn/text_open.svg');
    }
  }
};

export const getCardImages = () => {
  return {
    info: chrome?.runtime?.getURL('images/card/info.svg'),
  };
};

export const getIllustrationUrl = (persona: string) => {
  return chrome?.runtime?.getURL(`images/illustration/${persona}.png`);
};

export const getLogos = () => {
  return {
    size_128: chrome?.runtime?.getURL('images/128x128.png'),
    size_64: chrome?.runtime?.getURL('images/64x64.png'),
    size_48: chrome?.runtime?.getURL('images/48x48.png'),
    size_32: chrome?.runtime?.getURL('images/32x32.png'),
    size_16: chrome?.runtime?.getURL('images/16x16.png'),
    large_logo: chrome?.runtime?.getURL('images/logos/psychological_ai_logo.svg'),
    large_logo_white: chrome?.runtime?.getURL('images/logos/psychological_ai_logo_white.svg'),
    short_logo: chrome?.runtime?.getURL('images/logos/logo_short.svg'),
    short_logo_white: chrome?.runtime?.getURL('images/logos/logo_short_white.svg'),
    product_logo_white: chrome?.runtime?.getURL('images/logos/product_logo_white.svg'),
  };
};
