import ScopedCssBaseline from '@mui/material/ScopedCssBaseline';
import i18n from 'i18next';
import _ from 'lodash';
import React, { useEffect, useState } from 'react';
import { Root, createRoot } from 'react-dom/client';
import { useLocation, useNavigate } from 'react-router-dom';
import shallow from 'zustand/shallow';
import DiagnosticTooltip from './components/highlighter/DiagnosticTooltip';
import InteractiveTooltip from './components/highlighter/InteractiveTooltip';
import { ApiActions, GeneralActions, LinkedinActions, LinkedinEventActions, UserActions } from './enums/actions';
import { Ids, Modes, Routes, SendButtonText } from './enums/enums';
import ButtonWrapper from './features/ButtonWrapper';
import Highlighter from './features/Highlighter';
import SidePanel from './features/SidePanel';
import { useAugmentedWriting } from './hooks/useAugmentedWriting';
import { useAuthorization } from './hooks/useAuthorization';
import useAugmentedWritingStore from './stores/augmentedWritingStore';
import useContainerStore from './stores/containerStore';
import useElementStore from './stores/elementStore';
import useLanguageStore from './stores/languageStore';
import usePanelStore from './stores/panelStore';
import useProfileStore from './stores/profileStore';
import useSnackbarStore from './stores/snackbarStore';
import useTextGenerationStore from './stores/textGenerationStore';
import useUserStore from './stores/userStore';
import { User } from './types/account';
import { Scores } from './types/augmentedWriting';
import { Contact } from './types/contact';
import { LicenseInfo } from './types/license';
import { sendMessageToBackground } from './utils/helper';
import {
  extractLinkedInSalesNavUserName,
  extractLinkedInUserName,
  extractLinkedRecruiterUserName,
  getLinkedInHandle,
  getLinkedInRecHandle,
  isLinkedIn,
  isLinkedInRecComposePage,
  isLinkedInRecThreadsPage,
  isLinkedInRecUserURL,
  isLinkedInSalesNavThreadsPage,
  isLinkedInSalesNavUserPage,
  isLinkedInSalesNavUserURL,
  isLinkedInThreadsPage,
  isLinkedInUserPage,
} from './utils/linkedinUtils';

const App: React.FC = () => {
  const navigate = useNavigate();
  const location = useLocation();

  const { clearStorage, authenticated, setIsAuthenticated, validate } = useAuthorization();
  const { user, setUser, setLicense, setQuotaLimitReached, resetUser } = useUserStore(
    (state) => ({
      user: state.user,
      setUser: state.setUser,
      setLicense: state.setLicense,
      setQuotaLimitReached: state.setQuotaLimitReached,
      resetUser: state.resetUser,
    }),
    shallow
  );
  const { userLanguage, setUserLanguage } = useLanguageStore(
    (state) => ({ userLanguage: state.userLanguage, setUserLanguage: state.setUserLanguage }),
    shallow
  );
  const lang = !_.isNil(userLanguage) ? userLanguage : i18n.languages[0];
  const { resetContact, profileLoading, setProfileLoading, setContactAnalysis, setContactData } = useProfileStore(
    (state) => ({
      resetContact: state.resetContact,
      userAnalysis: state.userAnalysis,
      profileLoading: state.profileLoading,
      setProfileLoading: state.setProfileLoading,
      setContactAnalysis: state.setContactAnalysis,
      setContactData: state.setContactData,
    }),
    shallow
  );
  const contact = useProfileStore((state) => state.contact);
  const { setIsAnalyzed, setAnalysisLoading } = useAugmentedWritingStore(
    (state) => ({ setIsAnalyzed: state.setIsAnalyzed, setAnalysisLoading: state.setAnalysisLoading }),
    shallow
  );
  const { togglePanel, setMode } = usePanelStore((state) => ({ togglePanel: state.togglePanel, setMode: state.setMode }), shallow);
  const openSnackbar = useSnackbarStore((state) => state.openSnackbar);

  const { activeElement, setActiveElement } = useElementStore(
    (state) => ({ activeElement: state.activeElement, setActiveElement: state.setActiveElement }),
    shallow
  );
  const resetAllTextGeneration = useTextGenerationStore((state) => state.resetAllTextGeneration);
  const [currentUrl, setCurrentUrl] = useState('');
  const [scrollY, setScrollY] = useState(0);
  const [isScrolling, setIsScrolling] = useState(false);
  const setTooltipContainer = useContainerStore((state) => state.setTooltipContainer);

  const {
    allSuggestions,
    scores,
    sidebarNotes,
    currentSession,
    resetAnalysisResults,
    resetSuggestions,
    skipSuggestion,
    ignoreSuggestion,
    insertAtPosition,
    onCategoryClick,
  } = useAugmentedWriting(activeElement, contact);

  let scrollingTimer: ReturnType<typeof setTimeout>;

  const config: MutationObserverInit = {
    childList: true,
    characterData: true,
    subtree: true,
  };

  useEffect(() => {
    const onResize = () => {
      const width = window.innerWidth;
      const height = window.innerHeight;
      sendMessageToBackground({ action: GeneralActions.RESIZE_WINDOW, body: { width, height } });
    };
    window.addEventListener('resize', onResize);

    const onScroll = () => {
      setIsScrolling(true);
      clearTimeout(scrollingTimer);
      scrollingTimer = setTimeout(() => {
        const scrollOffsetYAxis = window.scrollY;
        setScrollY(scrollOffsetYAxis);
        setIsScrolling(false);
        sendMessageToBackground({ action: GeneralActions.SCROLL, body: window.scrollY });
      }, 50);
    };
    window.addEventListener('scroll', onScroll);

    const onMouseUp = () => {
      const element = document.activeElement;
      validateTextField(element);
    };
    window.addEventListener('mouseup', onMouseUp);

    chrome.storage.local.get(['language'], ({ language }) => {
      if (!_.isNil(language)) {
        setUserLanguage(language);
        i18n.changeLanguage(language);
      }
    });

    return () => {
      window.removeEventListener('resize', onResize);
      window.removeEventListener('scroll', onScroll);
      window.removeEventListener('mouseup', onMouseUp);
    };
  }, []);

  useEffect(() => {
    if (currentUrl && currentUrl !== '') {
      resetAnalysisResults();
      setActiveElement(null);
      if (authenticated) {
        togglePanel(false);
        setProfileLoading(false);
        resetContact();
        resetAllTextGeneration();
      }
    } else {
      chrome?.storage?.local?.get('disableSidebarAutoOpen', async ({ disableSidebarAutoOpen }) => {
        if ((_.isNil(disableSidebarAutoOpen) || disableSidebarAutoOpen !== 'true') && !_.isNil(authenticated) && !authenticated) {
          togglePanel(true);
        }
      });
    }
  }, [currentUrl, authenticated]);

  useEffect(() => {
    if (!_.isNil(authenticated) && authenticated) {
      setActiveElement(null);
      if (location.pathname === Routes.LOGIN) {
        navigate(Routes.LINKEDIN);
      }
      sendMessageToBackground({ action: UserActions.GET_USER_INFO_REQUEST });
      sendMessageToBackground({ action: UserActions.GET_LINKEDIN_LICENSE_INFO_REQUEST });
    } else {
      navigate(Routes.LOGIN);
    }
  }, [authenticated]);

  useEffect(() => {
    const messageListener = (request, sender, callback) => {
      if (request.action.includes(ApiActions.ERROR)) {
        setAnalysisLoading(false);
        setProfileLoading(false);

        if (request.action.includes(LinkedinActions.ANALYZE_LINKEDIN_MESSAGE)) {
          resetContact();
        }
        if (
          request.body?.message !== 'no participants to analyze' &&
          request.body?.message !== 'Validation Error' &&
          request.body?.message !== 'not enough quota to add new contacts' &&
          request.body?.message !== 'Email templates not found'
        ) {
          openSnackbar(true, request.body.message, 'error');
        }
        if (request.body?.message === 'not enough quota to add new contacts') {
          setQuotaLimitReached(true);
        }
        if (
          request.body.message?.includes(LinkedinActions.ANALYZE_LINKEDIN_USER) ||
          request.body.message?.includes(LinkedinActions.ANALYZE_LINKEDIN_SALESNAV_USER) ||
          request.body.message?.includes(LinkedinActions.ANALYZE_LINKEDIN_REC_USER)
        ) {
          resetContact();
        }
      }

      if (request.action === UserActions.LOGOUT_RESPONSE) {
        navigate(Routes.LOGIN);
        clearStorage();
        setIsAuthenticated(false);
        resetContact();
        resetAllTextGeneration();
        resetUser();
        resetAnalysisResults();
      }

      if (request.action === ApiActions.REVALIDATE_TOKEN) {
        validate();
      }

      if (request.action === GeneralActions.URL_CHANGED) {
        if (request.body.currentUrl) {
          setCurrentUrl(request.body.currentUrl);
        }
      }

      if (request.action === GeneralActions.MINIMIZE_EXTENSION) {
        togglePanel(false);
      }

      if (request.action === UserActions.GET_LINKEDIN_LICENSE_INFO_RESPONSE) {
        const res = request.body.license;
        const tempLicenseInfo: LicenseInfo = { package: res.productName, total: res.contactsCount.total, remaining: res.contactsCount.remaining };
        setLicense(tempLicenseInfo);
      }

      if (request.action === UserActions.GET_USER_INFO_RESPONSE) {
        const resStatus = request.body.status;
        const resTenant = request.body.tenant;
        const resFirstname = request.body.firstname;
        const resLastname = request.body.lastname;
        const resEmail = request.body.email;

        let userBody: User = {};

        if (!_.isNil(resTenant)) {
          userBody.companyId = resTenant;
        }

        if (!_.isNil(resFirstname)) {
          userBody.firstName = resFirstname;
        }

        if (!_.isNil(resLastname)) {
          userBody.lastName = resLastname;
        }

        if (!_.isNil(resStatus)) {
          userBody.status = resStatus;
        }

        if (!_.isNil(resEmail)) {
          userBody.email = resEmail;
        }

        setUser(userBody);
      }

      if (request.action === LinkedinActions.GET_LINKEDIN_CONTACT_BY_ID_RESPONSE) {
        const tempContact = new Contact(request.body);
        setContactAnalysis(tempContact.assessment, tempContact.profile, tempContact.percentiles);
        setContactData(
          tempContact.id,
          tempContact.globalContact,
          tempContact.externalId,
          tempContact.firstname,
          tempContact.lastname,
          tempContact.occupation,
          tempContact.qualityFactor,
          tempContact.trend,
          tempContact.basis,
          tempContact.matchedJobTitle
        );
        setQuotaLimitReached(false);
        sendMessageToBackground({ action: UserActions.GET_LINKEDIN_LICENSE_INFO_REQUEST });

        setProfileLoading(false);
      }
    };

    chrome?.runtime?.onMessage.addListener(messageListener);
    return () => {
      chrome?.runtime?.onMessage.removeListener(messageListener);
    };
  }, [user]);

  const onAnalyzeMessageThread = async () => {
    const currPath = window.location.pathname.split('/');
    const threadId = currPath[currPath.length - 2];

    sendMessageToBackground({ action: LinkedinActions.ANALYZE_LINKEDIN_MESSAGE, body: { threadId, lang } });
    setProfileLoading(true);
  };

  const onAnalyzeMessageSalesNavThread = async () => {
    const currPath = window.location.pathname.split('/');
    const threadId = currPath.pop();
    sendMessageToBackground({ action: LinkedinActions.ANALYZE_LINKEDIN_SALESNAV_MESSAGE, body: { threadId, lang } });
    setProfileLoading(true);
  };

  const onAnalyzeMessageRecThread = async () => {
    const currPath = getLinkedInRecHandle(document);
    if (currPath) {
      const profileId = extractLinkedRecruiterUserName(currPath);
      sendMessageToBackground({ action: LinkedinActions.ANALYZE_LINKEDIN_REC_MESSAGE, body: { profileId, lang } });
      setProfileLoading(true);
    }
  };

  useEffect(() => {
    if (isLinkedIn()) {
      if (activeElement) {
        if (!isLinkedInRecComposePage()) {
          if (!profileLoading && (isLinkedInThreadsPage() || isLinkedInSalesNavThreadsPage() || isLinkedInRecThreadsPage())) {
            if (isLinkedInThreadsPage()) {
              onAnalyzeMessageThread();
            } else if (isLinkedInSalesNavThreadsPage()) {
              onAnalyzeMessageSalesNavThread();
            } else if (isLinkedInRecThreadsPage()) {
              onAnalyzeMessageRecThread();
            }
          } else {
            const userHref = getLinkedInHandle(activeElement);
            if (userHref) {
              if (isLinkedInSalesNavUserURL(userHref)) {
                const profileId = extractLinkedInSalesNavUserName(userHref);
                sendMessageToBackground({ action: LinkedinActions.GET_LINKEDIN_SALESNAV_USER, body: { profileId, lang }, source: 'analyzeButton' });
              } else if (isLinkedInRecUserURL(userHref)) {
                const profileId = extractLinkedRecruiterUserName(userHref);
                sendMessageToBackground({ action: LinkedinActions.GET_LINKEDIN_REC_USER, body: { profileId, lang }, source: 'analyzeButton' });
              } else {
                const profileId = extractLinkedInUserName(userHref);
                sendMessageToBackground({ action: LinkedinActions.GET_LINKEDIN_USER, body: { profileId, lang }, source: 'analyzeButton' });
              }
              setProfileLoading(true);
            }
          }
        } else {
          const profileId = extractLinkedRecruiterUserName(window.location.pathname);
          if (profileId) {
            sendMessageToBackground({ action: LinkedinActions.GET_LINKEDIN_REC_USER, body: { profileId, lang }, source: 'analyzeButton' });
            setProfileLoading(true);
          }
        }
      }
    }

    const textFieldObserver = new MutationObserver(function (mutations_list) {
      mutations_list.forEach(function (mutation) {
        setIsAnalyzed(false);
      });
    });

    if (activeElement) {
      textFieldObserver?.observe(document.body, config);
    }

    const elementObserver = new MutationObserver(function (mutations_list) {
      mutations_list.forEach(function (mutation) {
        mutation.removedNodes.forEach(function (removed_node) {
          const isElement = activeElement === removed_node;
          const isChildOfElement = removed_node.contains(activeElement);
          if (isChildOfElement || isElement) {
            setActiveElement(null);
            togglePanel(false);
            if (isLinkedIn()) {
              if (isLinkedInThreadsPage() || isLinkedInUserPage()) {
                setMode(Modes.CONTACT_ANALYSIS);
              }
            }
            elementObserver?.disconnect();
          }
        });
      });
    });
    elementObserver?.observe(document.body, config);

    const container = document.getElementById(Ids.PANEL_SHADOW_ROOT);
    const shadow = container?.shadowRoot;

    const innerContainer = shadow?.getElementById(Ids.PANEL_SHADOW_ROOT_CONTAINER);

    const tooltipContainer = document.createElement('div');
    tooltipContainer.id = Ids.TOOLTIP_CONTAINER;
    innerContainer?.appendChild(tooltipContainer);
    setTooltipContainer(tooltipContainer);

    const highlighter = <Highlighter />;

    const rootElementId = 'injected-highlights';

    const highlightContainer = document.createElement('hundert-worte-highlights');
    highlightContainer.id = rootElementId;
    highlightContainer.style.position = activeElement?.tagName === 'TEXTAREA' ? 'relative' : 'absolute';
    highlightContainer.style.top = '0px';
    highlightContainer.style.left = '0px';

    const elementInDOM = activeElement?.parentElement;
    let root: Root | null = null;

    if (elementInDOM) {
      elementInDOM.prepend(highlightContainer);
      const selectedElement = document.querySelector(`#${rootElementId}`);
      if (!_.isNil(selectedElement)) {
        root = createRoot(selectedElement);
        root.render(highlighter);
      }
    }

    return () => {
      textFieldObserver?.disconnect();
      elementObserver.disconnect();
      root?.unmount();
      highlightContainer?.remove();
      tooltipContainer.remove();

      resetContact();
      resetSuggestions();
      resetAnalysisResults();
      setAnalysisLoading(false);
      sendMessageToBackground({ action: ApiActions.ABORT_REQUEST });
    };
  }, [activeElement]);

  const validateTextField = (element: Element | null) => {
    switch (element?.tagName) {
      case 'DIV':
        const divElement = element as HTMLDivElement;
        if (!divElement?.isContentEditable || (isLinkedIn() && element.className === 'ql-editor ql-blank')) return;
        setActiveElement(divElement);
        break;
      case 'TEXTAREA':
        const textAreaElement = element as HTMLTextAreaElement;
        if (isLinkedIn() && (element.id === 'custom-message' || element.id === 'connect-cta-form__invitation')) return;
        setActiveElement(textAreaElement);
        setMode(Modes.WRITER);
        break;
      default:
        break;
    }
  };

  const validateSendButton = (element: Element | null, contact: Contact | undefined, scores: Scores) => {
    if (
      isLinkedIn() &&
      (element?.className?.includes('msg-form__send-button') ||
        element?.className?.includes('artdeco-button artdeco-button--2 artdeco-button--primary'))
    ) {
      if (currentSession && scores.overall) {
        sendMessageToBackground({
          action: LinkedinEventActions.CREATE_LI_EVENT_REQUEST,
          body: { eventType: 'AWSendEvent', scores, contact: contact?.id, usedAt: new Date(), assessmentName: contact?.assessment?.name },
        });
      }
    }
    if (
      (isLinkedInUserPage() || isLinkedInSalesNavUserPage()) &&
      (element?.className?.includes('connect-cta-form__send') || _.some(Object.values(SendButtonText), (sbt) => sbt === element?.ariaLabel))
    ) {
      if (contact) {
        sendMessageToBackground({
          action: LinkedinEventActions.CREATE_LI_EVENT_REQUEST,
          body: { eventType: 'ContactRequest', contact: contact?.id, usedAt: new Date(), assessmentName: contact?.assessment?.name },
        });
      }
    }
  };

  useEffect(() => {
    const onMouseUp = () => {
      const element = document.activeElement;
      validateSendButton(element, contact as Contact, scores);
    };
    window.addEventListener('mouseup', onMouseUp);
    return () => {
      window.removeEventListener('mouseup', onMouseUp);
    };
  }, [scores, contact]);

  return (
    <ScopedCssBaseline>
      <SidePanel
        authenticated={authenticated}
        scores={scores}
        sidebarNotes={sidebarNotes}
        currentSession={currentSession}
        allSuggestions={allSuggestions}
        insertAtPosition={insertAtPosition}
        skipSuggestion={skipSuggestion}
        ignoreSuggestion={ignoreSuggestion}
        onCategoryClick={onCategoryClick}
      />
      <ButtonWrapper activeElement={activeElement} scrollY={scrollY} isScrolling={isScrolling} resetAnalysisResults={resetAnalysisResults} />
      <InteractiveTooltip insertAtPosition={insertAtPosition} ignoreSuggestion={ignoreSuggestion} />
      <DiagnosticTooltip />
    </ScopedCssBaseline>
  );
};

export default App;
