import { ButtonBase, Stack, Typography } from '@mui/material';
import _ from 'lodash';
import React from 'react';
import { makeStyles } from 'tss-react/mui';

interface Props {
  text: string;
  number?: number;
  active?: boolean;
  underline?: boolean;
  disabled?: boolean;

  action?(): void;
}

const SidebarItem: React.FC<Props> = ({ text, number, active, underline, disabled, action }) => {
  const { classes, cx } = useStyles();

  return (
    <ButtonBase
      className={classes.sidebarItem}
      onClick={!_.isNil(action) ? action : undefined}
      style={{ opacity: disabled ? 0.25 : 1, pointerEvents: disabled ? 'none' : 'all' }}
    >
      <Stack gap={0.5}>
        {!_.isNil(number) ? <Typography className={cx(classes.number, active ? 'active' : null)}>{number}</Typography> : null}
        <Typography className={cx(classes.text, active ? 'active' : null, underline ? 'underline' : null)}>{text}</Typography>
      </Stack>
    </ButtonBase>
  );
};

const useStyles = makeStyles()((theme) => ({
  sidebarItem: {
    display: 'flex',
    alignItems: 'center',
    justifyContent: 'space-between',
    '&:hover': {
      color: theme.palette.primary.main,
    },
  },
  number: {
    fontSize: '16px',
    lineHeight: 1,
    fontWeight: 'bold',
    '&.active': {
      color: theme.palette.primary.main,
    },
  },
  text: {
    fontSize: '11px',
    whiteSpace: 'pre-wrap',
    lineHeight: 1.2,
    '&.active': {
      color: theme.palette.primary.main,
    },
    '&.underline': {
      textDecoration: 'underline',
      textUnderlineOffset: '2px',
      textDecorationThickness: '1px',
    },
  },
  icon: {
    '&.active': {
      '& svg': {
        color: theme.palette.primary.main,
      },
    },
    '& svg': {
      fontSize: '20px',
    },
  },
}));

export default SidebarItem;
