import { Stack, Typography } from '@mui/material';
import React from 'react';
import { makeStyles } from 'tss-react/mui';
import { Assessment } from '../../types/assessment';
import PaiListItem from '../basic/PaiListItem';

interface Props {
  assessment: Assessment | undefined;
  isDo: boolean;
}

const DoComponent: React.FC<Props> = ({ assessment, isDo = true }) => {
  const { classes } = useStyles();

  return (
    <div className={classes.card}>
      <Stack gap={1}>
        {isDo
          ? assessment &&
            assessment.instructions.descriptions.dos.map((item, index) => (
              <div key={index}>
                <Typography className={classes.listSubTitle}>{item[0]}</Typography>
                <PaiListItem text={item[1]} />
              </div>
            ))
          : assessment &&
            assessment.instructions.descriptions.donts.map((item, index) => (
              <div key={index}>
                <Typography className={classes.listSubTitle}>{item[0]}</Typography>
                <PaiListItem text={item[1]} />
              </div>
            ))}
      </Stack>
    </div>
  );
};

const useStyles = makeStyles()((theme) => ({
  card: {
    width: '100%',
    background: '#FFF',
    padding: '16px 16px 8px 16px',
  },
  listSubTitle: {
    color: theme.palette.primary.main,
    fontSize: '12px',
    fontWeight: 900,
    marginBottom: '8px',
  },
}));

export default DoComponent;
