import { List, Typography } from '@mui/material';
import React from 'react';
import { makeStyles } from 'tss-react/mui';
import Optimization from './Optimization';
import _ from 'lodash';
import { Paraphrase } from '../../../types/augmentedWriting';
import { TooltipContentType } from '../../../enums/enums';

interface Props {
  paraphrase: Paraphrase;

  insertAtPosition: (word: string, highlightId: string, type: TooltipContentType) => void;
}

const ParaphraseContent: React.FC<Props> = ({ paraphrase, insertAtPosition }) => {
  const { classes } = useStyles();

  return (
    <div>
      <Typography className={classes.explanation}>{paraphrase.text}</Typography>
      {!_.isNil(paraphrase.replacedSpan) ? <Typography className={classes.originalText}>{paraphrase.replacedSpan.content}</Typography> : null}
      <List disablePadding={true}>
        {paraphrase.suggestions.map((suggestion, index) => (
          <Optimization
            key={index} suggestion={suggestion}
            contentType={TooltipContentType.PARAPHRASE} ranking_index={paraphrase.ranking_index} insertAtPosition={insertAtPosition} />
        ))}
      </List>
    </div>
  );
};

const useStyles = makeStyles()((_theme) => ({
  explanation: {
    fontSize: '11px',
    marginBottom: '8px',
  },
  originalText: {
    fontSize: '11px',
    marginBottom: '8px',
    textDecoration: 'line-through',
  },
}));

export default ParaphraseContent;
