import React, { useCallback, useEffect, useRef, useState } from 'react';
import { makeStyles } from 'tss-react/mui';
import { ZIndices } from '../../enums/enums';
import { DiagnosticMode, GrammarReplacement, HighlightTexts, HighlightType, ISuggestionItem, Paraphrase } from '../../types/augmentedWriting';
import Highlight from './Highlight';

interface Props {
  highlights: HighlightType[];
  grammarReplacements: GrammarReplacement[];
  paraphrases: Paraphrase[];
  firstSuggestion?: ISuggestionItem;

  highlightTexts?: HighlightTexts;

  activeElement: HTMLDivElement | HTMLTextAreaElement | null;
  resizeElement: { height: number; width: number };
  resizeWindow: { height: number; width: number };
  windowScrollY: number;

  diagnosticMode: DiagnosticMode;
}

export interface Feedback {
  open: boolean;
  comment: string;
  loading: boolean;
}

const HighlightRenderer: React.FC<Props> = ({
  highlights,
  grammarReplacements,
  paraphrases,
  firstSuggestion,
  highlightTexts,
  resizeElement,
  resizeWindow,
  activeElement,
  windowScrollY,
  diagnosticMode,
}) => {
  const { classes } = useStyles();
  const mirrorRef = useRef(null);

  const [rects, setRects] = useState<DOMRect>();
  const [compStyles, setCompStyles] = useState<CSSStyleDeclaration>();
  const [padding, setPadding] = useState<string>('');
  const [margin, setMargin] = useState<string>('');
  const [width, setWidth] = useState<string>('');
  const [height, setHeight] = useState<string>('');
  const [parentElementScrollTop, setParentElementScrollTop] = useState<number | undefined>(0);
  const [parentPadding, setParentPadding] = useState<{ top: string; right: string; bottom: string; left: string }>({
    top: '0px',
    right: '0px',
    bottom: '0px',
    left: '0px',
  });
  const [textValue, setTextValue] = useState('');
  const [elementScrollY, setElementScrollY] = useState(0);

  useEffect(() => {
    const textFieldChangeEvent = (event: any) => {
      const value = event.target.value;
      setTextValue(value);
    };

    const divScrollContainer = activeElement?.parentElement?.parentElement;

    const elementScrollListener = (event: any) => {
      setElementScrollY(event.target.scrollTop);
    };

    if (activeElement) {
      if (activeElement?.tagName === 'TEXTAREA') {
        activeElement.addEventListener('input', textFieldChangeEvent);
        activeElement.addEventListener('scroll', elementScrollListener);
      } else {
        divScrollContainer?.addEventListener('scroll', elementScrollListener);
      }
      const tempText = (activeElement as HTMLTextAreaElement).value;
      if (tempText !== '') {
        setTextValue(tempText);
      }
    }

    return () => {
      if (activeElement?.tagName === 'TEXTAREA') {
        activeElement.removeEventListener('input', textFieldChangeEvent);
        activeElement?.removeEventListener('scroll', elementScrollListener);
      } else {
        divScrollContainer?.removeEventListener('scroll', elementScrollListener);
      }
    };
  }, [activeElement]);

  useEffect(() => {
    if (activeElement) {
      setRects(activeElement.getBoundingClientRect());
      setCompStyles(getComputedStyle(activeElement));

      const tempPadding = `${compStyles?.padding}`;
      setPadding(tempPadding);

      const tempMargin = `${compStyles?.margin}`;
      setMargin(tempMargin);

      const tempWidth = `calc(${rects?.width}px - ${compStyles?.paddingLeft} - ${compStyles?.paddingRight})`;
      setWidth(tempWidth);

      const tempHeight = `calc(${rects?.height}px - ${compStyles?.paddingTop} - ${compStyles?.paddingBottom})`;
      setHeight(tempHeight);

      const parentElementOffset = activeElement?.offsetParent;
      const parentElement = activeElement?.parentElement;

      if (parentElementOffset && !parentElement?.classList.contains('compose-textarea')) {
        parentElementOffset.addEventListener('scroll', (event: any) => {
          setParentElementScrollTop(event.target.scrollTop);
        });
      }

      if (activeElement.tagName === 'TEXTAREA') {
        const parentEl = activeElement.parentElement;
        if (parentEl) {
          if (!parentEl.classList.contains('compose-textarea')) {
            const parentStyles = getComputedStyle(parentEl, null);
            const paddingTop = parentStyles.getPropertyValue('padding-top');
            const paddingLeft = parentStyles.getPropertyValue('padding-left');
            const paddingRight = parentStyles.getPropertyValue('padding-right');
            const paddingBottom = parentStyles.getPropertyValue('padding-bottom');
            setParentPadding({ top: paddingTop, right: paddingRight, bottom: paddingBottom, left: paddingLeft });
            parentEl.addEventListener('scroll', (event: any) => {
              setParentElementScrollTop(event.target.scrollTop);
            });
          }
        }
      }

      if (parentElement && activeElement.tagName === 'DIV') {
        const parentStyles = getComputedStyle(parentElement, null);
        const paddingTop = parentStyles.getPropertyValue('padding-top');
        const paddingLeft = parentStyles.getPropertyValue('padding-left');
        const paddingRight = parentStyles.getPropertyValue('padding-right');
        const paddingBottom = parentStyles.getPropertyValue('padding-bottom');
        setParentPadding({ top: paddingTop, right: paddingRight, bottom: paddingBottom, left: paddingLeft });
      }

      if (mirrorRef && mirrorRef.current) {
        const getInputCSS = (prop, isnumber) => {
          let val = activeElement ? document.defaultView?.getComputedStyle(activeElement, null).getPropertyValue(prop) : undefined;
          return isnumber && val ? parseFloat(val) : val || 0;
        };

        let cssDefaultStyles = `
        top: 0;
        left: 0;
        position: absolute;
        visibility: hidden;
        pointer-events: none;
        z-index: -999;
        white-space: pre-wrap;
        `,
          listOfModifiers = [
            'direction',
            'font-family',
            'font-size',
            'font-size-adjust',
            'font-variant',
            'font-weight',
            'font-style',
            'letter-spacing',
            'text-align',
            'text-indent',
            'text-transform',
            'word-wrap',
            'word-spacing',
            'box-sizing',
            'width',
            'height',
            'padding',
            'padding-left',
            'padding-right',
            'padding-top',
            'padding-bottom',
            'margin',
            'border',
            'flex-grow',
            'flex-shrink',
            'resize',
            'min-height',
            'line-height',
          ];
        for (let i = 0; i < listOfModifiers.length; i++) {
          let property = listOfModifiers[i];
          cssDefaultStyles += property + ':' + getInputCSS(property, false) + ';';
        }
        const textElement: HTMLDivElement | null = mirrorRef.current;
        if (textElement !== null) {
          (textElement as HTMLDivElement).style.cssText = cssDefaultStyles;
          (textElement as HTMLDivElement).scrollTop = elementScrollY;
        }
      }
    }
  }, [activeElement, resizeElement, resizeWindow, windowScrollY, elementScrollY, textValue, mirrorRef, highlights, paraphrases, grammarReplacements]);

  const renderMirror = useCallback(() => {
    return <div ref={mirrorRef} id={'hundert-worte-mirror'} contentEditable={true} dangerouslySetInnerHTML={{ __html: textValue }} />;
  }, [activeElement, resizeElement, resizeWindow, windowScrollY, elementScrollY, textValue, mirrorRef, highlights, paraphrases, grammarReplacements]);

  return (
    <>
      <div id={'highlight-wrapper'}>
        <div
          id={'highlight-container'}
          className={classes.highlightContainer}
          style={{
            top: parentPadding.top,
            left: parentPadding.left,
            right: parentPadding.right,
            bottom: parentPadding.bottom,
            padding: padding,
            margin: margin,
            width: width,
            height: resizeElement.height ? resizeElement.height : height,
            position: 'absolute',
            pointerEvents: 'none',
            overflow: 'hidden',
          }}
        >
          {diagnosticMode.active &&
            highlights.map((highlight, index) => (
              <Highlight
                key={index}
                activeElement={activeElement?.tagName === 'DIV' ? activeElement : mirrorRef.current}
                highlight={highlight}
                highlightTexts={highlightTexts}
                diagnosticHighlights={highlights}
                diagnosticMode={diagnosticMode}
                resizeElement={resizeElement}
                resizeWindow={resizeWindow}
                windowScrollY={windowScrollY}
                elementScrollY={elementScrollY}
                parentElementScrollTop={parentElementScrollTop}
              />
            ))}
          {grammarReplacements?.map((grammar, index) => (
            <Highlight
              key={index}
              activeElement={activeElement?.tagName === 'DIV' ? activeElement : mirrorRef.current}
              highlight={grammar}
              highlightTexts={highlightTexts}
              diagnosticMode={diagnosticMode}
              resizeElement={resizeElement}
              resizeWindow={resizeWindow}
              windowScrollY={windowScrollY}
              elementScrollY={elementScrollY}
              parentElementScrollTop={parentElementScrollTop}
              grammar={true}
              firstSuggestion={firstSuggestion}
            />
          ))}
          {paraphrases?.map((paraphrase, index) => (
            <Highlight
              key={index}
              activeElement={activeElement?.tagName === 'DIV' ? activeElement : mirrorRef.current}
              highlight={paraphrase}
              highlightTexts={highlightTexts}
              diagnosticMode={diagnosticMode}
              resizeElement={resizeElement}
              resizeWindow={resizeWindow}
              windowScrollY={windowScrollY}
              elementScrollY={elementScrollY}
              parentElementScrollTop={parentElementScrollTop}
              paraphrase={true}
              firstSuggestion={firstSuggestion}
            />
          ))}
        </div>
        {activeElement?.tagName === 'TEXTAREA' && renderMirror()}
      </div>
    </>
  );
};

const useStyles = makeStyles()((theme) => ({
  highlightContainer: {
    display: 'flex',
    alignItems: 'flex-end',
    justifyContent: 'flex-end',
    pointerEvents: 'none',
    boxSizing: 'content-box',
    zIndex: ZIndices.HIGHLIGHT_RENDERER,
  },
}));

export default HighlightRenderer;
