import { CircularProgress } from '@mui/material';
import useResizeObserver from '@react-hook/resize-observer';
import $ from 'jquery';
import _ from 'lodash';
import React, { useEffect, useState } from 'react';
import { makeStyles } from 'tss-react/mui';
import shallow from 'zustand/shallow';
import { AugmentedWritingActions, GeneralActions } from '../enums/actions';
import { AWTriggers, AWTypes, Modes, ZIndices } from '../enums/enums';
import i18n from '../i18n';
import useAugmentedWritingStore from '../stores/augmentedWritingStore';
import usePanelStore from '../stores/panelStore';
import useProfileStore from '../stores/profileStore';
import { getMostInnerTextNode, getTextFromActiveElement, sendMessageToBackground } from '../utils/helper';
import { getAnalysisButton } from '../utils/imageUtils';
import { isNormalLinkedin, isRecruiter, isSalesNav } from '../utils/linkedinUtils';
import useLanguageStore from '../stores/languageStore';

interface Props {
  activeElement: HTMLDivElement | HTMLTextAreaElement | null;
  scrollY: number;
  isScrolling: boolean;

  resetAnalysisResults(keepScore: boolean): void;
}

const ButtonWrapper: React.FC<Props> = ({ activeElement, scrollY, isScrolling, resetAnalysisResults }) => {
  const userLanguage = useLanguageStore((state) => state.userLanguage);
  const lang = !_.isNil(userLanguage) ? userLanguage : i18n.languages[0];
  const { contact, profileLoading } = useProfileStore((state) => ({ contact: state.contact, profileLoading: state.profileLoading }), shallow);
  const { analysisLoading, setAnalysisLoading } = useAugmentedWritingStore(
    (state) => ({
      analysisLoading: state.analysisLoading,
      setAnalysisLoading: state.setAnalysisLoading,
    }),
    shallow
  );
  const fingerprints = useAugmentedWritingStore((state) => state.fingerprints);
  const { togglePanel, setMode } = usePanelStore((state) => ({ togglePanel: state.togglePanel, setMode: state.setMode }), shallow);
  const { classes, cx } = useStyles({ analyzedPath: getAnalysisButton(true), notAnalyzedPath: getAnalysisButton(false) });
  const contactAssessment = contact?.assessment;

  // both needed to trigger re-renders for changes in window or element size
  const [, setResizeWindow] = useState<{ height: number; width: number }>({ height: 0, width: 0 });
  const [, setResizeElement] = useState({ height: 0, width: 0 });

  const rects = activeElement?.getBoundingClientRect();
  const compStyles = !_.isNil(activeElement) ? getComputedStyle(activeElement) : undefined;

  const parentElement = activeElement?.tagName === 'DIV' ? activeElement.parentElement?.parentElement : activeElement?.parentElement;
  const parentElementScrollTop = parentElement?.scrollTop;
  const parentHeight = `calc(${parentElement?.clientHeight}px - ${compStyles?.paddingTop} - ${compStyles?.paddingBottom})`;

  const padding = !_.isNil(compStyles) ? `${compStyles.padding}` : '0px';
  const width = !_.isNil(compStyles) && !_.isNil(rects) ? `calc(${rects.width}px - ${compStyles.paddingLeft} - ${compStyles.paddingRight})` : '0px';
  const height =
    !_.isNil(compStyles) && !_.isNil(rects)
      ? hasSmallerParent(activeElement) || isSalesNav()
        ? parentHeight
        : `calc(${rects.height}px - ${compStyles.paddingTop} - ${compStyles.paddingBottom})`
      : '0px';

  const myObserver = useResizeObserver(activeElement, (entry) => {
    const rect = entry.contentRect;
    setTimeout(() => {
      setResizeElement(rect);
    }, 150);
  });

  const analyzeText = () => {
    if (activeElement) {
      const text = getTextFromActiveElement(activeElement);
      const profile = contact?.profile;
      const assessment = contactAssessment;
      const domain = AWTypes.LINKEDIN_MSG;

      if (text.length > 0 && profile && !_.isNil(assessment)) {
        resetAnalysisResults(true);

        const jqueryContents: any[] = $(activeElement).contents();
        _.forEach(jqueryContents, (node) => {
          const nodeList = getMostInnerTextNode(node);
          _.forEach(nodeList, (textNode) => {
            const trimTextNodeContent = textNode?.textContent?.trim();
            textNode.textContent = trimTextNodeContent || '';
          });
        });

        sendMessageToBackground({
          action: AugmentedWritingActions.POST_AUGMENTED_WRITING_SUGGESTIONS_REQUEST,
          body: { text, awTrigger: AWTriggers.Manual, profile, domain, lang, ignoredFingerprints: fingerprints },
        });
        setAnalysisLoading(true);
      }
      setMode(Modes.WRITER);
    }
  };

  useEffect(() => {
    if (activeElement) {
      const observableElement =
        activeElement.tagName === 'DIV' ? activeElement.offsetParent?.parentElement || activeElement.parentElement || activeElement : activeElement;
      myObserver.observe(observableElement);
    }

    return () => {
      myObserver?.disconnect();
    };
  }, [activeElement]);

  useEffect(() => {
    const messageListener = (request, sender, callback) => {
      if (request.action === AugmentedWritingActions.ANALYZE_TEXT) {
        if (activeElement) {
          analyzeText();
        }
      }

      if (request.action === GeneralActions.RESIZE_WINDOW) {
        setResizeWindow(request.body);
      }
    };

    chrome?.runtime?.onMessage.addListener(messageListener);
    return () => {
      chrome?.runtime?.onMessage.removeListener(messageListener);
    };
  }, [activeElement, contact, fingerprints]);

  function hasSmallerParent(el: HTMLDivElement | HTMLTextAreaElement | null) {
    const elementHeight = el?.getBoundingClientRect().height;
    const parentHeight = el?.tagName === 'DIV' ? el?.offsetParent?.parentElement?.clientHeight : el?.offsetParent?.clientHeight;

    return elementHeight && parentHeight ? parentHeight < elementHeight : false;
  }

  return (
    <>
      {!_.isNil(activeElement) ? (
        <div id={'btn-wrapper'}>
          <div
            className={classes.btnContainer}
            style={{
              top: `calc(${rects?.y}px + ${scrollY}px + ${parentElementScrollTop}px)`,
              left: `calc(${rects?.x}px)`,
              padding: padding,
              width: width,
              height: height,
              position: 'absolute',
              visibility: isScrolling ? 'hidden' : 'visible',
            }}
          >
            <div
              style={{
                position: 'absolute',
                bottom: isRecruiter() ? compStyles?.paddingBottom : isSalesNav() ? 'calc(-24px / 2 - 48px / 2)' : 0,
                right: isNormalLinkedin() ? '-32px' : isSalesNav() ? undefined : isRecruiter() ? '0px' : undefined,
                left: isSalesNav() ? 'calc(32px + 16px)' : undefined,
                width: '24px',
                height: '24px',
              }}
            >
              {profileLoading || analysisLoading ? (
                <div className={cx(classes.spinnerContainer, profileLoading ? 'profile' : analysisLoading ? 'analysis' : null)}>
                  <CircularProgress className={classes.spinner} />
                </div>
              ) : !_.isNil(contactAssessment) && !_.isNil(contact?.profile) ? (
                <div
                  className={cx(classes.analysisButton, _.isNil(contactAssessment) ? 'disabled' : null)}
                  onClick={() => {
                    if (!_.isNil(contactAssessment)) {
                      analyzeText();
                      togglePanel(true);
                    }
                  }}
                />
              ) : null}
            </div>
          </div>
        </div>
      ) : null}
    </>
  );
};

const useStyles = makeStyles<{ analyzedPath: string | undefined; notAnalyzedPath: string | undefined }>()(
  (theme, { analyzedPath, notAnalyzedPath }) => ({
    btnContainer: {
      display: 'flex',
      alignItems: 'flex-end',
      justifyContent: 'flex-end',
      pointerEvents: 'none',
      boxSizing: 'content-box',
      zIndex: ZIndices.ANALYSIS_BUTTON,
    },
    spinnerContainer: {
      borderRadius: '50%',
      display: 'flex',
      alignItems: 'center',
      justifyContent: 'center',
      width: '24px !important',
      height: '24px !important',
      '&.profile': {
        background: theme.palette.secondary.main,
      },
      '&.analysis': {
        background: theme.palette.primary.main,
      },
    },
    spinner: {
      width: '18px !important',
      height: '18px !important',
      color: '#FFF',
    },
    analysisButton: {
      width: '24px',
      height: '24px',
      cursor: 'pointer',
      pointerEvents: 'all',
      backgroundImage: `url(${notAnalyzedPath})`,
      backgroundSize: 'cover',
      '&:hover': {
        backgroundImage: `url(${analyzedPath})`,
      },
      '&.disabled': {
        filter: 'grayscale(100%)',
        pointerEvents: 'none',
      },
    },
  })
);

export default ButtonWrapper;
