import _ from 'lodash';
import React, { useEffect, useState } from 'react';
import { SidebarNote } from '../../../types/augmentedWriting';
import NoteItem from './NoteItem';
interface Props {
  sidebarNotes: SidebarNote[];

  onCategoryClicked(sidebarNote: SidebarNote, category?: string): void;
}

const NotesList: React.FC<Props> = ({ sidebarNotes, onCategoryClicked }) => {
  const [sortedNotes, setSortedNotes] = useState<SidebarNote[]>([]);
  const [expanded, setExpanded] = useState<string | false>(false);

  useEffect(() => {
    const levelOrder = [1, 0, -1];
    const tempNotes = _.sortBy(sidebarNotes, (note) => {
      return levelOrder.indexOf(note.level);
    });
    setSortedNotes(tempNotes);

    if (expanded && !sidebarNotes.map((note) => note.key).includes(expanded)) {
      setExpanded(false);
    } else if (expanded) {
      const foundNote = sidebarNotes.find((note) => note.key === expanded);

      if (!_.isNil(foundNote)) {
        onCategoryClicked(foundNote, expanded);
      }
    }
  }, [sidebarNotes]);

  const handleExpandNote = (key: string, sidebarNote: SidebarNote) => {
    return () => {
      if (key === expanded) {
        setExpanded(false);
      } else {
        setExpanded(key);
      }
      onCategoryClicked(sidebarNote, key);
    };
  };

  return (
    <div>
      {sortedNotes.map((note, index) => (
        <NoteItem
          key={index}
          sidebarNote={note}
          expanded={expanded}
          handleExpandNote={handleExpandNote}
          isLast={_.isEqual(sidebarNotes.length - 1, index)}
        />
      ))}
    </div>
  );
};

export default NotesList;
