import create from 'zustand';

interface Snackbar {
  open: boolean;
  message: string;
  type?: 'error' | 'warning' | 'info' | 'success';
}

interface SnackbarStore {
  snackbar: Snackbar;

  openSnackbar(open: boolean, message: string, type?: 'error' | 'warning' | 'info' | 'success');

  closeSnackbar: () => void;
}

const defaultValues = {
  open: false,
  message: '',
  type: undefined,
};

const useSnackbarStore = create<SnackbarStore>((set) => ({
  snackbar: defaultValues,
  openSnackbar(open: boolean, message: string, type?: 'error' | 'warning' | 'info' | 'success') {
    set(() => ({ snackbar: { open, message, type } }));
  },

  closeSnackbar() {
    set(() => ({ snackbar: defaultValues }));
  },
}));

export default useSnackbarStore;
