import { Stack, Typography } from '@mui/material';
import _ from 'lodash';
import React from 'react';
import { useTranslation } from 'react-i18next';
import { makeStyles } from 'tss-react/mui';
import { RelationshipQuality } from '../../../types/analysis';
import { Assessment } from '../../../types/assessment';
import { ProfileValues } from '../../../types/contact';
import Legend from './Legend';
import Match from './Match';
import MatchCompareGraph from './MatchCompareGraph';
import MotiveChart from './MotiveChart';
import PersonalityType from './PersonalityType';

interface Props {
  contactAssessment: Assessment | undefined;
  contactProfile: ProfileValues | undefined;
  userProfile: ProfileValues | undefined;
  relationshipQuality: RelationshipQuality | undefined;
}

const StyleMatch: React.FC<Props> = ({ contactAssessment, contactProfile, userProfile, relationshipQuality }) => {
  const { classes } = useStyles();
  const { t } = useTranslation();

  return (
    <Stack spacing={1}>
      {!_.isNil(relationshipQuality) ? <Match score={relationshipQuality.qualityFactor} /> : null}
      {!_.isNil(contactProfile) ? <Legend hideOwn={_.isNil(userProfile)} /> : null}
      {!_.isNil(contactProfile) ? (
        <div className={classes.card}>
          <Typography className={classes.title}>{t('motiveMatch')}</Typography>
          <MotiveChart contactScores={contactProfile} userScores={userProfile} />
        </div>
      ) : null}
      {!_.isNil(contactProfile?.authenticity) ? (
        <MatchCompareGraph
          title={t('languageStyleMatch')}
          categoryKey={'authenticity'}
          leftText={t('formal')}
          rightText={t('informal')}
          contactScore={contactProfile?.authenticity}
          userScore={userProfile?.authenticity}
        />
      ) : null}
      {!_.isNil(contactAssessment) ? <PersonalityType assessment={contactAssessment} /> : null}
    </Stack>
  );
};

const useStyles = makeStyles()((_theme) => ({
  card: {
    width: '100%',
    background: '#FFF',
    padding: '8px',
  },
  title: {
    fontSize: '12px',
    fontWeight: 900,
    textTransform: 'uppercase',
    textAlign: 'center',
    whiteSpace: 'pre-wrap',
    marginBottom: '8px',
  },
}));

export default StyleMatch;
