import ArrowForwardIcon from '@mui/icons-material/ArrowForward';
import CloseIcon from '@mui/icons-material/Close';
import DragIndicatorIcon from '@mui/icons-material/DragIndicator';
import LinkIcon from '@mui/icons-material/Link';
import LinkOffIcon from '@mui/icons-material/LinkOff';
import { ButtonBase, Grid, Tooltip } from '@mui/material';
import React from 'react';
import { useTranslation } from 'react-i18next';
import { makeStyles } from 'tss-react/mui';
import shallow from 'zustand/shallow';
import { ZIndices } from '../../enums/enums';
import useContainerStore from '../../stores/containerStore';
import usePanelStore from '../../stores/panelStore';

interface Props {
  authenticated?: boolean;

  closePanel(event: React.MouseEvent): void;
}

const ExtHeader: React.FC<Props> = ({ authenticated, closePanel }) => {
  const { classes, cx } = useStyles();
  const { t } = useTranslation();
  const { attached, setAttachment, collapsed, collapsePanel } = usePanelStore(
    (state) => ({ attached: state.attached, setAttachment: state.setAttachment, collapsed: state.collapsed, collapsePanel: state.collapsePanel }),
    shallow
  );
  const tooltipContainerElement = useContainerStore((state) => state.tooltipContainer);

  return (
    <Grid
      className={cx(classes.modalHandle, !attached && 'sidebar-detached')}
      container={true}
      justifyContent={'space-between'}
      alignItems={'center'}
    >
      <Grid className={classes.leftGrid} item={true} xs={attached ? 8 : 4}>
        {authenticated && attached ? (
          <ButtonBase onClick={collapsePanel}>
            <ArrowForwardIcon className={cx(classes.collapse, collapsed ? 'is-collapsed' : null)} />
          </ButtonBase>
        ) : null}
      </Grid>
      {!attached && (
        <Grid className={cx(classes.middleGrid, 'panel-handle')} item={true} xs={4}>
          <Tooltip
            classes={{ tooltip: classes.tooltip }}
            PopperProps={{
              container: tooltipContainerElement,
              style: { zIndex: ZIndices.TOOLTIP },
            }}
            title={t('dragInfo')}
            placement={'top'}
            arrow={true}
          >
            <DragIndicatorIcon className={classes.dragIndicator} />
          </Tooltip>
        </Grid>
      )}
      <Grid className={classes.rightGrid} item={true} xs={4} style={{ display: 'flex' }}>
        {!collapsed ? (
          <>
            <Tooltip
              classes={{ tooltip: classes.tooltip }}
              PopperProps={{
                container: tooltipContainerElement,
                style: { zIndex: ZIndices.TOOLTIP },
              }}
              title={attached ? t('detach') : t('attach')}
              placement={'top'}
              arrow={true}
            >
              <div className={classes.actionButton} onClick={(event) => setAttachment(!attached)}>
                {attached ? <LinkOffIcon className={classes.icon} /> : <LinkIcon className={classes.icon} />}
              </div>
            </Tooltip>
            <Tooltip
              classes={{ tooltip: classes.tooltip }}
              PopperProps={{
                container: tooltipContainerElement,
                style: { zIndex: ZIndices.TOOLTIP },
              }}
              title={t('close')!}
              placement={'top'}
              arrow={true}
            >
              <div className={classes.actionButton} onClick={closePanel}>
                <CloseIcon className={classes.icon} />
              </div>
            </Tooltip>
          </>
        ) : null}
      </Grid>
    </Grid>
  );
};

const useStyles = makeStyles()((theme) => ({
  modalHandle: {
    background: '#FFF',
    height: '35px',
  },
  leftGrid: {
    height: '100%',
    display: 'flex',
    alignItems: 'center',
    padding: '4px',
  },
  middleGrid: {
    display: 'flex',
    alignItems: 'center',
    justifyContent: 'center',
  },
  dragIndicator: {
    fontSize: '24px',
    color: theme.palette.primary.main,
    transform: 'rotate(90deg)',
    cursor: 'grab',
    '&:hover': {
      color: theme.palette.secondary.main,
    },
  },
  rightGrid: {
    height: '100%',
    display: 'flex',
    alignItems: 'center',
    justifyContent: 'flex-end',
    paddingRight: '10px',
  },
  icon: {
    fontSize: '14px',
  },
  actionButton: {
    display: 'flex',
    alignItems: 'center',
    justifyContent: 'center',
    borderRadius: '50%',
    height: '18px',
    width: '18px',
    padding: '4px',
    background: theme.palette.primary.main,
    color: '#fff',
    cursor: 'pointer',
    marginLeft: '5px',
    '&:hover': {
      background: theme.palette.secondary.main,
    },
  },
  tooltip: {
    fontSize: '15px',
  },
  collapse: {
    fontSize: '20px',
    color: '#000',
    transition: '500ms',
    marginLeft: '24px',
    '&:hover': {
      color: theme.palette.primary.main,
    },
    '&.is-collapsed': {
      transform: 'rotate(180deg)',
    },
  },
}));

export default ExtHeader;
