import { Typography } from '@mui/material';
import _ from 'lodash';
import React from 'react';
import { useTranslation } from 'react-i18next';
import { makeStyles } from 'tss-react/mui';
import { TooltipContentType } from '../../enums/enums';
import { ISuggestionItem, SidebarNote } from '../../types/augmentedWriting';
import PaiDotLoader from '../basic/PaiDotLoader';
import NoteList from './NoteList/NoteList';
import SuggestionCard from './Suggestion/SuggestionCard';

interface Props {
  allSuggestions: ISuggestionItem[];
  sidebarNotes: SidebarNote[];
  loading: boolean;

  skipSuggestion(content: any): () => void;

  ignoreSuggestion(content: any, id: string): () => void;

  insertAtPosition: (word: string, highlightId: string, type: TooltipContentType) => void;

  onSidebarNotesCategoryClicked(sidebarNote: SidebarNote, category?: string): void;
}

const Suggestions: React.FC<Props> = ({
  allSuggestions,
  sidebarNotes,
  loading,
  skipSuggestion,
  ignoreSuggestion,
  insertAtPosition,
  onSidebarNotesCategoryClicked,
}) => {
  const { classes } = useStyles();
  const { t } = useTranslation();

  return (
    <>
      {loading ? <PaiDotLoader size="normal" /> : null}
      {!loading && !_.isNil(allSuggestions) && allSuggestions.length > 0 ? (
        <>
          {_.take(allSuggestions, 1).map((suggestion) => (
            <SuggestionCard
              key={suggestion.highlightId}
              suggestion={suggestion}
              skipSuggestion={skipSuggestion}
              ignoreSuggestion={ignoreSuggestion}
              insertAtPosition={insertAtPosition}
            />
          ))}
          {allSuggestions.length > 1 ? (
            <Typography className={classes.moreSuggestions}>{t('plusMoreSuggestions', { count: allSuggestions.length - 1 })}</Typography>
          ) : null}
        </>
      ) : null}
      {!loading && !_.isNil(sidebarNotes) && sidebarNotes.length > 0 && allSuggestions.length === 0 ? (
        <>
          <NoteList sidebarNotes={sidebarNotes} onCategoryClicked={onSidebarNotesCategoryClicked} />
        </>
      ) : null}
    </>
  );
};

const useStyles = makeStyles()((_theme) => ({
  title: {
    fontSize: '13px',
    fontWeight: 'bold',
    textTransform: 'uppercase',
    textAlign: 'center',
    marginBottom: '16px',
  },
  moreSuggestions: {
    fontSize: '11px',
    fontWeight: 'bold',
    textAlign: 'center',
  },
}));

export default Suggestions;
