import { Stack } from '@mui/material';
import _ from 'lodash';
import React, { useState } from 'react';
import { Modes, Sources, TooltipContentType } from '../../enums/enums';
import useAugmentedWritingStore from '../../stores/augmentedWritingStore';
import usePanelStore from '../../stores/panelStore';
import useProfileStore from '../../stores/profileStore';
import { Assessment } from '../../types/assessment';
import { ISuggestionItem, Scores, SidebarNote } from '../../types/augmentedWriting';
import { ProfileValues } from '../../types/contact';
import Match from '../analysis/AnalysisResults/Match';
import TextOptimizationResults from '../analysis/AnalysisResults/TextOptimizationResults';
import defaultConfig from '../analysis/default';
import Suggestions from './Suggestions';
import TextOptimizationInfo from './TextOptimizationInfo';
import UserDone from './UserDone';

interface Props {
  contactAssessment?: Assessment;
  contactProfile?: ProfileValues;
  userProfile?: ProfileValues;

  scores: Scores;
  sidebarNotes: SidebarNote[];
  allSuggestions: ISuggestionItem[];

  onChartCategoryClicked?(category: string | string[]): void;

  onSidebarNotesCategoryClicked?(category: any, sidebarNote: SidebarNote): void;

  onCategoryClick?(category: string | undefined, composedCategory: any, source: Sources, removeText?: string): void;

  insertAtPosition: (word: string, highlightId: string, type: TooltipContentType) => void;

  skipSuggestion(content: any): () => void;

  ignoreSuggestion(content: any, id: string): () => void;
}

const TextOptimization: React.FC<Props> = ({
  contactAssessment,
  contactProfile,
  userProfile,
  scores,
  sidebarNotes,
  allSuggestions,
  onCategoryClick,
  insertAtPosition,
  skipSuggestion,
  ignoreSuggestion,
  onChartCategoryClicked,
  onSidebarNotesCategoryClicked,
}) => {
  const analysisLoading = useAugmentedWritingStore((state) => state.analysisLoading);
  const userDone = useAugmentedWritingStore((state) => state.userDone);
  const contact = useProfileStore((state) => state.contact);
  const mode = usePanelStore((state) => state.mode);

  const [clickedChartCategoryKey, setClickedChartCategoryKey] = useState<string>();

  const onLabelClick = (category?: string) => {
    if (category) {
      if (onCategoryClick) {
        const composedCategory = _.get(defaultConfig, `augmentedWriting.customer.scores.${category}`);
        if (composedCategory?.composed) {
          onCategoryClick(category, composedCategory, Sources.CHART);
        } else {
          onCategoryClick(category, [category], Sources.CHART);
        }
        if (category === clickedChartCategoryKey) {
          setClickedChartCategoryKey(undefined);
        } else {
          setClickedChartCategoryKey(category);
        }
      } else if (onChartCategoryClicked) {
        onChartCategoryClicked(category);
      }
    }
  };

  const onSidebarNoteClick = (sidebarNote: SidebarNote, category?: string) => {
    if (category) {
      if (onCategoryClick) {
        setClickedChartCategoryKey(undefined);
        let combinedCategory: any = '';
        const categoryDefinition = _.get(defaultConfig, `augmentedWriting.customer.scores.${category}`);
        if (categoryDefinition) {
          // If composed is false or not set we use the key as the attribute name
          if (!categoryDefinition.composed) {
            combinedCategory = [category];
            // Check if composed is an array of strings
          } else if (_.isArray(categoryDefinition.composed) && _.every(categoryDefinition.composed, _.isString)) {
            combinedCategory = sidebarNote.remove_categories.length > 0 ? sidebarNote.remove_categories : categoryDefinition.composed;
          }
        } else {
          combinedCategory = [category];
        }
        onCategoryClick(category, combinedCategory, Sources.SIDEBAR_NOTES, sidebarNote.remove_text);
      } else if (onSidebarNotesCategoryClicked) {
        onSidebarNotesCategoryClicked(category, sidebarNote);
      }
    }
  };

  return (
    <Stack spacing={1}>
      {mode === Modes.WRITER ? (
        <>
          <>
            <Suggestions
              allSuggestions={allSuggestions}
              sidebarNotes={sidebarNotes}
              loading={analysisLoading}
              skipSuggestion={skipSuggestion}
              ignoreSuggestion={ignoreSuggestion}
              insertAtPosition={insertAtPosition}
              onSidebarNotesCategoryClicked={onSidebarNoteClick}
            />

            {userDone ? <UserDone profileName={`${contact?.firstName || ''} ${contact?.lastName || ''}`} userAssessment={contactAssessment} /> : null}

            {!userDone ? <Match score={scores.overall * 100} /> : null}

            {contactProfile ? (
              <TextOptimizationResults
                contactProfile={contactProfile}
                userProfile={userProfile}
                clickedChartCategoryKey={clickedChartCategoryKey}
                onChartCategoryClicked={onLabelClick}
              />
            ) : null}
          </>
        </>
      ) : (
        <TextOptimizationInfo />
      )}
    </Stack>
  );
};

export default TextOptimization;
