import create from 'zustand';

interface ContainerStoreState {
  tooltipContainer: HTMLElement | null;
  panelContainer: HTMLElement | null;

  setTooltipContainer: (newElement: HTMLElement | null) => void;

  setPanelContainer: (newElement: HTMLElement | null) => void;
}

const useContainerStore = create<ContainerStoreState>((set) => ({
  tooltipContainer: null,
  panelContainer: null,

  setTooltipContainer(newElement: HTMLElement | null) {
    set(() => ({ tooltipContainer: newElement }));
  },

  setPanelContainer(newElement: HTMLElement | null) {
    set(() => ({ panelContainer: newElement }));
  },
}));

export default useContainerStore;
