import { Button, Dialog, DialogActions, DialogContent, Typography } from '@mui/material';
import React from 'react';
import { useTranslation } from 'react-i18next';
import { makeStyles } from 'tss-react/mui';
import useContainerStore from '../../stores/containerStore';
import { Colors } from '../../theme/theme';
import PaiTextField from '../basic/PaiTextField';

interface Props {
  open: boolean;
  projectName: string;
  nameTakenError: boolean | undefined;
  loading: boolean;

  handleProjectNameChange(event: React.ChangeEvent<HTMLInputElement>): void;

  handleClose(): void;

  acceptProjectName(): void;
}

const EnterProjectNameDialog: React.FC<Props> = ({
  open,
  projectName,
  nameTakenError,
  loading,
  handleProjectNameChange,
  handleClose,
  acceptProjectName,
}) => {
  const { classes, cx } = useStyles();
  const { t } = useTranslation();

  const container = useContainerStore((state) => state.panelContainer);

  return (
    <Dialog open={open} classes={{ paper: classes.paper }} fullWidth={true} maxWidth={'xs'} container={container}>
      <DialogContent className={classes.content}>
        <PaiTextField value={projectName} placeholder={t('enterProjectName')} onChange={handleProjectNameChange} />
        {nameTakenError ? <Typography className={classes.errorText}>{t('nameAlreadyTakenError')}</Typography> : null}
      </DialogContent>
      <DialogActions className={classes.actions}>
        <Button className={cx(classes.button, 'cancel')} onClick={handleClose}>
          {t('cancel')}
        </Button>
        <Button className={cx(classes.button, 'accept')} onClick={acceptProjectName} disabled={projectName.trim() === '' || loading}>
          {t('accept')}
        </Button>
      </DialogActions>
    </Dialog>
  );
};

const useStyles = makeStyles()((theme) => ({
  paper: {
    borderRadius: 0,
  },
  content: {
    paddingBottom: '12px',
  },
  errorText: {
    fontSize: '11px',
    color: 'red',
    marginTop: '4px',
  },
  actions: {
    justifyContent: 'center',
  },
  button: {
    fontSize: '13px',
    lineHeight: 1.3,
    textTransform: 'none',
    borderRadius: 0,
    '&.cancel': {
      color: theme.palette.secondary.main,
      '&:hover': {
        background: theme.palette.secondary.main,
        color: '#FFF',
      },
    },
    '&.accept': {
      color: theme.palette.primary.main,
      '&:hover': {
        background: theme.palette.primary.main,
        color: '#FFF',
      },
    },
    '&.Mui-disabled': {
      color: Colors.GREY_SHADE_1,
    },
  },
}));

export default EnterProjectNameDialog;
