import { ProfileBases } from '../stores/profileStore';
import { Assessment } from './assessment';

export enum BaseProfileTypes {
  TARGET_GROUP = 'TargetGroup',
  CONTACT = 'Contact',
}

export interface ProfileValues {
  jointPosAffil: number;
  jointPosAchieve: number;
  jointPosPower: number;
  authenticity: number;
  regFocus: number;
  quant?: number;
  preposition?: number;
  negation?: number;
  adverb?: number;
  article?: number;
  auxverb?: number;
  impersonalPronouns?: number;
  personalPronouns?: number;
}

export class Contact {
  public id: string;
  public globalContact: string;
  public firstname: string;
  public lastname: string;
  public name: string;
  public createDate: number;
  public updateDate: number;
  public contentLanguage: string;
  public inconsistentLanguage: true;
  public wordCount: number;
  public score: ProfileValues;
  public step?: ProfileValues;
  public companyWideVisibility: boolean;
  public isOwn: boolean;
  public externalId: string;
  public type: BaseProfileTypes | '';
  public profile?: ProfileValues;
  public percentiles?: ProfileValues;
  public analysesCount: number;
  public assessment?: Assessment;
  public qualityFactor?: number | string;
  public trend?: string;
  public occupation?: string;
  public basis?: ProfileBases;
  public matchedJobTitle?: string;

  constructor(response: any) {
    this.id = response.id;
    this.globalContact = response.globalContact;
    this.firstname = response.firstname;
    this.lastname = response.lastname;
    this.createDate = response.createDate;
    this.updateDate = response.updateDate;
    this.contentLanguage = response.contentLanguage;
    this.inconsistentLanguage = response.inconsistentLanguage;
    this.wordCount = response.wordCount;
    this.score = response.score;
    this.companyWideVisibility = response.companyWideVisibility;
    this.isOwn = response.isOwn;
    this.externalId = response.externalId;
    this.name = response.name;
    this.type = response.type;
    this.profile = response.profile;
    this.analysesCount = response.analysesCount;
    this.assessment = response.assessment;
    this.step = response.step;
    this.qualityFactor = response.qualityFactor;
    this.trend = response.trend;
    this.percentiles = response.percentiles;
    this.occupation = response.occupation;
    this.basis = response.basis;
    this.matchedJobTitle = response.matchedJobTitle;
  }
}
