import { Grid } from '@mui/material';
import _ from 'lodash';
import React, { useEffect, useRef, useState } from 'react';
import { makeStyles } from 'tss-react/mui';
import shallow from 'zustand/shallow';
import PaiDotLoader from '../components/basic/PaiDotLoader';
import QuotaLimitReached from '../components/sidePanel/QuotaLimitReached';
import ScrollContainer from '../components/sidePanel/ScrollContainer';
import SelectionContent from '../components/sidePanel/SelectionContent';
import Sidebar from '../components/sidePanel/SideBar';
import { GeneralActions, LinkedinActions, TemplateActions } from '../enums/actions';
import { Modes, SideBarSelection, Sources, TooltipContentType } from '../enums/enums';
import i18n from '../i18n';
import useContainerStore from '../stores/containerStore';
import useElementStore from '../stores/elementStore';
import useLanguageStore from '../stores/languageStore';
import usePanelStore from '../stores/panelStore';
import useProfileStore from '../stores/profileStore';
import useTemplateStore from '../stores/templatesStore';
import useTextGenerationStore from '../stores/textGenerationStore';
import useUserStore from '../stores/userStore';
import { RelationshipQuality, Tendency } from '../types/analysis';
import { ISuggestionItem, Scores, SidebarNote } from '../types/augmentedWriting';
import { sendMessageToBackground } from '../utils/helper';
import {
  extractLinkedRecruiterUserName,
  getLinkedInRecHandle,
  isLinkedInRecThreadsPage,
  isLinkedInRecUserPage,
  isLinkedInSalesNavSearchLeadsPage,
  isLinkedInSalesNavThreadsPage,
  isLinkedInSalesNavUserPage,
  isLinkedInThreadsPage,
  isLinkedInUserPage,
} from '../utils/linkedinUtils';

interface Props {
  scores: Scores;
  allSuggestions: ISuggestionItem[];
  sidebarNotes: SidebarNote[];

  onCategoryClick(category: string | undefined, composedCategory: any, source: Sources, removeText?: string): void;

  insertAtPosition: (word: string, highlightId: string, type: TooltipContentType) => void;

  skipSuggestion(content: any): () => void;

  ignoreSuggestion(content: any, id: string): () => void;
}

const Linkedin: React.FC<Props> = ({ scores, sidebarNotes, onCategoryClick, allSuggestions, insertAtPosition, skipSuggestion, ignoreSuggestion }) => {
  const { classes } = useStyles();

  const userLanguage = useLanguageStore((state) => state.userLanguage);
  const lang = !_.isNil(userLanguage) ? userLanguage : i18n.languages[0];

  const { quotaLimitReached } = useUserStore((state) => ({ quotaLimitReached: state.quotaLimitReached }), shallow);
  const { togglePanel, clickTrigger, setClickTrigger, setMode, mode } = usePanelStore(
    (state) => ({
      togglePanel: state.togglePanel,
      clickTrigger: state.clickTrigger,
      setClickTrigger: state.setClickTrigger,
      setMode: state.setMode,
      mode: state.mode,
    }),
    shallow
  );
  const { contact, userAnalysis, profileLoading, setProfileLoading, resetContact } = useProfileStore(
    (state) => ({
      contact: state.contact,
      userAnalysis: state.userAnalysis,
      profileLoading: state.profileLoading,
      setProfileLoading: state.setProfileLoading,
      resetContact: state.resetContact,
    }),
    shallow
  );

  const resetAllTextGeneration = useTextGenerationStore((state) => state.resetAllTextGeneration);

  const { setActiveElement } = useElementStore((state) => ({ setActiveElement: state.setActiveElement }));

  const setTemplates = useTemplateStore((state) => state.setTemplates);
  const setPanelContainer = useContainerStore((state) => state.setPanelContainer);

  const { collapsePanel, collapsed } = usePanelStore((state) => ({ collapsePanel: state.collapsePanel, collapsed: state.collapsed }), shallow);

  const userProfile = userAnalysis?.percentiles;
  const contactProfile = contact?.percentiles;
  const contactAssessment = contact?.assessment;

  const panelElementRef = useRef<any>(null);
  const [relationshipQuality, setRelationshipQuality] = useState<RelationshipQuality>();

  const [activeSelection, setActiveSelection] = useState<SideBarSelection | undefined>(SideBarSelection.ANALYSIS);

  const handleSelectionChange = (selection: SideBarSelection) => {
    setActiveSelection(selection);

    if (collapsed) {
      collapsePanel();
    }
  };

  useEffect(() => {
    setPanelContainer(panelElementRef.current);
    sendMessageToBackground({ action: GeneralActions.GET_CURRENT_URL });

    const messageListener = (request, sender, callback) => {
      if (request.action === TemplateActions.GET_EMAIL_TEMPLATES_RESPONSE) {
        const templatesResponse = request.body.emailTemplates?.map((template: any) => {
          return {
            key: template.id,
            name: template.phase.name,
            assessment: template.assessment,
            body: template.text,
            phase: template.phase,
          };
        });
        setTemplates(templatesResponse);
      }
    };

    chrome?.runtime?.onMessage.addListener(messageListener);
    return () => {
      chrome?.runtime?.onMessage.removeListener(messageListener);
    };
  }, []);

  useEffect(() => {
    if (!_.isNil(contact)) {
      if (!_.isNil(contact.qualityFactor) && contact.qualityFactor !== 'not enough data') {
        setRelationshipQuality({
          trend: contact.trend as Tendency,
          qualityFactor: +((contact.qualityFactor as number) * 100).toFixed(0),
        });
      } else {
        setRelationshipQuality(undefined);
      }

      if (!_.isNil(contact.assessment) && !_.isNil(contact.assessment.name)) {
        sendMessageToBackground({ action: TemplateActions.GET_EMAIL_TEMPLATES_REQUEST, body: { assessmentName: contact.assessment.name } });
      }
    }
  }, [contact]);

  /**
   * Contact analysis
   */

  const handleLinkedinAnalysis = () => {
    if (isLinkedInThreadsPage() || isLinkedInSalesNavThreadsPage() || isLinkedInRecThreadsPage()) {
      setMode(Modes.CONTACT_ANALYSIS);
      analyzeContactThread();
    } else if (isLinkedInUserPage() || isLinkedInSalesNavUserPage() || isLinkedInSalesNavSearchLeadsPage() || isLinkedInRecUserPage()) {
      setMode(Modes.CONTACT_ANALYSIS);
      analyzeContactProfile();
    }
  };

  const onAnalyzeContact = async () => {
    const currPath = window.location.pathname.split('/');
    const profileId = currPath[currPath.length - 2];
    sendMessageToBackground({ action: LinkedinActions.ANALYZE_LINKEDIN_USER, body: { profileId, lang } });
    setProfileLoading(true);
  };

  const onAnalyzeSalesNavContact = async () => {
    const currPath = window.location.pathname.split('/');
    const profileId = currPath.pop();
    sendMessageToBackground({ action: LinkedinActions.ANALYZE_LINKEDIN_SALESNAV_USER, body: { profileId, lang } });
    setProfileLoading(true);
  };

  const config: MutationObserverInit = {
    childList: true,
    characterData: true,
    subtree: true,
  };

  const onAnalyzeSalesNavSearchLeadsContact = async () => {
    const anchorElement = document.querySelectorAll('._lead-page-link_sqh8tm')[0];
    const userHref = (anchorElement as HTMLAnchorElement)?.href;
    const currPath = userHref?.split('/');
    const profileId = currPath?.pop();

    if (!_.isNil(profileId)) {
      sendMessageToBackground({ action: LinkedinActions.ANALYZE_LINKEDIN_SALESNAV_USER, body: { profileId, lang } });
      setProfileLoading(true);

      const elementObserver = new MutationObserver(function (mutations_list) {
        mutations_list.forEach(function (mutation) {
          mutation.removedNodes.forEach(function (removed_node) {
            const isElement = anchorElement === removed_node;
            const isChildOfElement = removed_node.contains(anchorElement);
            if (isChildOfElement || isElement) {
              togglePanel(false);
              setActiveElement(null);
              resetContact();
              resetAllTextGeneration();
              elementObserver?.disconnect();
            }
          });
        });
      });
      elementObserver?.observe(document.body, config);
    }
  };

  const onAnalyzeRecContact = async () => {
    const currPath = window.location.pathname;
    const profileId = extractLinkedRecruiterUserName(currPath);
    sendMessageToBackground({ action: LinkedinActions.ANALYZE_LINKEDIN_REC_USER, body: { profileId, lang } });
    setProfileLoading(true);
  };

  const onAnalyzeMessageThread = async () => {
    const currPath = window.location.pathname.split('/');
    const threadId = currPath[currPath.length - 2];
    sendMessageToBackground({ action: LinkedinActions.ANALYZE_LINKEDIN_MESSAGE, body: { threadId, lang } });
    setProfileLoading(true);
  };

  const onAnalyzeMessageSalesNavThread = async () => {
    const currPath = window.location.pathname.split('/');
    const threadId = currPath.pop();
    sendMessageToBackground({ action: LinkedinActions.ANALYZE_LINKEDIN_SALESNAV_MESSAGE, body: { threadId, lang } });
    setProfileLoading(true);
  };

  const onAnalyzeMessageRecThread = async () => {
    const currPath = getLinkedInRecHandle(document);
    if (currPath) {
      const profileId = extractLinkedRecruiterUserName(currPath);
      sendMessageToBackground({ action: LinkedinActions.ANALYZE_LINKEDIN_REC_MESSAGE, body: { profileId, lang } });
      setProfileLoading(true);
    }
  };

  const analyzeContactThread = () => {
    if (!profileLoading) {
      if (isLinkedInThreadsPage()) {
        onAnalyzeMessageThread();
      } else if (isLinkedInSalesNavThreadsPage()) {
        onAnalyzeMessageSalesNavThread();
      } else if (isLinkedInRecThreadsPage()) {
        onAnalyzeMessageRecThread();
      }
    }
  };

  const analyzeContactProfile = () => {
    if (!profileLoading) {
      if (isLinkedInUserPage()) {
        onAnalyzeContact();
      } else if (isLinkedInSalesNavUserPage()) {
        onAnalyzeSalesNavContact();
      } else if (isLinkedInSalesNavSearchLeadsPage()) {
        onAnalyzeSalesNavSearchLeadsContact();
      } else if (isLinkedInRecUserPage()) {
        onAnalyzeRecContact();
      }
    }
  };

  useEffect(() => {
    if (clickTrigger) {
      handleLinkedinAnalysis();
      setClickTrigger(false);
    }
  }, [clickTrigger, userLanguage]);

  return (
    <>
      <Grid className={classes.linkedinContainer} container={true} ref={panelElementRef} direction={'row'}>
        <div className={classes.resultsContainerSideBar}>
          <Sidebar mode={mode} activeSelection={activeSelection} handleSelectionChange={handleSelectionChange} />
        </div>
        <div className={classes.resultsContainer}>
          <ScrollContainer>
            {profileLoading && activeSelection !== SideBarSelection.OPTIONS ? (
              <div className={classes.loaderContainer}>
                <PaiDotLoader size="normal" />
              </div>
            ) : quotaLimitReached ? (
              <QuotaLimitReached />
            ) : mode === Modes.WRITER || mode === Modes.CONTACT_ANALYSIS ? (
              <SelectionContent
                activeSelection={activeSelection}
                scores={scores}
                sidebarNotes={sidebarNotes}
                allSuggestions={allSuggestions}
                onCategoryClick={onCategoryClick}
                insertAtPosition={insertAtPosition}
                skipSuggestion={skipSuggestion}
                ignoreSuggestion={ignoreSuggestion}
                contactAssessment={contactAssessment}
                contactProfile={contactProfile}
                userProfile={userProfile}
                relationshipQuality={relationshipQuality}
              />
            ) : (
              <></>
            )}
          </ScrollContainer>
        </div>
      </Grid>
    </>
  );
};

const useStyles = makeStyles()((_theme) => ({
  linkedinContainer: {
    height: '100%',
  },
  resultsContainer: {
    zIndex: 1,
    position: 'relative',
    height: '100%',
    width: '300px',
  },
  resultsContainerClosed: {
    display: 'none',
  },
  resultsContainerSideBar: {
    zIndex: 1,
    position: 'relative',
    height: '100%',
    width: '80px',
  },
  loaderContainer: {
    display: 'flex',
    justifyContent: 'center',
    alignItems: 'center',
    padding: '16px 0',
  },
}));

export default Linkedin;
