import { Grid } from '@mui/material';
import _ from 'lodash';
import React from 'react';
import { makeStyles } from 'tss-react/mui';
import { Assessment } from '../../types/assessment';
import PaiListItem from '../basic/PaiListItem';

interface Props {
  assessment: Assessment | undefined;
}

const BoosterWords: React.FC<Props> = ({ assessment }) => {
  const { classes } = useStyles();

  const wordList = assessment?.instructions.descriptions.wordlist;
  const wordListChunk = _.chunk(assessment?.instructions.descriptions.wordlist, 2);

  return (
    <div className={classes.card}>
      <Grid container={true}>
        {wordList &&
          wordListChunk.map((chunk, index) => (
            <Grid key={index} className={classes.listItem} item={true} xs={12}>
              <Grid container={true} justifyContent={'space-between'}>
                {chunk.map((item, itemIndex) => (
                  <Grid key={itemIndex} item={true} xs={5}>
                    <PaiListItem text={item} />
                  </Grid>
                ))}
              </Grid>
            </Grid>
          ))}
      </Grid>
    </div>
  );
};

const useStyles = makeStyles()((_theme) => ({
  card: {
    width: '100%',
    background: '#FFF',
    padding: '16px 16px 8px 16px',
  },
  listItem: {
    padding: '2px 0',
  },
}));

export default BoosterWords;
