import { useEffect, useState } from 'react';
import { isExpired } from 'react-jwt';
import { ApiActions } from '../enums/actions';
import { sendMessageToBackground } from '../utils/helper';

export const useAuthorization = () => {
  const [authenticated, setAuthenticated] = useState<boolean>();

  const validate = (validateWithClearStorage = true) => {
    chrome.storage.local.get(['token'], ({ token }) => {
      if (token && token.accessToken) {
        if (isExpired(token.accessToken)) {
          sendMessageToBackground({ action: ApiActions.GET_REFRESH_TOKEN });
        } else {
          setAuthenticated(true);
        }
      } else {
        if (validateWithClearStorage) {
          clearStorage();
        }
        setAuthenticated(false);
      }
    });
  };

  const setIsAuthenticated = (isAuth: boolean) => {
    setAuthenticated(isAuth);
  };

  const clearStorage = () => {
    chrome?.storage.local.remove(['user', 'token']);
  };

  useEffect(() => {
    validate();
  }, []);

  return {
    authenticated,
    validate,
    clearStorage,
    setIsAuthenticated,
  };
};
