import { Box, CircularProgress, CircularProgressProps, Typography } from '@mui/material';
import { makeStyles } from 'tss-react/mui';

const PaiCircularProgress = (props: CircularProgressProps & { value: number }) => {
  const { classes } = useStyles();

  return (
    <Box className={classes.outerBox}>
      <CircularProgress className={classes.circle} variant="determinate" size={80} thickness={5} {...props} />
      <Box className={classes.innerBox}>
        <Typography className={classes.score} variant="caption" component="div">{`${Math.round(props.value)}%`}</Typography>
      </Box>
    </Box>
  );
};

const useStyles = makeStyles()((theme) => ({
  outerBox: {
    position: 'relative',
    display: 'inline-flex',
  },
  innerBox: {
    top: 0,
    left: 0,
    bottom: 0,
    right: 0,
    position: 'absolute',
    display: 'flex',
    alignItems: 'center',
    justifyContent: 'center',
  },
  circle: {
    color: theme.palette.primary.main,
  },
  score: {
    fontSize: '16px',
    fontWeight: 900,
  },
}));

export default PaiCircularProgress;
