import _ from 'lodash';

export const isLinkedIn = () => {
  return window.location.host.replace('www.', '').split('.')[0].toLowerCase() === 'linkedin';
};

export const getLinkedInHandle = (element: HTMLDivElement | HTMLTextAreaElement) => {
  return (
    element.closest('.msg-convo-wrapper')?.querySelector('a')?.href ||
    element.closest('.msg-overlay-conversation-bubble__content-wrapper')?.querySelector('a')?.href ||
    element.closest('#message-overlay')?.querySelector('.inbox__right-rail-container')?.querySelector('a')?.href ||
    element.closest('.message-overlay')?.querySelector('.inbox__right-rail-container')?.querySelector('a')?.href ||
    element.closest('.inbox-content')?.querySelector('.inbox__right-rail-container')?.querySelector('a')?.href ||
    element.closest('.conversation')?.querySelector('#thread-detail-jump-target')?.querySelector('a')?.href
  );
};

export const extractLinkedInMessageboxThreadId = (element: HTMLDivElement | HTMLTextAreaElement) => {
  const quotedthreadId = element
    .closest('.msg-convo-wrapper')
    ?.querySelector('.msg-s-event-listitem')
    ?.attributes?.getNamedItem('data-event-urn')
    ?.value?.split(':')
    .pop()
    ?.split(',')[0];
  const threadId = quotedthreadId?.substring(1);
  return threadId;
};

export const getLinkedInRecHandle = (document) => {
  return document.getElementById('thread-detail-jump-target')?.querySelector('a')?.href;
};

export const extractLinkedInUserName = (href: string) => {
  const currPath = href.split('/');
  let profileId = '';
  if (currPath[currPath.length - 1] !== '') {
    profileId = currPath[currPath.length - 1];
  } else {
    profileId = currPath[currPath.length - 2];
  }
  return profileId;
};

export const extractLinkedInSalesNavUserName = (href: string) => {
  const currPath = href.split('/');
  const profileId = currPath.pop();
  return profileId;
};

export const extractLinkedRecruiterUserName = (url: string) => {
  const profileIdMatch = url.match(/\/profile\/([^/?]+)/);

  if (!_.isNil(profileIdMatch)) {

    return profileIdMatch[1];
  } else {
    const currPath = url.split('/');
    const profileId = currPath.pop();

    if (
      profileId !== '' &&
      profileId !== 'requisition' &&
      profileId !== 'messages' &&
      profileId !== 'feedback' &&
      profileId !== 'attachments' &&
      profileId !== 'recruiting-activities'
    ) {

      return profileId;
    }

    return currPath[currPath.length - 2];
  }
};

export const isLinkedInUserPage = () => {
  return isLinkedIn() && window.location.pathname.split('/').includes('in');
};

export const isLinkedInSalesNavUserPage = () => {
  const locationSplit = window.location.pathname.split('/');
  return (
    isLinkedIn() &&
    !locationSplit.includes('lists') &&
    !locationSplit.includes('search') &&
    locationSplit.includes('sales') &&
    (locationSplit.includes('lead') || locationSplit.includes('people'))
  );
};

export const isLinkedInSalesNavSearchLeadsPage = () => {
  const locationSplit = window.location.pathname.split('/');
  return (
    isLinkedIn() &&
    !locationSplit.includes('lists') &&
    locationSplit.includes('search') &&
    locationSplit.includes('sales') &&
    locationSplit.includes('people')
  );
};

export const isLinkedInRecUserPage = () => {
  const locationSplit = window.location.pathname.split('/');
  return isLinkedIn() && !locationSplit.includes('lists') && locationSplit.includes('talent') && locationSplit.includes('profile');
};

export const isLinkedInSalesNavUserURL = (url) => {
  const locationSplit = url.split('/');
  return isLinkedIn() && locationSplit.includes('sales') && (locationSplit.includes('lead') || locationSplit.includes('people'));
};

export const isLinkedInRecUserURL = (url) => {
  const locationSplit = url.split('/');
  return isLinkedIn() && locationSplit.includes('talent') && locationSplit.includes('profile');
};

export const isLinkedInSalesNavThreadsPage = () => {
  const locationSplit = window.location.pathname.split('/');

  return isLinkedIn() && locationSplit.includes('sales') && locationSplit.includes('inbox');
};

export const isLinkedInRecThreadsPage = () => {
  const locationSplit = window.location.pathname.split('/');
  return isLinkedIn() && locationSplit.includes('talent') && locationSplit.includes('inbox') && !locationSplit.includes('profile');
};

export const isLinkedInRecComposePage = () => {
  const locationSplit = window.location.pathname.split('/');
  let isCompose = false;
  if (window.location.search !== '') {
    const searchParams = Object.fromEntries(new URLSearchParams(window.location.search).entries());
    if (searchParams.rightRail && searchParams.rightRail === 'composer') {
      isCompose = true;
    }
  }
  return isLinkedIn() && locationSplit.includes('talent') && isCompose && locationSplit.includes('profile');
};

export const isLinkedInThreadsPage = () => {
  return isLinkedIn() && window.location.pathname.split('/').includes('messaging');
};

export const isLinkedInFeedPage = () => {
  const locationSplit = window.location.pathname.split('/');
  return isLinkedIn() && (locationSplit.includes('feed') || locationSplit.includes('home'));
};

export const isRecruiter = () => {
  return isLinkedInRecComposePage() || isLinkedInRecThreadsPage() || isLinkedInRecUserPage();
};

export const isSalesNav = () => {
  return isLinkedInSalesNavThreadsPage() || isLinkedInSalesNavUserPage() || isLinkedInSalesNavSearchLeadsPage();
};

export const isNormalLinkedin = () => {
  return isLinkedInFeedPage() || isLinkedInThreadsPage() || isLinkedInUserPage();
};
