import { createTheme } from '@mui/material';
import { Theme } from '@mui/material/styles';

declare module '@mui/material/styles' {
  interface Palette {
    tertiary: Palette['primary'];
    neutral: Palette['primary'];
  }
  interface PaletteOptions {
    tertiary: PaletteOptions['primary'];
  }
}

const theme: Theme = createTheme({
  typography: {
    fontFamily: ['Roboto', 'Arial', 'sans-serif'].join(','),
  },
  palette: {
    primary: {
      main: '#0F87FF',
      contrastText: '#fff',
    },
    secondary: {
      main: '#FF9D00',
      contrastText: '#fff',
    },
    tertiary: {
      main: '#EDECFF',
      contrastText: '#fff',
    },
  },
});

export enum Colors {
  GREY_SHADE_1 = '#C9CCD3',
  GREY_SHADE_2 = '#E8EAED',
  GREY_SHADE_3 = '#E3E3E8',
  GREY_SHADE_4 = '#707070',
  GREY_SHADE_5 = 'rgba(0,0,0,0.38)',

  SUCCESS_GREEN = '#18C61F',

  ORANGE = '#FF9D00',
  MAGENTA = '#FE0970',
  PURPLE = '#7722FF',
  BLUE = '#4f44ff',
}

export enum Shadows {
  NORMAL_SHADOW = '0 4px 12px 0 rgba(0, 0, 0, 0.18)',
  BLUE_SHADOW = '1px 1px 5px 0 #0F87FF',
  ORANGE_SHADOW = '1px 1px 5px 0 #FF9D00',
  GREY_SHADOW = '5px 5px 10px 0px rgba(0, 0, 0, 0.2)',
}

export default theme;
