import { Stack, Typography } from '@mui/material';
import _ from 'lodash';
import React from 'react';
import Confetti from 'react-confetti';
import { useTranslation } from 'react-i18next';
import { makeStyles } from 'tss-react/mui';
import useProfileStore, { ProfileBases } from '../../../stores/profileStore';
import { Assessment } from '../../../types/assessment';
import { getIllustrationUrl } from '../../../utils/imageUtils';

interface Props {
  assessment: Assessment | undefined;
  showSuccess?: boolean;
}

const Persona: React.FC<Props> = ({ assessment, showSuccess }) => {
  const { classes, cx } = useStyles();
  const { t } = useTranslation();
  const contact = useProfileStore((state) => state.contact);

  const motiveIllustrationGenerator = () => {
    const motive = assessment?.name || '';
    const lowerCase = _.lowerCase(motive);
    const noGap = _.replace(lowerCase, ' ', '');

    return getIllustrationUrl(noGap);
  };

  return (
    <Stack gap={1}>
      <div className={classes.card}>
        <Typography className={classes.contactName}>
          {`${contact?.firstName || ''} ${contact?.lastName || ''}`}
          {contact?.basis === ProfileBases.EXACT || contact?.basis === ProfileBases.MATCHED ? <span>{' *'}</span> : null}
        </Typography>
        <Typography className={classes.occupation} textAlign={'center'}>
          {!_.isNil(contact?.occupation) ? `- ${contact?.occupation} -` : `- ${t('noProfession')} -`}
        </Typography>
        {contact?.basis === ProfileBases.EXACT || contact?.basis === ProfileBases.MATCHED ? (
          <Typography className={classes.profileInfo}>
            {t('profileInfo', { contactName: `${contact?.firstName || ''} ${contact?.lastName || ''}` })}
          </Typography>
        ) : null}
      </div>

      <div className={cx(classes.card, showSuccess ? classes.confettiContainer : null)} style={{ display: 'flex', justifyContent: 'center' }}>
        {showSuccess ? (
          <Confetti className={classes.confetti} numberOfPieces={5000} tweenDuration={125000} friction={1} gravity={0.08} recycle={false} />
        ) : null}
        <img className={classes.illustration} src={motiveIllustrationGenerator()} alt="motive illustration" />
      </div>
    </Stack>
  );
};

const useStyles = makeStyles()((theme) => ({
  card: {
    width: '100%',
    padding: '8px',
    height: 'calc(100% - 39px - 16px - 20px)',
    background: '#FFF',
  },
  confettiContainer: {
    width: '100%',
    position: 'relative',
    overflow: 'hidden',
  },
  contactName: {
    fontSize: '18px',
    fontWeight: 'bold',
    textAlign: 'center',
    marginBottom: '4px',
    textTransform: 'capitalize',
  },
  occupation: {
    width: '100%',
    fontSize: '12px',
    fontWeight: 900,
    color: theme.palette.primary.main,
  },
  illustration: {
    width: 'auto',
    maxHeight: '125px',
  },
  profileInfo: {
    fontSize: '9px',
    marginTop: '12px',
  },
  confetti: {
    width: '100%',
    height: '100%',
  },
}));

export default Persona;
