import { FormControl, FormControlLabel, Radio, RadioGroup, Stack, Typography } from '@mui/material';
import React, { useState } from 'react';
import { useTranslation } from 'react-i18next';
import { makeStyles } from 'tss-react/mui';
import i18n from '../../i18n';
import useLanguageStore, { UserLanguages } from '../../stores/languageStore';
import usePanelStore from '../../stores/panelStore';

const Languages: React.FC = () => {
  const { classes } = useStyles();
  const { t } = useTranslation();

  const setUserLanguage = useLanguageStore((state) => state.setUserLanguage);
  const userLanguage = useLanguageStore((state) => state.userLanguage);
  const setClickTrigger = usePanelStore((state) => state.setClickTrigger);

  const [selectedLanguage, setSelectedLanguage] = useState(userLanguage || i18n.languages[0]);

  const uiLanguages = [
    { key: 'de', text: t('german') },
    { key: 'en', text: t('english') },
  ];

  const selectedLanguageChange = (event: React.ChangeEvent<HTMLInputElement>) => {
    setSelectedLanguage(event.target.value);

    setUserLanguage(event.target.value as UserLanguages);
    i18n.changeLanguage(event.target.value);
    chrome.storage.local.set({ language: event.target.value });
    setClickTrigger(true);
  };

  return (
    <div className={classes.card}>
      <Typography className={classes.title}>{t('uiLanguage')}</Typography>
      <Stack direction={'row'} justifyContent={'center'}>
        <FormControl>
          <RadioGroup value={selectedLanguage} onChange={selectedLanguageChange} row={true}>
            {uiLanguages.map((lang, index) => (
              <FormControlLabel key={index} className={classes.radioLabel} value={lang.key} control={<Radio />} label={lang.text} />
            ))}
          </RadioGroup>
        </FormControl>
      </Stack>
    </div>
  );
};

const useStyles = makeStyles()((_theme) => ({
  card: {
    width: '100%',
    background: '#FFF',
    padding: '16px 8px 8px',
  },
  title: {
    fontSize: '12px',
    fontWeight: 900,
    textTransform: 'uppercase',
    textAlign: 'center',
    marginBottom: '12px',
  },
  radioLabel: {
    '& .MuiFormControlLabel-label': {
      fontSize: '11px',
    },
  },
}));

export default Languages;
