import { ButtonBase, Stack } from '@mui/material';
import { useTranslation } from 'react-i18next';
import { makeStyles } from 'tss-react/mui';
import { Genres } from '../../enums/enums';
import PaiButton from '../basic/PaiButton';
import PaiCheckbox from '../basic/PaiCheckBox';
import PaiMenuItem from '../basic/PaiMenuItem';
import PaiSelect from '../basic/PaiSelect';
import { BoosterProject } from './GenerateText';

interface Props {
  projects: BoosterProject[];

  genre: Genres | undefined;
  selectedLanguage: string;
  isFormal: boolean;
  includeEmoji: boolean;
  selectedProject: BoosterProject | null;

  createTextVariantStream(): void;

  selectedGenreChange(event: React.ChangeEvent<HTMLInputElement>): void;

  selectedProjectChange(event: React.ChangeEvent<HTMLInputElement>): void;

  handleCreateNewClick(): void;

  selectedLanguageChange(event: React.ChangeEvent<HTMLInputElement>): void;

  handleIsFormalChange(event: React.ChangeEvent<HTMLInputElement>): void;

  handleIncludeEmojiChange(event: React.ChangeEvent<HTMLInputElement>): void;
}

const FirstStepCreateFromExisting: React.FC<Props> = ({
  selectedProjectChange,
  projects,
  selectedProject,
  genre,
  selectedLanguage,
  isFormal,
  includeEmoji,
  createTextVariantStream,
  selectedGenreChange,
  handleCreateNewClick,
  selectedLanguageChange,
  handleIsFormalChange,
  handleIncludeEmojiChange,
}) => {
  const { t } = useTranslation();
  const { classes } = useStyles();

  const genres = [
    { key: Genres.CONNECTION_REQUEST, text: t('connectionRequestText') },
    { key: Genres.SALES_EMAIL, text: t('salesEmailsText') },
    { key: Genres.ACTIVE_SOURCING, text: t('activeSourcingText') },
  ];

  const textGenerationLanguages = [
    { key: 'auto-detect', text: t('autoDetect') },
    { key: 'de', text: t('german') },
    { key: 'en', text: t('english') },
    { key: 'it', text: t('italian') },
    { key: 'fr', text: t('french') },
    { key: 'es', text: t('spanish') },
    { key: 'pt', text: t('portuguese') },
  ];

  return (
    <Stack gap={2}>
      <PaiSelect value={genre ?? ''} label={t('typeOfText')} onChange={selectedGenreChange}>
        {genres.map((genre, index) => (
          <PaiMenuItem key={index} value={genre.key ?? ''}>
            {genre.text}
          </PaiMenuItem>
        ))}
      </PaiSelect>
      <PaiSelect value={selectedLanguage ?? ''} label={t('language')} onChange={selectedLanguageChange}>
        {textGenerationLanguages.map((lang, index) => (
          <PaiMenuItem key={index} value={lang.key ?? ''}>
            {lang.text}
          </PaiMenuItem>
        ))}
      </PaiSelect>
      <Stack direction={'row'} alignItems={'center'} justifyContent={'center'} gap={2} marginTop={'4px'}>
        <PaiCheckbox checked={isFormal} label={t('politeSpeech')} onChange={handleIsFormalChange} />
        <PaiCheckbox checked={includeEmoji} label={t('includeEmoji')} onChange={handleIncludeEmojiChange} />
      </Stack>
      <Stack gap={1.5}>
        <PaiSelect value={selectedProject?._id ?? ''} label={t('savedTextProjects')} onChange={selectedProjectChange}>
          {projects.map((project) => (
            <PaiMenuItem key={project._id} value={project._id ?? ''}>
              {project.projectName}
            </PaiMenuItem>
          ))}
        </PaiSelect>
        <ButtonBase className={classes.actionText} onClick={handleCreateNewClick}>
          {t('createNewTextProject')}
        </ButtonBase>
      </Stack>

      <PaiButton
        text={t('generateTextVariants')}
        action={createTextVariantStream}
        fullWidth={true}
        disabled={
          selectedProject?.problems?.trim() === '' || selectedProject?.offer?.trim() === '' || !genre || projects.length === 0 || !selectedProject
        }
      />
    </Stack>
  );
};

const useStyles = makeStyles()((theme) => ({
  actionText: {
    fontSize: '12px',
    alignSelf: 'flex-end',
    color: theme.palette.primary.main,
    textDecoration: 'underline',
    '&:hover': {
      color: theme.palette.secondary.main,
    },
  },
}));

export default FirstStepCreateFromExisting;
