import create from 'zustand';
import { BoosterProject } from '../components/textGeneration/GenerateText';
import { Genres } from '../enums/enums';

interface TextGenerationStoreState {
  generatedText: string;

  setGeneratedText: (newText: string) => void;

  textVariants: string[];

  addTextVariant: (newText: string) => void;

  resetTextVariants: () => void;

  genre: Genres;

  setGenre: (newGenre: Genres) => void;

  selectedLanguage: string;

  setSelectedLanguage: (newLanguage: string) => void;

  isFormal: boolean;

  setIsFormal: (newBool: boolean) => void;

  includeEmoji: boolean;

  setIncludeEmoji: (newBool: boolean) => void;

  selectedProject: BoosterProject | null;

  setSelectedProject: (newProject: BoosterProject | null) => void;

  createNew: boolean;

  setCreateNew: (newBool: boolean) => void;

  companyDescription: string;

  setCompanyDescription: (newText: string) => void;

  requirements: string;

  setRequirements: (newText: string) => void;

  tasks: string;

  setTasks: (newText: string) => void;

  whyYou: string;

  setWhyYou: (newText: string) => void;

  problems: string;

  setProblems: (newText: string) => void;

  features: string;

  setFeatures: (newText: string) => void;

  benefits: string;

  setBenefits: (newText: string) => void;

  impact: string;

  setImpact: (newText: string) => void;

  resetAllTextGeneration: () => void;
}

const useTextGenerationStore = create<TextGenerationStoreState>((set, get) => ({
  generatedText: '',

  setGeneratedText(newText: string) {
    set(() => ({ generatedText: newText }));
  },

  textVariants: [],

  addTextVariant(newText: string) {
    const state = get();
    const updateArray = state.textVariants;
    updateArray.push(newText);
    set(() => ({ textVariants: updateArray }));
  },

  resetTextVariants() {
    set(() => ({ textVariants: [] }));
  },

  genre: Genres.CONNECTION_REQUEST,

  setGenre(newGenre: Genres) {
    set(() => ({ genre: newGenre }));
  },

  selectedLanguage: 'auto-detect',

  setSelectedLanguage(newLanguage: string) {
    set(() => ({ selectedLanguage: newLanguage }));
  },

  isFormal: true,

  setIsFormal(newBool: boolean) {
    set(() => ({ isFormal: newBool }));
  },

  includeEmoji: false,

  setIncludeEmoji(newBool: boolean) {
    set(() => ({ includeEmoji: newBool }));
  },

  selectedProject: null,

  setSelectedProject(newProject: BoosterProject | null) {
    set(() => ({ selectedProject: newProject }));
  },

  createNew: false,

  setCreateNew(newBool) {
    set(() => ({ createNew: newBool }));
  },

  companyDescription: '',

  setCompanyDescription(newText: string) {
    set(() => ({ companyDescription: newText }));
  },

  requirements: '',

  setRequirements(newText: string) {
    set(() => ({ requirements: newText }));
  },

  tasks: '',

  setTasks(newText: string) {
    set(() => ({ tasks: newText }));
  },

  whyYou: '',

  setWhyYou(newText: string) {
    set(() => ({ whyYou: newText }));
  },

  problems: '',

  setProblems(newText: string) {
    set(() => ({ problems: newText }));
  },

  features: '',

  setFeatures(newText: string) {
    set(() => ({ features: newText }));
  },

  benefits: '',

  setBenefits(newText: string) {
    set(() => ({ benefits: newText }));
  },

  impact: '',

  setImpact(newText: string) {
    set(() => ({ impact: newText }));
  },

  resetAllTextGeneration() {
    set(() => ({
      generatedText: '',
      textVariants: [],
      genre: Genres.CONNECTION_REQUEST,
      selectedLanguage: 'auto-detect',
      isFormal: true,
      includeEmoji: false,
      selectedProject: null,
      createNew: false,
      companyDescription: '',
      requirements: '',
      tasks: '',
      whyYou: '',
      problems: '',
      features: '',
      benefits: '',
      impact: '',
    }));
  },
}));

export default useTextGenerationStore;
