import { Typography } from '@mui/material';
import React from 'react';
import { useTranslation } from 'react-i18next';
import { makeStyles } from 'tss-react/mui';
import { SideBarSelection } from '../../enums/enums';

const TextOptimizationInfo: React.FC = () => {
  const { classes } = useStyles();
  const { t } = useTranslation();

  return (
    <div className={classes.card}>
      <Typography className={classes.title} textTransform={'uppercase'}>
        {t(SideBarSelection.TEXT_OPTIMIZATION)}
      </Typography>
      <Typography className={classes.subTitle}>
        {t('textOptimizationInstruction')}
      </Typography>
    </div>
  );
};

const useStyles = makeStyles()((_theme) => ({
  card: {
    width: '100%',
    background: '#FFF',
    padding: '16px 16px 8px 16px',
  },
  title: {
    fontSize: '12px',
    fontWeight: 900,
    textTransform: 'uppercase',
    textAlign: 'center',
    marginBottom: '8px',
  },
  subTitle: {
    fontSize: '12px',
    textAlign: 'center',
  },
}));

export default TextOptimizationInfo;
